// Smart responder: if this is an event roster invite, call the specialized RPC
export async function respondAnyOwnerNotification(notificationRow, response /* 'yes' | 'no' */) {
  const id = notificationRow?.id || notificationRow;
  if (!id) throw new Error('Invalid notification');
  const kind = (notificationRow?.payload && (notificationRow.payload.kind || notificationRow.payload?.kind)) || null;
  const type = notificationRow?.type || null;
  // Prefer specialized responder for event roster invites; fall back to generic ACK on any error
  if (kind === 'event_roster_invite') {
    const { error } = await supabase.rpc('respond_event_roster_invite', { p_notification_id: id, p_response: response });
    if (!error) return;
    // Fallback if function missing or permission issue
    try { await respondOwnerNotification(id, response); return; } catch (_) { /* bubble below */ }
    throw new Error(error.message || 'Failed to respond to event invite');
  }
  if (type === 'resp_call') {
    const { error } = await supabase.rpc('respond_event_callout_notification', { p_notification_id: id, p_response: response });
    if (error) throw new Error(error.message);
    return;
  }
  // Generic ACK
  await respondOwnerNotification(id, response);
}

