export async function fetchGroupEvents(groupId, windowStartIso, windowEndIso, calIdsOverride) {
  const calIds = Array.isArray(calIdsOverride) ? calIdsOverride : (await listGroupCalendars(groupId)).map(c => c.id);
  const ownPromise = calIds.length ? supabase
    .from('events')
    .select('*')
    .in('calendar_id', calIds)
    .lte('dtstart', windowEndIso)
    .order('dtstart', { ascending: true })
    : Promise.resolve({ data: [], error: null });

  // Also include events this group has accepted invitations to (series-level)
  const { data: invited, error: errInv } = await supabase.rpc('list_group_invited_events', {
    p_group_id: groupId,
    p_window_start: windowStartIso || null,
    p_window_end: windowEndIso || null,
  });
  const { data: own, error } = await ownPromise;
  if (error) throw new Error(error.message);
  if (errInv) throw new Error(errInv.message);
  // Merge unique by event id
  const byId = new Map();
  (own || []).forEach(e => byId.set(e.id, e));
  (invited || []).forEach(e => byId.set(e.id, e));
  return Array.from(byId.values()).sort((a,b) => new Date(a.dtstart) - new Date(b.dtstart));
}

export async function fetchGroupOverrides(groupId, windowStartIso, windowEndIso, calIdsOverride) {
  const calIds = Array.isArray(calIdsOverride) ? calIdsOverride : (await listGroupCalendars(groupId)).map(c => c.id);
  // Pull overrides for events on these calendars; optionally filter by recurrence window
  const ownPromise = calIds.length ? supabase
    .from('event_overrides')
    .select('*, events!inner(calendar_id)')
    .in('events.calendar_id', calIds)
    .gte('recurrence_id', windowStartIso)
    .lte('recurrence_id', windowEndIso)
    : Promise.resolve({ data: [], error: null });

  // Also include overrides for events this group has accepted invitations to (series-level)
  const { data: invited, error: errInv } = await supabase.rpc('list_group_invited_overrides', {
    p_group_id: groupId,
    p_window_start: windowStartIso || null,
    p_window_end: windowEndIso || null,
  });
  const { data: own, error } = await ownPromise;
  if (error) throw new Error(error.message);
  if (errInv) throw new Error(errInv.message);
  // Strip the joined event for own overrides and merge
  const ownFlat = (own || []).map(({ events, ...rest }) => rest);
  const byKey = new Map(); // key parent_event_id + recurrence_id
  const keyOf = (r) => `${r.parent_event_id}|${new Date(r.recurrence_id).toISOString()}`;
  ownFlat.forEach(r => byKey.set(keyOf(r), r));
  (invited || []).forEach(r => byKey.set(keyOf(r), r));
  return Array.from(byKey.values());
}

