/**
 * Directly set RSVP (partstat) for an attendee owner on an event.
 * If an instance recurrence is provided and no instance attendee exists,
 * falls back to series-level attendee row.
 * After updating, clears any pending invite notifications for this event/owner
 * by recording a matching response.
 */
export async function setOwnerRSVPForEvent(eventId, recurrenceIdIso, ownerId, response /* 'yes' | 'no' */) {
  const part = response === 'yes' ? 'ACCEPTED' : 'DECLINED';
  // First, if there are pending roster invites for this scope, respond via RPC and return.
  // That RPC is authoritative and will upsert attendees appropriately, avoiding duplicate inserts.
  try {
    const [mine, teams] = await Promise.all([
      (await supabase.rpc('list_my_owner_notifications')).data || [],
      (await supabase.rpc('list_my_groups')).data || [],
    ]);
    const adminTeams = (teams||[]).filter(t => ['admin','manager'].includes(String(t.role||'').toLowerCase()));
    const groupNotifsNested = await Promise.all(adminTeams.map(async (t)=>{
      try { return (await supabase.rpc('list_group_notifications', { p_group_id: t.id })).data || []; } catch { return []; }
    }));
    const allNotifs = [...(mine||[]), ...groupNotifsNested.flat()];
    const baseIso = recurrenceIdIso ? new Date(recurrenceIdIso).toISOString() : null;
    const pending = allNotifs.filter(n => {
      if (n.ack_response) return false;
      const p = n.payload || {};
      if ((p.kind || p?.kind) !== 'event_roster_invite') return false;
      if (String(p.event_id || p.eventId) !== String(eventId)) return false;
      if (n.to_owner_id && String(n.to_owner_id) !== String(ownerId)) return false;
      const rid = p.recurrence_id || p.recurrenceId || '';
      if (baseIso && rid && new Date(rid).toISOString() !== baseIso) return false;
      if (baseIso && !rid) return false; // looking for instance-specific invite
      return true;
    });
    if (pending.length > 0) {
      for (const n of pending) {
        const { error } = await supabase.rpc('respond_owner_notification', { p_id: n.id, p_response: response });
        if (error) throw error;
      }
      return { updated: pending.length };
    }
  } catch (_) { /* fall through to direct upsert */ }

  // No pending invites matched; directly upsert attendees.
  let updated = 0;
  try {
    if (recurrenceIdIso) {
      // Ensure override row exists
      try { await upsertEventOverride(eventId, recurrenceIdIso, {}); } catch {}
      const { data: ovr } = await supabase
        .from('event_overrides')
        .select('id')
        .eq('parent_event_id', eventId)
        .eq('recurrence_id', recurrenceIdIso)
        .limit(1)
        .maybeSingle();
      if (ovr?.id) {
        // Update if exists
        const { error: errUp1, count } = await supabase
          .from('event_attendees')
          .update({ partstat: part })
          .eq('event_id', eventId)
          .eq('owner_id', ownerId)
          .eq('override_id', ovr.id)
          .select('id', { count: 'exact', head: true });
        if (errUp1) throw errUp1;
        updated += count || 0;
        if (updated === 0) {
          // Insert instance attendee (handle race duplicates gracefully)
          const { error: errIns1 } = await supabase
            .from('event_attendees')
            .insert({ event_id: eventId, override_id: ovr.id, owner_id: ownerId, partstat: part, rsvp: true });
          if (errIns1) {
            const msg = String(errIns1.message || '').toLowerCase();
            if (errIns1.code === '23505' || msg.includes('duplicate key') || msg.includes('unique constraint')) {
              // Row exists; update it instead
              const { error: errUpRetry, count: c2 } = await supabase
                .from('event_attendees')
                .update({ partstat: part })
                .eq('event_id', eventId)
                .eq('owner_id', ownerId)
                .eq('override_id', ovr.id)
                .select('id', { count: 'exact', head: true });
              if (errUpRetry) throw errUpRetry;
              updated += c2 || 1;
            } else {
              throw errIns1;
            }
          } else {
            updated += 1;
          }
        }
      }
    }
    if (updated === 0) {
      const { error: errUp2, count } = await supabase
        .from('event_attendees')
        .update({ partstat: part })
        .eq('event_id', eventId)
        .eq('owner_id', ownerId)
        .is('override_id', null)
        .select('id', { count: 'exact', head: true });
      if (errUp2) throw errUp2;
      updated += count || 0;
      if (updated === 0) {
        const { error: errIns2 } = await supabase
          .from('event_attendees')
          .insert({ event_id: eventId, owner_id: ownerId, partstat: part, rsvp: true });
        if (errIns2) {
          const msg = String(errIns2.message || '').toLowerCase();
          if (errIns2.code === '23505' || msg.includes('duplicate key') || msg.includes('unique constraint')) {
            // Row exists; update it instead
            const { error: errUpRetry2, count: c3 } = await supabase
              .from('event_attendees')
              .update({ partstat: part })
              .eq('event_id', eventId)
              .eq('owner_id', ownerId)
              .is('override_id', null)
              .select('id', { count: 'exact', head: true });
            if (errUpRetry2) throw errUpRetry2;
            updated += c3 || 1;
          } else {
            throw errIns2;
          }
        } else {
          updated += 1;
        }
      }
    }
  } catch (e) {
    throw new Error(e?.message || 'Failed to update RSVP');
  }

  return { updated };
}

