import { createClient } from "@supabase/supabase-js";
import { NEXT_PUBLIC_SUPABASE_URL as PUBLIC_URL, NEXT_PUBLIC_SUPABASE_ANON_KEY as PUBLIC_KEY } from "./publicEnv";

function isValidUrl(u) {
  try {
    if (!u || typeof u !== "string") return false;
    if (!/^https?:\/\//.test(u)) return false;
    new URL(u);
    return true;
  } catch {
    return false;
  }
}

const reactUrl = process.env.REACT_APP_SUPABASE_URL || "";
const reactKey = process.env.REACT_APP_SUPABASE_ANON_KEY || "";

// Prefer NEXT_PUBLIC_* if valid, otherwise fall back to REACT_APP_* if valid
const resolvedUrl = isValidUrl(PUBLIC_URL) ? PUBLIC_URL : (isValidUrl(reactUrl) ? reactUrl : "");
const resolvedKey = PUBLIC_KEY || reactKey || "";

if (!isValidUrl(PUBLIC_URL) && isValidUrl(reactUrl)) {
  // eslint-disable-next-line no-console
  console.warn("Falling back to REACT_APP_SUPABASE_URL due to invalid NEXT_PUBLIC_SUPABASE_URL", { PUBLIC_URL, reactUrl });
}
if (!PUBLIC_KEY && reactKey) {
  // eslint-disable-next-line no-console
  console.warn("Falling back to REACT_APP_SUPABASE_ANON_KEY (NEXT_PUBLIC_SUPABASE_ANON_KEY missing)");
}

function makeStub() {
  const notConfigured = () => ({ data: null, error: { message: 'Supabase not configured' } });
  // Minimal thenable PostgREST-style builder that swallows any chain and resolves to notConfigured
  const makeBuilder = () => {
    const builder = {
      select() { return builder; },
      update() { return builder; },
      insert() { return builder; },
      delete() { return builder; },
      upsert() { return builder; },
      order() { return builder; },
      eq() { return builder; },
      in() { return builder; },
      lte() { return builder; },
      gte() { return builder; },
      lt() { return builder; },
      gt() { return builder; },
      single() { return builder; },
      then(resolve) { try { resolve(notConfigured()); } catch {} },
      catch() { return builder; },
      finally() { return builder; },
    };
    return builder;
  };
  return {
    auth: {
      getSession: async () => ({ data: { session: null }, error: { message: 'Supabase not configured' } }),
      onAuthStateChange: () => ({ data: { subscription: { unsubscribe() {} } } }),
      signInWithPassword: async () => notConfigured(),
      signUp: async () => notConfigured(),
      resetPasswordForEmail: async () => notConfigured(),
      updateUser: async () => notConfigured(),
      signOut: async () => ({ error: null }),
    },
    from: () => makeBuilder(),
    rpc: async () => notConfigured(),
  };
}

export const SUPABASE_ENV_OK = isValidUrl(resolvedUrl) && !!resolvedKey;
export const RESOLVED_SUPABASE_URL = resolvedUrl;
export const supabase = SUPABASE_ENV_OK
  ? createClient(resolvedUrl, resolvedKey, { auth: { persistSession: true, autoRefreshToken: true } })
  : makeStub();
