import { useEffect, useMemo, useState } from 'react';
import { useLocation } from 'react-router-dom';
import ErrorBoundary from 'components/ErrorBoundary';
import RightPanelUpdates from './RightPanelUpdates';
import RightPanelMembers from './RightPanelMembers';
import RightPanelCalendar from './RightPanelCalendar';
import RightGroupAdmin from 'teams/components/RightGroupAdmin';
import { listMyTeams } from 'teams/teams.api';
import IdPeek from 'components/IdPeek';

export default function RightPanelHub() {
  const location = useLocation();
  const { view, groupId } = useMemo(() => {
    try {
      const sp = new URLSearchParams(location.search || '');
      const v = (sp.get('rpanel') || '').toLowerCase();
      const gid = sp.get('team') || null;
      const allowed = new Set(['updates','members','calendar','admin']);
      const safe = allowed.has(v) ? v : null;
      return { view: safe, groupId: gid };
    } catch { return { view: null, groupId: null }; }
  }, [location.search]);

  if (!view || !groupId) return null;

  const [teamLabel, setTeamLabel] = useState('');
  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const list = await listMyTeams();
        if (!active) return;
        const t = (list || []).find(x => String(x.id) === String(groupId));
        setTeamLabel(t ? (t.name || t.group_name || t.display_id || '') : '');
      } catch {}
    })();
    return () => { active = false; };
  }, [groupId]);

  return (
    <div className="overflow-auto max-h-[calc(100vh-120px)] pr-2">
      {teamLabel && (
        <div className="mb-3 text-xs opacity-80">
          Working on: <span className="font-semibold">{teamLabel}</span> <IdPeek id={groupId} />
        </div>
      )}
      {view === 'updates' && (
        <ErrorBoundary name="RightPanel-UpdatesNew">
          <RightPanelUpdates groupId={groupId} />
        </ErrorBoundary>
      )}
      {view === 'members' && (
        <ErrorBoundary name="RightPanel-MembersNew">
          <RightPanelMembers groupId={groupId} />
        </ErrorBoundary>
      )}
      {view === 'calendar' && (
        <ErrorBoundary name="RightPanel-CalendarNew">
          <RightPanelCalendar groupId={groupId} />
        </ErrorBoundary>
      )}
      {view === 'admin' && (
        <ErrorBoundary name="RightPanel-AdminNew">
          <div className="border border-white/10 rounded-xl p-3 bg-card/70">
            <RightGroupAdmin groupId={groupId} />
          </div>
        </ErrorBoundary>
      )}
    </div>
  );
}
