import { useEffect, useState, useMemo } from 'react';
import { listPublicGroupsByType } from 'teams/teams.api';
import { InfoText } from 'components/ui';

const TYPE_KEYS = ['act','practice_group','school','theatre','producer'];

export default function PublicGroupSummaryPanel({ groupId }) {
  const [group, setGroup] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const lists = await Promise.all(TYPE_KEYS.map(k => listPublicGroupsByType(k).catch(()=>[])));
        const merged = lists.flat();
        const match = merged.find(g => String(g.group_id || g.display_id) === String(groupId));
        if (active) setGroup(match || null);
      } finally { if (active) setLoading(false); }
    })();
    return () => { active = false; };
  }, [groupId]);

  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (!group) return <div style={{ opacity: 0.75 }}>Group not found.</div>;

  const name = group.name || '(group)';
  const types = Array.isArray(group.types) ? group.types : [];

  return (
    <div>
      <div style={{ fontWeight: 700, fontSize: 18 }}>{name}</div>
      <InfoText style={{ marginTop: 2 }}>Public group</InfoText>
      {types.length > 0 && (
        <div style={{ display:'flex', gap:6, flexWrap:'wrap', marginTop: 6 }}>
          {types.map(t => (
            <span key={t} style={{ border:'1px solid rgba(255,255,255,0.2)', borderRadius:999, padding:'2px 8px', fontSize:12 }}>{t}</span>
          ))}
        </div>
      )}
      {group.website && (
        <div style={{ marginTop: 8 }}>
          Website: <a href={/^https?:\/\//.test(group.website) ? group.website : `http://${group.website}`} target="_blank" rel="noreferrer" style={{ color:'#7aa2ff' }}>{group.website}</a>
        </div>
      )}
      {group.bio && (
        <div style={{ marginTop: 8, whiteSpace:'pre-wrap', opacity:0.9 }}>{group.bio}</div>
      )}
    </div>
  );
}

