// src/teams/hooks/useCalendarData.js
import { useCallback, useEffect, useMemo, useState } from "react";
import {
  fetchGroupEvents,
  fetchGroupOverrides,
  createGroupEvent,
  updateEvent,
  listOrphanedEventInstances,
  updateEventAndPrune,
  deleteEvent,
  upsertEventOverride,
  deleteEventOverrideRPC,
  listGroupCalendars,
} from "../teams.api";
import { expandEvents, expandBaseOccurrences } from "../../calendar/expandOccurrences";

const VISIBILITY_PUBLIC = "public";
const VISIBILITY_PRIVATE = "private";

const ensureExtended = (ext) => (ext && typeof ext === "object" ? ext : {});

const deriveCategory = (eventRow = {}, ext = {}) => {
  const fromExt = typeof ext.category === "string" ? ext.category.trim().toLowerCase() : "";
  if (fromExt) return fromExt;
  if (Array.isArray(eventRow.categories) && eventRow.categories.length) {
    const raw = eventRow.categories[0];
    if (typeof raw === "string" && raw.trim()) return raw.trim().toLowerCase();
  }
  if (typeof eventRow.category === "string" && eventRow.category.trim()) {
    return eventRow.category.trim().toLowerCase();
  }
  return "rehearsal";
};

const deriveVisibility = (ext) => {
  const obj = ensureExtended(ext);
  const raw = obj.visibility;
  if (typeof raw === "string") {
    const val = raw.toLowerCase();
    if (val === VISIBILITY_PUBLIC) return VISIBILITY_PUBLIC;
    if (val === VISIBILITY_PRIVATE) return VISIBILITY_PRIVATE;
  }
  if (Object.prototype.hasOwnProperty.call(obj, "is_public")) {
    return obj.is_public ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
  }
  return VISIBILITY_PRIVATE;
};

const cloneExtended = (ext) => {
  const obj = ensureExtended(ext);
  return JSON.parse(JSON.stringify(obj));
};

export default function useCalendarData(teamId, windowStartIso, windowEndIso) {
  const [events, setEvents] = useState([]);
  const [overrides, setOverrides] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");

  const inflight = useMemo(() => ({ v: 0 }), []);
  const load = useCallback(async () => {
    if (!teamId) return;
    setLoading(true); setErr("");
    try {
      const myTicket = ++inflight.v;
      const cals = await listGroupCalendars(teamId);
      const calIds = (cals || []).map(c => c.id);
      const [ev, ov] = await Promise.all([
        // Includes own events and events accepted by the group
        fetchGroupEvents(teamId, windowStartIso, windowEndIso, calIds),
        // Includes overrides from own calendars and for accepted events
        fetchGroupOverrides(teamId, windowStartIso, windowEndIso, calIds),
      ]);
      // Discard out-of-order responses
      if (myTicket !== inflight.v) return;
      // Normalize prototype events to legacy-friendly shape expected by CalendarPanel
      const norm = (ev || []).map(e => {
        const ext = ensureExtended(e.extended);
        const visibility = deriveVisibility(ext);
        const category = deriveCategory(e, ext);
        return {
          ...e,
          extended: ext,
          // legacy-friendly aliases for series editing UI
          starts_at: e.dtstart,
          ends_at: e.dtend,
          tz: e.tzid || 'UTC',
          title: e.summary || '',
          description: e.description || '',
          location: e.location || '',
          category,
          status: e.status || 'TENTATIVE',
          visibility,
          is_public: visibility === VISIBILITY_PUBLIC,
        };
      });
      setEvents(norm);
      setOverrides(ov);
    } catch (e) {
      setErr(e.message || "Failed to load calendar");
    } finally {
      setLoading(false);
    }
  }, [teamId, windowStartIso, windowEndIso]);

  useEffect(() => { load(); }, [load]);

  const occurrences = useMemo(() => {
    const merged = expandEvents({ events, overrides, windowStart: windowStartIso, windowEnd: windowEndIso, capPerEvent: 12 });
    // Adapt to legacy consumer shape for CalendarPanel
    return merged.map(m => {
      const overrideExt = ensureExtended(m.override && m.override.extended);
      const seriesExt = ensureExtended(m.event && m.event.extended);
      const useOverrideExt = m.override && Object.keys(overrideExt).length > 0;
      const activeExt = useOverrideExt ? overrideExt : seriesExt;
      const visibility = deriveVisibility(activeExt);
      const category = (() => {
        const overrideCat = typeof overrideExt.category === 'string' && overrideExt.category.trim()
          ? overrideExt.category.trim().toLowerCase()
          : '';
        if (overrideCat) return overrideCat;
        return deriveCategory(m.event, seriesExt);
      })();
      return {
        event_id: m.eventId,
        base_start: m.recurrence_id,
        starts_at: m.start ? new Date(m.start).toISOString() : m.recurrence_id,
        ends_at: m.end ? new Date(m.end).toISOString() : null,
        title: (m.override && m.override.summary) || (m.event && m.event.summary) || '',
        description: (m.override && m.override.description) || (m.event && m.event.description) || '',
        location: (m.override && m.override.location) || (m.event && m.event.location) || '',
        tz: (m.override && m.override.tzid) || (m.event && m.event.tzid) || 'UTC',
        overridden: !!m.override,
        status: (m.override && m.override.status) || (m.event && m.event.status) || 'TENTATIVE',
        override_status: m.override ? (m.override.status || null) : null,
        series_status: m.event ? (m.event.status || null) : null,
        override_extended: overrideExt,
        series_extended: seriesExt,
        extended: activeExt,
        visibility,
        is_public: visibility === VISIBILITY_PUBLIC,
        category,
      };
    });
  }, [events, overrides, windowStartIso, windowEndIso]);

  // Mutations
  const createBase = async (payload) => {
    const ext = (() => {
      const base = cloneExtended(payload.extended);
      if (typeof base.visibility === 'string') {
        base.visibility = base.visibility.toLowerCase() === VISIBILITY_PUBLIC ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
      }
      if (typeof base.is_public !== 'boolean') {
        base.is_public = base.visibility === VISIBILITY_PUBLIC;
      }
      if (typeof base.visibility !== 'string') {
        base.visibility = base.is_public ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
      }
      if (!Object.prototype.hasOwnProperty.call(base, 'category')) {
        base.category = (payload.category || '').toLowerCase() || 'rehearsal';
      }
      return base;
    })();
    const status = (payload.status || 'TENTATIVE').toUpperCase();

    const e = await createGroupEvent(teamId, {
      summary: payload.title,
      description: payload.description,
      location: payload.location,
      tzid: payload.tz,
      dtstart: payload.starts_at,
      dtend: payload.ends_at,
      rrule: (() => {
        // Compose a minimal RRULE from legacy fields
        const freq = (payload.recur_freq || 'none').toUpperCase();
        if (freq === 'NONE') return null;
        const parts = [ `FREQ=${freq}` ];
        if (payload.recur_interval && Number(payload.recur_interval) > 1) parts.push(`INTERVAL=${Number(payload.recur_interval)}`);
        if (payload.recur_byday && Array.isArray(payload.recur_byday) && payload.recur_byday.length) parts.push(`BYDAY=${payload.recur_byday.join(',')}`);
        if (payload.recur_bymonthday && Array.isArray(payload.recur_bymonthday) && payload.recur_bymonthday.length) parts.push(`BYMONTHDAY=${payload.recur_bymonthday.join(',')}`);
        if (payload.recur_week_of_month && payload.recur_day_of_week) parts.push(`BYDAY=${payload.recur_week_of_month}${payload.recur_day_of_week}`);
        if (payload.recur_until) parts.push(`UNTIL=${new Date(payload.recur_until).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/, 'Z')}`);
        if (payload.recur_count) parts.push(`COUNT=${payload.recur_count}`);
        return parts.join(';');
      })(),
      category: payload.category,
      status,
      extended: ext,
    });
    await load();
    return e;
  };
  const updateBase = async (eventId, patch) => {
    // Build patch for server
    const serverPatch = {
      summary: patch.title,
      description: patch.description,
      location: patch.location,
      tzid: patch.tz,
      dtstart: patch.starts_at,
      dtend: patch.ends_at,
      rrule: patch.recur_freq ? (()=>{
        const freq = (patch.recur_freq || 'none').toUpperCase();
        if (freq === 'NONE') return null;
        const parts = [ `FREQ=${freq}` ];
        if (patch.recur_interval && Number(patch.recur_interval) > 1) parts.push(`INTERVAL=${Number(patch.recur_interval)}`);
        if (patch.recur_byday && Array.isArray(patch.recur_byday) && patch.recur_byday.length) parts.push(`BYDAY=${patch.recur_byday.join(',')}`);
        if (patch.recur_bymonthday && Array.isArray(patch.recur_bymonthday) && patch.recur_bymonthday.length) parts.push(`BYMONTHDAY=${patch.recur_bymonthday.join(',')}`);
        if (patch.recur_week_of_month && patch.recur_day_of_week) parts.push(`BYDAY=${patch.recur_week_of_month}${patch.recur_day_of_week}`);
        if (patch.recur_until) parts.push(`UNTIL=${new Date(patch.recur_until).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/, 'Z')}`);
        if (patch.recur_count) parts.push(`COUNT=${patch.recur_count}`);
        return parts.join(';');
      })() : undefined,
      category: patch.category,
    };
    if (Array.isArray(patch.staff_defaults)) {
      serverPatch.staff_defaults = patch.staff_defaults;
    }
    if (Object.prototype.hasOwnProperty.call(patch, 'status')) {
      serverPatch.status = (patch.status || 'TENTATIVE').toUpperCase();
    }

    const current = events.find(ev => ev.id === eventId);
    let extendedOverride = patch.extended ? cloneExtended(patch.extended) : undefined;

    const wantsVisibility = typeof patch.visibility === 'string';
    const wantsIsPublic = Object.prototype.hasOwnProperty.call(patch, 'is_public');
    if (wantsVisibility || wantsIsPublic) {
      const baseExt = current ? cloneExtended(current.extended) : {};
      const initial = extendedOverride ? { ...baseExt, ...extendedOverride } : baseExt;
      if (wantsVisibility) {
        const vis = patch.visibility.toLowerCase() === VISIBILITY_PUBLIC ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
        initial.visibility = vis;
        if (!wantsIsPublic) {
          initial.is_public = vis === VISIBILITY_PUBLIC;
        }
      }
      if (wantsIsPublic) {
        initial.is_public = !!patch.is_public;
        if (!wantsVisibility) {
          initial.visibility = patch.is_public ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
        }
      }
      extendedOverride = initial;
    }

    if (Object.prototype.hasOwnProperty.call(patch, 'category')) {
      const cat = (patch.category || '').toLowerCase();
      if (!extendedOverride) {
        extendedOverride = current ? cloneExtended(current.extended) : {};
      }
      if (cat) {
        extendedOverride.category = cat;
      } else {
        delete extendedOverride.category;
      }
    }

    if (extendedOverride) {
      serverPatch.extended = extendedOverride;
    }

    // Compute authoritative valid recurrence_id set (no time window), capped by server policy (12/12months)
    try {
      if (current) {
        const candidate = {
          ...current,
          dtstart: serverPatch.dtstart ?? current.dtstart,
          dtend: serverPatch.dtend ?? current.dtend,
          rrule: serverPatch.rrule === undefined ? current.rrule : serverPatch.rrule,
        };
        const start = new Date(candidate.dtstart);
        const windowStart = new Date(start.getTime() - 24*3600*1000);
        const windowEnd = new Date(start.getTime() + 370*24*3600*1000);
        const bases = expandBaseOccurrences(candidate, windowStart.toISOString(), windowEnd.toISOString(), { hardCap: 12, monthsLimit: 12 }) || [];
        const validRids = bases.map(b => new Date(b.recurrence_id).toISOString());

        // Ask server which instance data would be orphaned
        const orphans = await listOrphanedEventInstances(eventId, validRids);
        if (orphans.length > 0) {
          const count = orphans.length;
          const ok = window.confirm(`This change will remove ${count} edited occurrence(s). Proceed?`);
          if (ok) {
            const e = await updateEventAndPrune(eventId, serverPatch, validRids);
            await load();
            return e;
          }
        }
      }
    } catch (e) {
      console.warn('orphan preview failed, falling back to simple update', e);
    }

    // Fallback: simple update without pruning
    const e = await updateEvent(eventId, serverPatch);
    await load();
    return e;
  };
  const deleteBase = async (eventId) => {
    await deleteEvent(eventId);
    await load();
  };

  const editOccurrence = async (eventId, baseStartIso, patch) => {
    const payload = {};
    if (Object.prototype.hasOwnProperty.call(patch, 'title')) payload.summary = patch.title;
    if (Object.prototype.hasOwnProperty.call(patch, 'description')) payload.description = patch.description;
    if (Object.prototype.hasOwnProperty.call(patch, 'location')) payload.location = patch.location;
    if (Object.prototype.hasOwnProperty.call(patch, 'tz')) payload.tzid = patch.tz;
    if (Object.prototype.hasOwnProperty.call(patch, 'starts_at')) payload.dtstart = patch.starts_at;
    if (Object.prototype.hasOwnProperty.call(patch, 'ends_at')) payload.dtend = patch.ends_at;
    if (Object.prototype.hasOwnProperty.call(patch, 'status')) payload.status = (patch.status || 'TENTATIVE').toUpperCase();

    const currentOverride = overrides.find(ov => ov.parent_event_id === eventId && new Date(ov.recurrence_id).toISOString() === new Date(baseStartIso).toISOString());
    const parentEvent = events.find(ev => ev.id === eventId);

    let extendedOverride = patch.extended ? cloneExtended(patch.extended) : undefined;
    const wantsVisibility = typeof patch.visibility === 'string';
    const wantsIsPublic = Object.prototype.hasOwnProperty.call(patch, 'is_public');
    if (wantsVisibility || wantsIsPublic) {
      const baseExt = currentOverride
        ? cloneExtended(currentOverride.extended)
        : (parentEvent ? cloneExtended(parentEvent.extended) : {});
      const initial = extendedOverride ? { ...baseExt, ...extendedOverride } : baseExt;
      if (wantsVisibility) {
        const vis = patch.visibility.toLowerCase() === VISIBILITY_PUBLIC ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
        initial.visibility = vis;
        if (!wantsIsPublic) {
          initial.is_public = vis === VISIBILITY_PUBLIC;
        }
      }
      if (wantsIsPublic) {
        initial.is_public = !!patch.is_public;
        if (!wantsVisibility) {
          initial.visibility = patch.is_public ? VISIBILITY_PUBLIC : VISIBILITY_PRIVATE;
        }
      }
      extendedOverride = initial;
    }

    if (extendedOverride) {
      payload.extended = extendedOverride;
    }

    if (Array.isArray(patch.instance_staff)) {
      payload.instance_staff = patch.instance_staff;
    }

    await upsertEventOverride(eventId, baseStartIso, payload);
    await load();
  };
  const cancelOccurrence = async (eventId, baseStartIso) => {
    await upsertEventOverride(eventId, baseStartIso, { status: 'CANCELLED' });
    await load();
  };
  const clearOccurrenceOverride = async (eventId, baseStartIso) => {
    // Delete the override row entirely so the series values are authoritative.
    await deleteEventOverrideRPC(eventId, baseStartIso);
    await load();
  };

  return {
    loading, err, events, overrides, occurrences, reload: load,
    createBase, updateBase, deleteBase,
    editOccurrence, cancelOccurrence, clearOccurrenceOverride,
  };
}
