import { useEffect } from 'react';
import { useParams, useSearchParams, Outlet } from 'react-router-dom';
import TeamsPanel from 'teams/TeamsPanel';

export default function GroupsPage() {
  const { groupId } = useParams();
  const [sp] = useSearchParams();
  const tab = sp.get('tab') || null;
  // TeamsPanel handles initial selection if provided
  return (
    <>
      <TeamsPanel initialTeamId={groupId || null} initialTab={tab || null} />
      <Outlet />
    </>
  );
}
