// src/profile/ProfilePanel.jsx
import { useEffect, useState } from "react";
import { useAuth } from "auth/AuthContext";
import { supabase } from "lib/supabaseClient";
import { Label, Input, Button, ErrorText, InfoText, Row, Section } from "components/ui";
import { useToast } from "components/toast";
import { getMyOwnerProfile, updateMyOwnerProfile } from "teams/teams.api";

export default function ProfilePanel() {
  const { session, refreshUser } = useAuth();
  const { add: addToast } = useToast();
  const user = session?.user;

  // Source of truth = Auth display name (raw_user_meta_data.display_name)
  const currentDisplayName =
    user?.user_metadata?.display_name ||
    (user?.email ? user.email.split("@")[0] : "");

  const [name, setName] = useState(currentDisplayName);
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState("");
  const [msg, setMsg] = useState("");
  // Removed legacy coach/showrunner flags

  // Email change UI
  const [email, setEmail] = useState(user?.email || "");
  const [savingEmail, setSavingEmail] = useState(false);
  const [emailMsg, setEmailMsg] = useState("");
  const [emailErr, setEmailErr] = useState("");

  // Password change UI
  const [pw1, setPw1] = useState("");
  const [pw2, setPw2] = useState("");
  const [savingPw, setSavingPw] = useState(false);
  const [pwMsg, setPwMsg] = useState("");
  const [pwErr, setPwErr] = useState("");

  // Public profile (owner-level)
  const [username, setUsername] = useState("");
  const [publicListing, setPublicListing] = useState(false);
  const [baseUsername, setBaseUsername] = useState("");
  const [basePublic, setBasePublic] = useState(false);

  useEffect(() => {
    setName(currentDisplayName);
    setEmail(user?.email || "");
  }, [currentDisplayName]);

  // Load owner public profile
  useEffect(() => {
    (async () => {
      try {
        const p = await getMyOwnerProfile();
        const u = p?.display_id || "";
        const pub = !!p?.public_listing;
        setUsername(u);
        setPublicListing(pub);
        setBaseUsername(u);
        setBasePublic(pub);
      } catch (e) {
        // non-fatal
      }
    })();
  }, []);

  // Unified updater: updates only changed fields (display name, email, password)
  const saveAll = async () => {
    setErr(""); setMsg("");
    setEmailErr(""); setPwErr(""); setEmailMsg(""); setPwMsg("");
    // Determine changes
    const nameChanged = (name || "").trim() !== (currentDisplayName || "");
    const emailChanged = (email || "").trim() !== (user?.email || "");
    const pwChanged = !!pw1 || !!pw2;
    const usernameChanged = true; // always send to ensure sync if edited
    const publicChanged = true;   // checkbox state should be persisted when saving profile
    if (pwChanged) {
      if (!pw1 || pw1.length < 6) { setPwErr("Password must be at least 6 characters."); return; }
      if (pw1 !== pw2) { setPwErr("Passwords do not match."); return; }
    }
    if (!nameChanged && !emailChanged && !pwChanged && !usernameChanged && !publicChanged) return; // nothing to do

    setSaving(true);
    try {
      const attrs = {};
      if (nameChanged) attrs.data = { ...(attrs.data || {}), display_name: name.trim() };
      if (emailChanged) attrs.email = email.trim();
      if (pwChanged) attrs.password = pw1;
      const options = emailChanged ? { emailRedirectTo: (process.env.REACT_APP_REDIRECT_URL || (typeof window !== 'undefined' ? (window.location.origin + window.location.pathname) : "")) } : undefined;
      const { error } = await supabase.auth.updateUser(attrs, options);
      if (error) throw error;
      // Update owner public profile (unique ID + visibility)
      const clean = (s) => (s || '').trim();
      const id = clean(username) || null;
      if (id && !/^[a-zA-Z0-9_-]+$/.test(id)) {
        throw new Error('Username may only contain letters, numbers, dashes and underscores.');
      }
      try {
        await updateMyOwnerProfile({ display_id: id, public_listing: !!publicListing });
      } catch (e) {
        // bubble up meaningful message
        throw e;
      }
      await refreshUser();
      setMsg("Profile updated."); addToast('Profile updated.');
      if (pwChanged) { setPw1(""); setPw2(""); setPwMsg("Password updated."); }
      if (emailChanged) setEmailMsg("If required, check your inbox to confirm your new email.");
    } catch (e) {
      const msg = e?.message || 'Failed to update profile';
      setErr(msg); addToast(msg, 'error');
    } finally {
      setSaving(false);
    }
  };

  const DEFAULT_REDIRECT =
    process.env.REACT_APP_REDIRECT_URL ||
    (typeof window !== 'undefined' ? (window.location.origin + window.location.pathname) : "");

  const saveEmail = async () => {
    setEmailErr(""); setEmailMsg(""); setSavingEmail(true);
    try {
      const { error } = await supabase.auth.updateUser(
        { email: email.trim() },
        { emailRedirectTo: DEFAULT_REDIRECT }
      );
      setSavingEmail(false);
      if (error) setEmailErr(error.message || "Failed to update email");
      else {
        setEmailMsg("If required, check your inbox to confirm your new email.");
        await refreshUser();
      }
    } catch (e) {
      setSavingEmail(false);
      setEmailErr(e.message || "Failed to update email");
    }
  };

  const savePassword = async () => {
    setPwErr(""); setPwMsg("");
    if (!pw1 || pw1.length < 6) { setPwErr("Password must be at least 6 characters."); return; }
    if (pw1 !== pw2) { setPwErr("Passwords do not match."); return; }
    setSavingPw(true);
    try {
      const { error } = await supabase.auth.updateUser({ password: pw1 });
      setSavingPw(false);
      if (error) setPwErr(error.message || "Failed to update password");
      else {
        setPwMsg("Password updated.");
        setPw1(""); setPw2("");
      }
    } catch (e) {
      setSavingPw(false);
      setPwErr(e.message || "Failed to update password");
    }
  };

  return (
      <div>
      <Section title="Identity">
        <Label>
          Display name
          <Input value={name} onChange={(e)=>setName(e.target.value)} />
        </Label>
        <Label>
          Unique ID (username)
          <Input
            placeholder="e.g. alice-smith"
            value={username}
            onChange={(e)=> setUsername(e.target.value)}
            maxLength={32}
          />
        </Label>
        <Label>
          <span style={{ display:'inline-flex', alignItems:'center', gap:8 }}>
            <input type="checkbox" checked={!!publicListing} onChange={(e)=> setPublicListing(e.target.checked)} />
            <span>List my profile publicly</span>
          </span>
        </Label>
        <InfoText>
          Unique ID must be unique. Use letters, numbers, dashes and underscores only.
        </InfoText>
      </Section>

      {err && <ErrorText style={{ marginTop: 8 }}>{err}</ErrorText>}
      {msg && <InfoText style={{ marginTop: 8 }}>{msg}</InfoText>}

      <Section title="Email">
      <Label>
        Email address
        <Input type="email" value={email} onChange={(e)=>setEmail(e.target.value)} />
      </Label>
      {emailErr && <ErrorText>{emailErr}</ErrorText>}
      {emailMsg && <InfoText>{emailMsg}</InfoText>}
      </Section>

      <Section title="Password">
      <Label>
        New password
        <Input type="password" value={pw1} onChange={(e)=>setPw1(e.target.value)} minLength={6} />
      </Label>
      <Label>
        Confirm new password
        <Input type="password" value={pw2} onChange={(e)=>setPw2(e.target.value)} minLength={6} />
      </Label>
      {pwErr && <ErrorText>{pwErr}</ErrorText>}
      {pwMsg && <InfoText>{pwMsg}</InfoText>}
      </Section>

      <Row>
        <Button
          onClick={saveAll}
          disabled={saving || (
            (name || '').trim() === (currentDisplayName || '') &&
            (email || '').trim() === (user?.email || '') &&
            (!pw1 && !pw2) &&
            (username || '').trim() === (baseUsername || '') &&
            !!publicListing === !!basePublic
          )}
        >
          {saving ? 'Saving…' : 'Update profile'}
        </Button>
      </Row>
    </div>
  );
}
