import { NavLink, Outlet, useNavigate, useLocation } from 'react-router-dom';
import { signOut } from 'auth/auth.api';
import { useAuth } from 'auth/AuthContext';
import { Bell, Home, Users, Megaphone, List, Calendar as CalendarIcon, HelpCircle, User as UserIcon, ChevronsLeft, ChevronsRight } from 'lucide-react';
import { Sheet } from 'components/ui/sheet';
import EventPanel from 'app_pages/EventPanel';
import { useEffect, useMemo, useState } from 'react';
import GroupSummaryPanel from 'teams/components/GroupSummaryPanel';
import RightGroupPanel from 'teams/components/RightGroupPanel';
import OwnerSummaryPanel from 'owners/OwnerSummaryPanel';
import { Dropdown, DropdownTrigger, DropdownContent } from 'components/ui/dropdown';
import { listMyOwnerNotifications, dismissOwnerNotification } from 'teams/teams.api';
import CreateGroupPanel from 'teams/components/CreateGroupPanel';
import PublicGroupSummaryPanel from 'teams/components/PublicGroupSummaryPanel';
import ErrorBoundary from 'components/ErrorBoundary';
import DebugOverlay from 'components/DebugOverlay';
import RightPanelHub from 'components/rightpanel/RightPanelHub';

export default function AppShell() {
  const navigate = useNavigate();
  const location = useLocation();
  const { displayName, user } = useAuth();
  const [sidebarExpanded, setSidebarExpanded] = useState(false); // affects md breakpoint only

  const { isEventContext, groupId, createTeam, communityGroupId, userId, tab, rpanel, eventKey } = useMemo(() => {
    const p = location.pathname || '';
    const eventRoute = (/\/groups\/.+\/events\/.+/.test(p) || /\/events\/.+/.test(p));
    const gMatch = p.match(/\/groups\/([^\/]+)/);
    const sp = new URLSearchParams(location.search || '');
    const createTeam = sp.get('create') === 'team';
    const searchOwnGroupId = sp.get('team') || null;
    const communityGroupId = sp.get('group') || null;
    const userId = sp.get('user') || null;
    const rawTab = sp.get('tab') || 'updates';
    const rpanel = sp.get('rpanel') || null;
    const eventParam = sp.get('event') || null;
    const ridParam = sp.get('rid') || null;
    const cleanTab = (() => {
      try { return String(rawTab).split(/[?&]/)[0]; } catch { return 'updates'; }
    })();
    // Prefer explicit search param for own groups to keep main route at /groups
    const ownGroupFromPath = gMatch ? gMatch[1] : null;
    const groupId = searchOwnGroupId || ownGroupFromPath;
    const isEventContext = eventRoute || !!eventParam;
    const eventKey = eventParam ? `${eventParam}:${ridParam || ''}` : (eventRoute ? p : null);
    return { isEventContext, groupId, createTeam, communityGroupId, userId, tab: cleanTab, rpanel, eventKey };
  }, [location.pathname, location.search]);

  // Notifications
  const [notifs, setNotifs] = useState([]);
  const [notifsOpen, setNotifsOpen] = useState(false);
  const unread = (notifs || []).length;
  useEffect(() => {
    let mounted = true;
    (async () => {
      try { const rows = await listMyOwnerNotifications(); if (mounted) setNotifs(rows || []); } catch {}
    })();
    const t = setInterval(async () => {
      try { const rows = await listMyOwnerNotifications(); if (mounted) setNotifs(rows || []); } catch {}
    }, 60_000);
    return () => { mounted = false; clearInterval(t); };
  }, []);

  const LinkItem = ({ to, icon: Icon, label, end = false, collapsed = false }) => (
    <NavLink
      to={to}
      end={end}
      className={({ isActive }) => `flex items-center gap-2 px-3 py-2 rounded-lg border transition-colors ${
        isActive ? 'bg-white text-black border-white' : 'border-white/20 text-white hover:bg-white/10'
      }`}
      title={label || ''}
      aria-label={label || ''}
    >
      <Icon size={18} />
      <span className={`${collapsed ? 'hidden md:hidden lg:inline' : 'hidden md:inline'}`}>{label}</span>
    </NavLink>
  );

  const mdSidebarWidth = sidebarExpanded ? 'md:w-56' : 'md:w-16';
  const showLabels = sidebarExpanded; // on md
  const topBarPad = '';
  const topBarLeft = sidebarExpanded ? 'md:left-56 lg:left-60' : 'md:left-16 lg:left-60';
  return (
    <div className="min-h-screen bg-bg text-text">
      {(() => { try { const sp = new URLSearchParams(location.search || ''); return sp.get('debug') === '1' ? <DebugOverlay /> : null; } catch { return null; } })()}
      {/* Global header spans main+right; offset so it does not cover the sidebar */}
      <div className={`fixed top-0 left-0 right-0 z-50 px-4 py-3 flex items-center justify-between bg-bg/70 backdrop-blur ${topBarLeft}`}>
        <div className="hidden sm:block font-semibold text-xl md:text-2xl text-left">
          {(() => {
            const p = location.pathname || '/';
            if (p === '/' || p === '') return 'Dashboard';
            if (p.startsWith('/groups')) return 'Groups';
            if (p.startsWith('/community')) return 'Community';
            if (p.startsWith('/listings')) return 'Listings';
            if (p.startsWith('/calendar')) return 'Calendar';
            
            if (p.startsWith('/help')) return 'Help';
            if (p.startsWith('/profile')) return 'Profile';
            return 'ImprovHub';
          })()}
        </div>
        <div className="flex items-center gap-2">
          {/* Help icon in top-right */}
          <button
            className="p-2 rounded-lg border border-white/20 hover:bg-white/10"
            title="Help"
            aria-label="Help"
            onClick={() => navigate('/help')}
          >
            <HelpCircle size={18} />
          </button>
          <Dropdown open={notifsOpen} onOpenChange={setNotifsOpen}>
            {({ open, setOpen }) => (
              <>
                <DropdownTrigger asChild setOpen={setOpen}>
                  <button
                    className={`relative inline-flex items-center justify-center w-10 h-10 rounded-full border ${unread? 'border-white bg-white/10' : 'border-white/20 hover:bg-white/10'}`}
                    title="Notifications"
                  >
                    <Bell size={18} />
                    {unread > 0 && (
                      <span className="absolute -top-1 -right-1 inline-flex h-3.5 min-w-3.5 items-center justify-center rounded-full bg-red-500 text-[10px] leading-none px-1">{Math.min(unread,9)}</span>
                    )}
                  </button>
                </DropdownTrigger>
                <DropdownContent open={open} setOpen={setOpen} align="end">
                  <div className="text-sm opacity-80 mb-1">Notifications</div>
                  {(notifs || []).length === 0 ? (
                    <div className="text-xs opacity-70">No new notifications.</div>
                  ) : (
                    <div className="max-h-80 overflow-auto space-y-2">
                      {(() => {
                        try {
                          const byGroup = new Map();
                          (notifs || []).forEach((n) => {
                            const p = n.payload || {};
                            const gid = p.group_id || p.groupId || p.owner_id || null;
                            if (!gid) return;
                            const prev = byGroup.get(String(gid)) || { count:0, label: p.owner_label || p.group_name || p.group_display_id || String(gid) };
                            prev.count += 1;
                            byGroup.set(String(gid), prev);
                          });
                          const items = Array.from(byGroup.entries());
                          if (items.length) {
                            return (
                              <div className="border border-white/10 rounded p-2">
                                <div className="text-xs opacity-80 mb-1">Group updates</div>
                                <ul className="space-y-1">
                                  {items.map(([gid, info]) => (
                                    <li key={gid} className="flex items-center justify-between">
                                      <span className="text-xs">{info.label}</span>
                                      <button className="px-2 py-1 text-xs rounded border border-white/20 hover:bg-white/10"
                                        onClick={() => {
                                          try {
                                            const sp = new URLSearchParams(location.search || '');
                                            sp.set('team', gid);
                                            sp.set('rpanel', 'updates');
                                            navigate(`/groups?${sp.toString()}`);
                                            setNotifsOpen(false);
                                          } catch {}
                                        }}
                                      >{info.count} updates</button>
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            );
                          }
                        } catch {}
                        return null;
                      })()}
                      <ul className="space-y-1">
                        {notifs.map((n) => (
                          <li key={n.id} className="border border-white/10 rounded p-2">
                            <div className="text-sm font-medium mb-1">{n.title || n.type || 'Notification'}</div>
                            <div className="text-xs opacity-80 break-words">{n.message || JSON.stringify(n.payload || {})}</div>
                            <div className="flex gap-2 justify-end mt-2">
                              <button className="px-2 py-1 text-xs rounded border border-white/20 hover:bg-white/10" onClick={async ()=>{ try { await dismissOwnerNotification(n.id); setNotifs((arr)=>arr.filter(x=>x.id!==n.id)); } catch {} }}>Dismiss</button>
                            </div>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </DropdownContent>
              </>
            )}
          </Dropdown>
          <Dropdown>
            {({ open, setOpen }) => (
              <>
                <DropdownTrigger asChild setOpen={setOpen}>
                  <button
                    className="inline-flex items-center justify-center w-10 h-10 rounded-full border border-white/20 hover:bg-white/10"
                    title="Account"
                  >
                    <span className="text-sm font-semibold">
                      {(() => {
                        const name = (displayName || user?.email || '').trim();
                        if (!name) return '?';
                        const parts = name.split(/\s+/).filter(Boolean);
                        const two = (parts[0]?.[0] || '') + (parts[1]?.[0] || (parts[0]?.[1] || ''));
                        return two.toUpperCase();
                      })()}
                    </span>
                  </button>
                </DropdownTrigger>
                <DropdownContent open={open} setOpen={setOpen} align="end">
                  <div className="text-sm opacity-80 mb-1">Account</div>
                  <div className="flex flex-col gap-1">
                    <button className="text-left px-2 py-1 rounded hover:bg-white/10" onClick={() => { setOpen(false); navigate('/profile'); }}>Profile</button>
                    <button className="text-left px-2 py-1 rounded hover:bg-white/10" onClick={async () => { setOpen(false); try { await signOut(); } catch {} }}>Sign out</button>
                  </div>
                </DropdownContent>
              </>
            )}
          </Dropdown>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-[auto_minmax(0,1fr)_360px]">
        {/* Sidebar */}
        <aside className={`hidden md:flex md:flex-col gap-2 p-3 border-r border-white/10 sticky top-0 h-screen ${mdSidebarWidth} lg:w-60 z-60`}>
          <div className="mb-2 flex flex-col">
            <div className="text-xl font-semibold">
              <span className="hidden md:inline lg:hidden">IH</span>
              <span className="hidden lg:inline">ImprovHub</span>
            </div>
            <button
              className="mt-2 md:inline-flex lg:hidden p-2 rounded border border-white/20 hover:bg-white/10"
              onClick={() => setSidebarExpanded(v => !v)}
              title={sidebarExpanded ? 'Collapse' : 'Expand'}
            >
              {sidebarExpanded ? <ChevronsLeft size={16} /> : <ChevronsRight size={16} />}
            </button>
          </div>
          <nav className="flex flex-col gap-2">
            <LinkItem to="/" icon={Home} label="Dashboard" end collapsed={!showLabels} />
            <LinkItem to="/groups" icon={Users} label="Groups" collapsed={!showLabels} />
            <LinkItem to="/community" icon={Megaphone} label="Community" collapsed={!showLabels} />
            <LinkItem to="/listings" icon={List} label="Listings" collapsed={!showLabels} />
            <LinkItem to="/calendar" icon={CalendarIcon} label="Calendar" collapsed={!showLabels} />
            
          </nav>
          <div className="mt-auto" />
        </aside>

        {/* Main */}
        <main className="min-h-screen p-4 pb-20 md:pb-4 pt-16">
          <div className="mt-2">
            <ErrorBoundary name="Main-Outlet">
              <Outlet />
            </ErrorBoundary>
          </div>
        </main>

        {/* Right panel (hidden on mobile; shows contextual content) */}
        <aside className="hidden md:block p-4 pt-16">
          {rpanel ? (
            <RightPanelHub key={`${groupId || 'no-group'}-${rpanel}`} />
          ) : createTeam ? (
            <div>
              <div className="flex items-center justify-between mb-2">
                <div className="text-sm opacity-80">Create Group</div>
                <div />
              </div>
              <div className="overflow-auto max-h-[calc(100vh-120px)] pr-2">
                <ErrorBoundary name="RightPanel-CreateGroup">
                  <div className="border border-white/10 rounded-xl p-3 bg-card/70">
                    <CreateGroupPanel />
                  </div>
                </ErrorBoundary>
              </div>
            </div>
          ) : isEventContext ? (
            <div>
              <div className="overflow-auto max-h-[calc(100vh-120px)] pr-2">
                <ErrorBoundary name="RightPanel-Event">
                  <EventPanel key={eventKey || 'event'} />
                </ErrorBoundary>
              </div>
            </div>
          ) : userId ? (
            <div>
              <div className="flex items-center justify-between mb-2">
                <div className="text-sm opacity-80">User</div>
                <div />
              </div>
              <div className="overflow-auto max-h-[calc(100vh-120px)] pr-2">
                <ErrorBoundary name="RightPanel-Owner">
                  <div className="border border-white/10 rounded-xl p-3 bg-card/70">
                    <OwnerSummaryPanel ownerId={userId} />
                  </div>
                </ErrorBoundary>
              </div>
            </div>
          ) : communityGroupId ? (
            <div>
              <div className="overflow-auto max-h-[calc(100vh-120px)] pr-2">
                <ErrorBoundary name="RightPanel-CommunityGroup">
                  <div className="border border-white/10 rounded-xl p-3 bg-card/70">
                    <PublicGroupSummaryPanel groupId={communityGroupId} />
                  </div>
                </ErrorBoundary>
              </div>
            </div>
          ) : null}
        </aside>
      </div>

      {/* Mobile bottom sheet for contextual routes (events, groups, create) */}
      <div className="md:hidden">
        <Sheet
          open={Boolean(isEventContext || groupId || createTeam || communityGroupId || userId || rpanel)}
          onOpenChange={(v) => {
            if (!v) {
              try {
                const sp = new URLSearchParams(location.search || '');
                ['rpanel','team','group','user','create','tab','event','rid'].forEach(k => sp.delete(k));
                navigate(`${location.pathname}?${sp.toString()}`);
              } catch { navigate(-1); }
            }
          }}
        >
          <div className="p-4 overflow-auto h-full">
            {rpanel ? (
              <>
                {/* No extra modal header; content handles its own headings */}
                <RightPanelHub key={`${groupId || 'no-group'}-${rpanel}`} />
              </>
            ) : createTeam ? (
              <>
                <div className="flex items-center justify-end mb-2">
                  <button className="px-3 py-2 rounded-lg border border-white/20" onClick={() => navigate('/groups')}>Close</button>
                </div>
                <CreateGroupPanel />
              </>
            ) : isEventContext ? (
              <>
                <div className="flex items-center justify-end mb-2">
                  <button
                    className="px-3 py-2 rounded-lg border border-white/20"
                    onClick={() => {
                      try {
                        const sp2 = new URLSearchParams(location.search || '');
                        sp2.delete('event');
                        sp2.delete('rid');
                        const q = sp2.toString();
                        navigate(`${location.pathname}${q ? `?${q}` : ''}`, { replace: true });
                      } catch { navigate(-1); }
                    }}
                  >Close</button>
                </div>
                <EventPanel key={eventKey || 'event'} />
              </>
            ) : userId ? (
              <>
                <div className="flex items-center justify-end mb-2">
                  <button className="px-3 py-2 rounded-lg border border-white/20" onClick={() => navigate(-1)}>Close</button>
                </div>
                <OwnerSummaryPanel ownerId={userId} />
              </>
            ) : communityGroupId ? (
              <>
                <div className="flex items-center justify-end mb-2">
                  <button className="px-3 py-2 rounded-lg border border-white/20" onClick={() => navigate('/community')}>Close</button>
                </div>
                <PublicGroupSummaryPanel groupId={communityGroupId} />
              </>
            ) : null}
          </div>
        </Sheet>
      </div>

      {/* FABs */}
      <div className="fab-container">
        <button
          onClick={() => navigate('/groups?create=event')}
          className="rounded-full w-12 h-12 grid place-items-center bg-white text-black shadow border border-white/20"
          title="Add Event"
        >
          +
        </button>
        <button
          onClick={() => navigate('/groups?create=member')}
          className="rounded-full w-12 h-12 grid place-items-center bg-white text-black shadow border border-white/20"
          title="Add Member"
        >
          👤
        </button>
        <button
          onClick={() => navigate('/groups?create=team')}
          className="rounded-full w-12 h-12 grid place-items-center bg-white text-black shadow border border-white/20"
          title="Add Team"
        >
          🧩
        </button>
      </div>

      {/* Mobile bottom navigation bar */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 z-40 border-t border-white/10 bg-bg/95 backdrop-blur px-2 py-2">
        <div className="grid grid-cols-5 gap-1">
          <NavLink
            to="/"
            end
            className={({ isActive }) => `flex flex-col items-center justify-center gap-1 py-2 rounded-md ${isActive ? 'text-white bg-white/10' : 'text-white/80 hover:bg-white/5'}`}
          >
            <Home size={18} />
            <span className="text-[10px]">Home</span>
          </NavLink>
          <NavLink
            to="/groups"
            className={({ isActive }) => `flex flex-col items-center justify-center gap-1 py-2 rounded-md ${isActive ? 'text-white bg-white/10' : 'text-white/80 hover:bg-white/5'}`}
          >
            <Users size={18} />
            <span className="text-[10px]">Groups</span>
          </NavLink>
          <NavLink
            to="/community"
            className={({ isActive }) => `flex flex-col items-center justify-center gap-1 py-2 rounded-md ${isActive ? 'text-white bg-white/10' : 'text-white/80 hover:bg-white/5'}`}
          >
            <Megaphone size={18} />
            <span className="text-[10px]">Community</span>
          </NavLink>
          <NavLink
            to="/listings"
            className={({ isActive }) => `flex flex-col items-center justify-center gap-1 py-2 rounded-md ${isActive ? 'text-white bg-white/10' : 'text-white/80 hover:bg-white/5'}`}
          >
            <List size={18} />
            <span className="text-[10px]">Listings</span>
          </NavLink>
          
        </div>
      </nav>
    </div>
  );
}
