import React from 'react';

export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null, info: null };
  }
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    try {
      // Log rich details to console for diagnostics
      // Include a tag so users can filter
      // eslint-disable-next-line no-console
      console.error('[ErrorBoundary]', this.props.name || 'Boundary', error, info);
    } catch {}
    this.setState({ error, info });
  }
  render() {
    const { error, info } = this.state;
    const { children } = this.props;
    if (!error) return children;
    return (
      <div style={{ border:'1px solid rgba(255,255,255,0.2)', borderRadius: 10, padding: 12, background: 'rgba(20,20,26,0.9)', color:'#fff' }}>
        <div style={{ fontWeight: 700, marginBottom: 6 }}>Something went wrong{this.props.name ? ` in ${this.props.name}` : ''}.</div>
        <pre style={{ whiteSpace:'pre-wrap', fontSize: 12, opacity: 0.9 }}>{String(error?.stack || error)}</pre>
        {info?.componentStack && (
          <pre style={{ whiteSpace:'pre-wrap', fontSize: 11, opacity: 0.7, marginTop: 8 }}>{info.componentStack}</pre>
        )}
      </div>
    );
  }
}
