import { useLocation } from 'react-router-dom';

export default function DebugOverlay() {
  const location = useLocation();
  const sp = new URLSearchParams(location.search || '');
  const p = location.pathname || '';
  const data = {
    pathname: p,
    search: location.search || '',
    groupId: (p.match(/\/groups\/([^\/]+)/) || [])[1] || null,
    tab: sp.get('tab') || null,
    user: sp.get('user') || null,
    create: sp.get('create') || null,
    communityGroup: sp.get('group') || null,
  };
  return (
    <div style={{ position:'fixed', bottom: 12, left: 12, zIndex: 9999, maxWidth: 360 }}>
      <div style={{ background:'rgba(20,20,26,0.95)', border:'1px solid rgba(255,255,255,0.25)', borderRadius:8, padding:12, color:'#fff', fontSize:12 }}>
        <div style={{ fontWeight:700, marginBottom:6 }}>Debug</div>
        <pre style={{ margin:0, whiteSpace:'pre-wrap' }}>{JSON.stringify(data, null, 2)}</pre>
      </div>
    </div>
  );
}

