// src/eventui/SeriesOverviewPanel.jsx
import { useEffect, useMemo, useState } from 'react';
import { Card, GhostButton, Row, Button, Chip } from 'components/ui';
import { useToast } from 'components/toast';
import { useAuth } from 'auth/AuthContext';
import { fmtRangeLocal, browserTZ, toLocalInput } from 'teams/utils/datetime';
import { parseRRule } from 'calendar/expandOccurrences';
import {
  getEventById,
  updateEvent,
  getCalendarOwnerInfo,
  listMyTeams,
  getOwnerForGroup,
  getOwnerForUser,
  getEventStaffDefaults,
  setEventStaffDefaults,
  listEventSlotsSeries,
  setEventSlotsSeries,
  listGroupStaffCandidates,
  listPublicStaffGroups,
  resolveOwnerByUserId,
  resolveOwnerByDisplayId,
  getEventCallouts,
  getEventCalloutResponses,
  respondEventCalloutResponse,
  clearEventCalloutInterest,
  getEventAttendeesSeries,
  listGroupOutgoingInvites,
  inviteOwnerToEvent,
  setOwnerRSVPForEvent,
} from 'teams/teams.api';

function cap(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }

export default function SeriesOverviewPanel({ eventId, onClose, inline = false }) {
  const { add: addToast } = useToast();
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');
  const [eventRow, setEventRow] = useState(null);
  const [ownerInfo, setOwnerInfo] = useState(null);
  const [myOwnerId, setMyOwnerId] = useState(null);
  const [actTeams, setActTeams] = useState([]); // teams I admin/manager

  // Inline edit state (mirror EventOverviewPanel basic fields)
  const [curTitle, setCurTitle] = useState('');
  const [curDesc, setCurDesc] = useState('');
  const [curStartIso, setCurStartIso] = useState(null);
  const [curEndIso, setCurEndIso] = useState(null);
  const [curLocation, setCurLocation] = useState('');
  const [curStatus, setCurStatus] = useState('TENTATIVE');
  const [editTitle, setEditTitle] = useState(false);
  const [editWhen, setEditWhen] = useState(false);
  const [editDesc, setEditDesc] = useState(false);
  const [editLocation, setEditLocation] = useState(false);
  const [editStatus, setEditStatus] = useState(false);
  const [busy, setBusy] = useState(false);

  // Recurrence UI state
  const [recMode, setRecMode] = useState('none'); // 'none'|'until'|'count'
  const [recFreq, setRecFreq] = useState('weekly'); // 'weekly'|'monthly'
  const [recInterval, setRecInterval] = useState(1);
  const [recByDay, setRecByDay] = useState(['MO']); // weekly
  const [recByMonthDay, setRecByMonthDay] = useState(null); // monthly by monthday
  const [recWeekOfMonth, setRecWeekOfMonth] = useState(null); // monthly ordinal, e.g., 1,2,3,4,-1
  const [recOrdinalWeekday, setRecOrdinalWeekday] = useState('MO'); // ordinal weekday
  const [recUntilDate, setRecUntilDate] = useState('');
  const [recCount, setRecCount] = useState(6);
  // Production: roster defaults and running order (series)
  const [seriesStaff, setSeriesStaff] = useState([]); // [{ owner_id, role, billing_name, billing_ord, notes }]
  const [seriesSlots, setSeriesSlots] = useState([]); // [{ slot_id?, name, offset_sec, duration_sec }]
  const [prodBusy, setProdBusy] = useState(false);
  const [staffCandidates, setStaffCandidates] = useState([]);
  const [dragRosterIdx, setDragRosterIdx] = useState(null);
  const [dragSlotIdx, setDragSlotIdx] = useState(null);
  const [addingRoster, setAddingRoster] = useState(false);
  const [query, setQuery] = useState("");
  const [selOwner, setSelOwner] = useState("");
  const [selRole, setSelRole] = useState('performer');
  const [billingName, setBillingName] = useState('');
  const [addErr, setAddErr] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const seriesRosterTimer = useMemo(() => ({ t: null }), []);
  const seriesSlotsTimer = useMemo(() => ({ t: null }), []);
  const [callouts, setCallouts] = useState([]);
  const [calloutResponses, setCalloutResponses] = useState([]);
  const [calloutBusy, setCalloutBusy] = useState(false);
  const [calloutErr, setCalloutErr] = useState('');
  const [seriesStaffSeed, setSeriesStaffSeed] = useState([]);
  const [seriesSlotsSeed, setSeriesSlotsSeed] = useState([]);
  const [prodReady, setProdReady] = useState(false);
  const [slotEdit, setSlotEdit] = useState({ idx: -1, field: '' });
  const [seriesAttendees, setSeriesAttendees] = useState(new Map());
  const [seriesPendingInvites, setSeriesPendingInvites] = useState(new Set());
  const [authorityOwnerIds, setAuthorityOwnerIds] = useState(new Set());

  const tz = useMemo(() => eventRow?.tzid || browserTZ() || 'UTC', [eventRow?.tzid]);

  // Permissions
  const canManage = useMemo(() => {
    try {
      if (!ownerInfo) return false;
      // group owner: admin/manager of that group
      if (ownerInfo.owner_kind === 'group') {
        const gid = String(ownerInfo.group_id || '');
        return (actTeams || []).some(t => String(t.groupId) === gid);
      }
      // individual owner: if I'm the owner
      return myOwnerId && String(myOwnerId) === String(ownerInfo.owner_id);
    } catch { return false; }
  }, [ownerInfo, actTeams, myOwnerId]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true); setErr('');
      try {
        const ev = await getEventById(eventId);
        if (!mounted) return;
        setEventRow(ev || null);
        setCurTitle(ev?.summary || '');
        setCurDesc(ev?.description || '');
        setCurStartIso(ev?.dtstart || null);
        setCurEndIso(ev?.dtend || null);
        setCurLocation(ev?.location || '');
        setCurStatus(String(ev?.status || 'TENTATIVE').toUpperCase());
        let calInfo = null;
        if (ev?.calendar_id) {
          try { calInfo = await getCalendarOwnerInfo(ev.calendar_id); if (mounted) setOwnerInfo(calInfo || null); } catch { if (mounted) setOwnerInfo(null); }
        } else { setOwnerInfo(null); }

        // Prefill recurrence from RRULE
        try {
          const rule = parseRRule(ev?.rrule || '');
          if (!rule || !rule.freq || rule.freq === 'NONE') {
            setRecMode('none');
          } else {
            if (rule.count) { setRecMode('count'); setRecCount(Math.max(1, Math.min(12, Number(rule.count) || 6))); }
            else if (rule.until) { const d = new Date(rule.until); if (!isNaN(+d)) setRecMode('until'); setRecUntilDate(d.toISOString().slice(0,10)); }
            else { setRecMode('count'); setRecCount(6); }
            const f = rule.freq.toLowerCase();
            setRecFreq(f === 'monthly' ? 'monthly' : 'weekly');
            setRecInterval(Math.max(1, Number(rule.interval) || 1));
            if (f === 'weekly') {
              const by = Array.isArray(rule.byday) && rule.byday.length ? rule.byday : undefined;
              setRecByDay(by || [weekdayFromDate(ev?.dtstart)]);
            } else if (f === 'monthly') {
              if (Array.isArray(rule.bymonthday) && rule.bymonthday.length) {
                setRecByMonthDay(Number(rule.bymonthday[0]) || null);
              } else if (Array.isArray(rule.byday) && rule.byday.length) {
                const tok = String(rule.byday[0]);
                const m = tok.match(/(-?\d)([A-Z]{2})/);
                if (m) { setRecWeekOfMonth(parseInt(m[1], 10)); setRecOrdinalWeekday(m[2]); }
              }
            }
          }
        } catch {}
        // Load production data
        try {
          const staff = await getEventStaffDefaults(eventId);
          const mapped = (staff || []).map(r => ({ owner_id: r.owner_id, role: r.role, billing_name: r.billing_name || '', billing_ord: r.billing_ord || null, notes: r.notes || '' }));
          if (mounted) { setSeriesStaff(mapped); setSeriesStaffSeed(mapped); }
        } catch {}
        try {
          const slots = await listEventSlotsSeries(eventId);
          if (mounted) { setSeriesSlots(slots || []); setSeriesSlotsSeed(slots || []); }
        } catch {}
        // Load series attendees (RSVPs) for hiding invite buttons
        try {
          const atts = await getEventAttendeesSeries(eventId);
          if (mounted) {
            const m = new Map(); (atts||[]).forEach(a => m.set(a.owner_id, a.partstat));
            setSeriesAttendees(m);
          }
        } catch {}
        // Load pending outgoing invites for this series (group-only)
        try {
          if (calInfo?.owner_kind === 'group' && calInfo?.group_id) {
            const rows = await listGroupOutgoingInvites(calInfo.group_id);
            const set = new Set();
            (rows || []).forEach(n => {
              const p = n?.payload || {};
              if ((p.kind || p?.kind) === 'event_roster_invite' && (p.event_id === eventId || p.eventId === eventId)) {
                const rid = p.recurrence_id || '';
                if (!rid && n.to_owner_id) set.add(n.to_owner_id);
              }
            });
            if (mounted) setSeriesPendingInvites(set);
          } else { if (mounted) setSeriesPendingInvites(new Set()); }
        } catch { if (mounted) setSeriesPendingInvites(new Set()); }
        if (mounted) setProdReady(true);
        // Load callouts + responses
        try {
          const [statusRows, responseRows] = await Promise.all([
            getEventCallouts(eventId),
            getEventCalloutResponses(eventId),
          ]);
          if (mounted) { setCallouts(statusRows || []); setCalloutResponses(responseRows || []); }
        } catch (e) { if (mounted) { setCallouts([]); setCalloutResponses([]); setCalloutErr(e?.message || ''); } }
      } catch (e) {
        if (mounted) { setErr(e?.message || 'Failed to load event'); setEventRow(null); }
      } finally { if (mounted) setLoading(false); }

      // Teams for permission checks
      try {
        const teams = await listMyTeams();
        const mine = (teams||[]).filter(t => ['admin','manager'].includes(String(t.role||'').toLowerCase()));
        const pairs = await Promise.all(mine.map(async (t)=>{ try { return [t, await getOwnerForGroup(t.id)]; } catch { return [t, null]; }}));
        const perms = [];
        pairs.forEach(([team, oid]) => { if (oid) perms.push({ groupId: team.id, ownerId: oid }); });
        if (mounted) {
          setActTeams(perms);
          const set = new Set(perms.map(p => String(p.ownerId)));
          setAuthorityOwnerIds(set);
        }
      } catch { if (mounted) setActTeams([]); }
      try {
        const uid = user?.id || null;
        if (uid) {
          const oid = await getOwnerForUser(uid);
          if (mounted) setMyOwnerId(oid || null);
        }
      } catch { if (mounted) setMyOwnerId(null); }
    })();
    return () => { mounted = false; };
  }, [eventId, user?.id]);

  // Load staff candidates (group + public) for typeahead
  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const pub = await listPublicStaffGroups().catch(() => []);
        let groupRows = [];
        if (ownerInfo?.owner_kind === 'group' && ownerInfo?.group_id) {
          groupRows = await listGroupStaffCandidates(ownerInfo.group_id).catch(() => []);
        }
        // merge + dedupe by owner_id or display_id
        const mergedMap = new Map();
        [...(groupRows||[]), ...(pub||[])].forEach((c) => {
          if (!c) return;
          const key = c.owner_id ? `owner:${c.owner_id}` : (c.display_id ? `disp:${c.display_id}` : `name:${c.display_name||''}`);
          if (!mergedMap.has(key)) mergedMap.set(key, c);
        });
        const merged = Array.from(mergedMap.values());
        if (active) setStaffCandidates(merged);
      } catch { if (active) setStaffCandidates([]); }
    })();
    return () => { active = false; };
  }, [ownerInfo?.owner_kind, ownerInfo?.group_id]);

  const weekdayFromDate = (iso) => {
    try { const d = new Date(iso); const map = ['SU','MO','TU','WE','TH','FR','SA']; return map[d.getDay()] || 'MO'; } catch { return 'MO'; }
  };

  const headerRange = useMemo(() => {
    try { if (curStartIso && curEndIso) return fmtRangeLocal(curStartIso, curEndIso, tz); return curStartIso ? new Date(curStartIso).toLocaleString() : ''; } catch { return ''; }
  }, [curStartIso, curEndIso, tz]);

  const sectionStyle = { border:'1px solid rgba(255,255,255,0.12)', borderRadius:12, padding:14, background:'rgba(255,255,255,0.04)' };
  const statusMap = { CONFIRMED: 'Confirmed', CANCELLED: 'Cancelled', TENTATIVE: 'Tentative' };
  const statusLabel = statusMap[(curStatus || 'TENTATIVE').toUpperCase()] || cap(curStatus || 'Tentative');

  async function saveBasicPatch(patch) {
    if (!eventId) return;
    setBusy(true);
    try {
      await updateEvent(eventId, patch);
      try { window.dispatchEvent(new CustomEvent('improvhub:event-updated', { detail: { eventId, patch } })); } catch {}
    } catch (e) { addToast(e?.message || 'Failed to update', 'error'); }
    finally { setBusy(false); }
  }

  function composeRRule() {
    if (recMode === 'none') return null;
    const parts = [ `FREQ=${recFreq.toUpperCase()}` ];
    const n = Math.max(1, Number(recInterval) || 1);
    if (n > 1) parts.push(`INTERVAL=${n}`);
    if (recFreq === 'weekly') {
      const days = Array.isArray(recByDay) && recByDay.length ? recByDay : [weekdayFromDate(curStartIso)];
      parts.push(`BYDAY=${days.join(',')}`);
    } else if (recFreq === 'monthly') {
      if (recByMonthDay) {
        parts.push(`BYMONTHDAY=${recByMonthDay}`);
      } else if (recWeekOfMonth && recOrdinalWeekday) {
        parts.push(`BYDAY=${recWeekOfMonth}${recOrdinalWeekday}`);
      }
    }
    if (recMode === 'count') {
      const c = Math.max(1, Math.min(12, Number(recCount) || 6));
      parts.push(`COUNT=${c}`);
    } else if (recMode === 'until' && recUntilDate) {
      const untilIso = new Date(`${recUntilDate}T23:59:59`).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/, 'Z');
      parts.push(`UNTIL=${untilIso}`);
    }
    return parts.join(';');
  }

  async function saveRecurrence() {
    const rrule = composeRRule();
    await saveBasicPatch({ rrule });
    addToast('Recurrence updated.');
    try { window.dispatchEvent(new CustomEvent('improvhub:calendar-reload')); } catch {}
  }

  async function saveRoster() {
    if (!canManage) return;
    setProdBusy(true);
    try {
      const payload = (seriesStaff || []).map(r => ({ owner_id: r.owner_id, role: r.role, billing_name: r.billing_name || '', billing_ord: r.billing_ord || null, notes: r.notes || '' }));
      await setEventStaffDefaults(eventId, payload);
      addToast('Roster saved.');
      try { window.dispatchEvent(new CustomEvent('improvhub:calendar-reload')); } catch {}
    } catch(e) { addToast(e?.message || 'Failed to save roster', 'error'); }
    finally { setProdBusy(false); }
  }

  async function saveSlots() {
    if (!canManage) return;
    setProdBusy(true);
    try {
      const payload = (seriesSlots || []).map(s => ({ slot_id: s.slot_id || null, name: s.name || '', offset_sec: Math.max(0, Number(s.offset_sec)||0), duration_sec: Math.max(0, Number(s.duration_sec)||0), staff: Array.isArray(s.staff) ? s.staff : [] }));
      await setEventSlotsSeries(eventId, payload);
      addToast('Running order saved.');
      try { window.dispatchEvent(new CustomEvent('improvhub:calendar-reload')); } catch {}
    } catch(e) { addToast(e?.message || 'Failed to save running order', 'error'); }
    finally { setProdBusy(false); }
  }

  const ROLE_KINDS = ['performer','host','jammer','crew'];
  const suggestions = useMemo(() => {
    const trimmed = (query || '').trim().toLowerCase();
    if (!trimmed) return [];
    const nameMatch = (c) => (c.display_name||'').toLowerCase().includes(trimmed);
    const displayIdMatch = (c) => (c.display_id||'').toLowerCase().includes(trimmed);
    return (staffCandidates || []).filter(c => nameMatch(c) || displayIdMatch(c)).slice(0, 8);
  }, [query, staffCandidates]);

  async function addRosterLine() {
    try {
      setAddErr('');
      const q = (query || '').trim();
      if (!q && !selOwner && !billingName) { setAddErr('Enter a name or pick a suggestion'); return; }
      let ownerId = selOwner || null;
      if (!ownerId && q) {
        // Try resolve by display_id
        try {
          const oid = await resolveOwnerByDisplayId(q);
          if (oid) ownerId = oid;
        } catch {}
      }
      const display = billingName || q || 'Party';
      setSeriesStaff(prev => [...prev, { owner_id: ownerId, role: selRole, billing_name: display, billing_ord: (prev?.length||0)+1, notes:'' }]);
      // reset
      setAddingRoster(false); setSelOwner(''); setQuery(''); setBillingName(''); setShowSuggestions(false);
    } catch(e) { setAddErr(e?.message || 'Failed to add'); }
  }

  // Auto-save with debounce when roster changes
  useEffect(() => {
    if (!canManage || !eventId || !prodReady) return;
    const cur = JSON.stringify(seriesStaff);
    const seed = JSON.stringify(seriesStaffSeed);
    if (cur === seed) return; // no-op loaded state
    if (seriesRosterTimer.t) clearTimeout(seriesRosterTimer.t);
    seriesRosterTimer.t = setTimeout(async () => {
      await saveRoster();
      // update seed to current after save
      try { setSeriesStaffSeed(JSON.parse(JSON.stringify(seriesStaff))); } catch { setSeriesStaffSeed(seriesStaff); }
    }, 500);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify(seriesStaff), canManage, eventId, prodReady]);

  // Auto-save with debounce when slots change
  useEffect(() => {
    if (!canManage || !eventId || !prodReady) return;
    const cur = JSON.stringify(seriesSlots);
    const seed = JSON.stringify(seriesSlotsSeed);
    if (cur === seed) return;
    if (seriesSlotsTimer.t) clearTimeout(seriesSlotsTimer.t);
    seriesSlotsTimer.t = setTimeout(async () => {
      await saveSlots();
      try { setSeriesSlotsSeed(JSON.parse(JSON.stringify(seriesSlots))); } catch { setSeriesSlotsSeed(seriesSlots); }
    }, 500);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify(seriesSlots), canManage, eventId, prodReady]);

  const statusFor = (kind) => {
    const row = (callouts || []).find((c) => c.kind === kind);
    return { published: !!(row && row.published) };
  };
  const responsesFor = (kind) => (calloutResponses || []).filter((r) => r.kind === kind);

  async function handleResponse(responseId, resp) {
    if (!responseId) return;
    setCalloutBusy(true); setCalloutErr('');
    try {
      await respondEventCalloutResponse(responseId, resp);
      const [statusRows, responseRows] = await Promise.all([
        getEventCallouts(eventId),
        getEventCalloutResponses(eventId),
      ]);
      setCallouts(statusRows || []);
      setCalloutResponses(responseRows || []);
      // Refresh roster to reflect accepted additions
      try { const staff = await getEventStaffDefaults(eventId); setSeriesStaff((staff || []).map(r => ({ owner_id: r.owner_id, role: r.role, billing_name: r.billing_name || '', billing_ord: r.billing_ord || null, notes: r.notes || '' }))); } catch {}
    } catch (e) { setCalloutErr(e?.message || 'Failed to update'); }
    finally { setCalloutBusy(false); }
  }
  async function handleDismiss(responseId) {
    if (!responseId) return;
    setCalloutBusy(true); setCalloutErr('');
    try {
      await clearEventCalloutInterest(responseId);
      const rows = await getEventCalloutResponses(eventId);
      setCalloutResponses(rows || []);
    } catch (e) { setCalloutErr(e?.message || 'Failed to remove'); }
    finally { setCalloutBusy(false); }
  }

  if (!eventId) return null;

  // Inner content (match EventOverviewPanel structure when inline)
  const inner = (
    <>
        <div style={{ ...sectionStyle }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 16 }}>
            <div style={{ minWidth: 0 }}>
              <div style={{ fontWeight: 800, fontSize: 22, minHeight: 26 }}>
                {editTitle && canManage ? (
                  <input
                    autoFocus
                    value={curTitle}
                    onChange={(e)=> setCurTitle(e.target.value)}
                    onBlur={()=>{ saveBasicPatch({ summary: (curTitle||'').trim() || null }); setEditTitle(false); }}
                    onKeyDown={(e)=>{ if (e.key==='Enter') e.currentTarget.blur(); if (e.key==='Escape') setEditTitle(false); }}
                    style={{ width:'100%', background:'transparent', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px', fontSize:18 }}
                  />
                ) : (
                  <span title={canManage ? 'Click to rename series' : undefined} onClick={()=> { if (canManage) setEditTitle(true); }} style={{ cursor: canManage ? 'text' : 'default' }}>
                    {curTitle || '(untitled series)'}
                  </span>
                )}
              </div>
              <div style={{ fontSize: 14, opacity: 0.9, marginTop: 4 }}>
                {editWhen && canManage ? (
                  <div style={{ display:'flex', gap:8, alignItems:'center', flexWrap:'wrap' }}>
                    <label style={{ fontSize:12, opacity:0.8 }}>Start
                      <input type="datetime-local" value={curStartIso ? toLocalInput(curStartIso) : ''}
                        onChange={(e)=>{ const v=e.target.value; setCurStartIso(v ? new Date(v).toISOString() : null); }}
                        style={{ marginLeft:6, background:'transparent', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'2px 6px' }} />
                    </label>
                    <label style={{ fontSize:12, opacity:0.8 }}>End
                      <input type="datetime-local" value={curEndIso ? toLocalInput(curEndIso) : ''}
                        onChange={(e)=>{ const v=e.target.value; setCurEndIso(v ? new Date(v).toISOString() : null); }}
                        style={{ marginLeft:6, background:'transparent', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'2px 6px' }} />
                    </label>
                    <Button style={{ padding:'2px 8px', fontSize:12 }} onClick={async()=>{
                      try {
                        if (!curStartIso || !curEndIso || new Date(curEndIso) <= new Date(curStartIso)) { addToast('End must be after start', 'error'); return; }
                        await saveBasicPatch({ dtstart: curStartIso, dtend: curEndIso });
                        addToast('Updated time');
                      } finally { setEditWhen(false); }
                    }}>Save</Button>
                    <GhostButton style={{ padding:'2px 8px', fontSize:12 }} onClick={()=> setEditWhen(false)}>Cancel</GhostButton>
                  </div>
                ) : (
                  <span title={canManage ? 'Click to edit start/end' : undefined} onClick={()=> { if (canManage) setEditWhen(true); }} style={{ cursor: canManage ? 'pointer' : 'default' }}>{headerRange}</span>
                )}
                {(() => {
                  const hasLoc = curLocation;
                  if (editLocation && canManage) {
                    return (
                      <>
                        {' · '}
                        <input autoFocus type="text" value={curLocation}
                          onChange={(e)=> setCurLocation(e.target.value)}
                          onBlur={()=>{ saveBasicPatch({ location: (curLocation || null) }); setEditLocation(false); }}
                          onKeyDown={(e)=>{ if (e.key==='Enter') e.currentTarget.blur(); if (e.key==='Escape') setEditLocation(false); }}
                          placeholder="Add location…"
                          style={{ background:'transparent', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'2px 6px' }} />
                      </>
                    );
                  }
                  if (hasLoc) {
                    return (<>
                      {' · '}<a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(curLocation||'')}`} target="_blank" rel="noreferrer" style={{ color:'#93c5fd' }}>{curLocation}</a>
                    </>);
                  }
                  if (canManage) {
                    return (
                      <>
                        {' · '}
                        <span
                          title="Click to add location"
                          onClick={()=> setEditLocation(true)}
                          style={{ opacity:0.6, fontStyle:'italic', cursor:'text' }}
                        >Add location…</span>
                      </>
                    );
                  }
                  return null;
                })()}
              </div>
            </div>
            <div style={{ display:'flex', gap:6, flexWrap:'wrap', justifyContent:'flex-end' }}>
              {editStatus && canManage ? (
                <select value={curStatus} onChange={(e)=> setCurStatus(e.target.value)} onBlur={()=>{ saveBasicPatch({ status: curStatus }); setEditStatus(false); }} style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:999, padding:'4px 8px' }}>
                  <option value="CONFIRMED">Confirmed</option>
                  <option value="TENTATIVE">Tentative</option>
                  <option value="CANCELLED">Cancelled</option>
                </select>
              ) : (
                <span title={canManage ? 'Click to change status' : undefined} onClick={()=> { if (canManage) setEditStatus(true); }}
                  style={{ padding: '4px 8px', borderRadius: 999, fontSize: 12, cursor: canManage ? 'pointer' : 'default',
                    background: curStatus === 'CONFIRMED' ? 'rgba(52,211,153,0.18)' : (curStatus === 'CANCELLED' ? 'rgba(248,113,113,0.18)' : 'rgba(96,165,250,0.18)'),
                    color: curStatus === 'CONFIRMED' ? '#34d399' : (curStatus === 'CANCELLED' ? '#f87171' : '#60a5fa') }}
                >{statusLabel}</span>
              )}
              {(() => {
                // Category chip like EventOverviewPanel
                const ext = eventRow?.extended || {};
                const cat = (typeof ext.category === 'string' && ext.category.trim())
                  ? ext.category.trim().toLowerCase()
                  : (Array.isArray(eventRow?.categories) && eventRow.categories[0]) || '';
                if (!cat) return null;
                return (<Chip>{cap(cat)}</Chip>);
              })()}
              {canManage && (
                <span style={{ padding: '4px 8px', borderRadius: 999, fontSize: 12, fontWeight: 800,
                  background: 'rgba(52,211,153,0.18)', color:'#34d399' }}
                >Your Event</span>
              )}
            </div>
          </div>
          <div style={{ marginTop: 14, opacity: 0.95, lineHeight: 1.5 }}>
            {editDesc && canManage ? (
              <textarea autoFocus value={curDesc} onChange={(e)=> setCurDesc(e.target.value)}
                onBlur={()=>{ saveBasicPatch({ description: (curDesc||'') || null }); setEditDesc(false); }}
                onKeyDown={(e)=>{ if (e.key==='Escape') setEditDesc(false); }} rows={3}
                style={{ width:'100%', background:'transparent', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:8, padding:8, resize:'vertical' }} />
            ) : (
              <div title={canManage ? 'Click to edit description' : undefined} onClick={()=> { if (canManage) setEditDesc(true); }}
                style={{ cursor: canManage ? 'text' : 'default', opacity: (curDesc) ? 0.95 : 0.6, fontStyle: (curDesc) ? 'normal' : 'italic' }}>
                {curDesc || 'Add description…'}
              </div>
            )}
          </div>
        </div>

        {/* Recurrence controls */}
        <div style={{ ...sectionStyle, marginTop: 12 }}>
          <div style={{ fontWeight: 600, marginBottom: 6 }}>Recurrence</div>
          {!canManage && (<div style={{ fontSize: 12, opacity: 0.8 }}>You don’t have permission to edit series.</div>)}
          {canManage && (
            <div style={{ display:'grid', gap:10 }}>
              <div style={{ display:'flex', gap:14, alignItems:'center', flexWrap:'wrap' }}>
                <label style={{ display:'inline-flex', alignItems:'center', gap:8 }}>
                  <input type="radio" name={`rec_mode_${eventId||'series'}`} checked={recMode==='none'} onChange={()=> setRecMode('none')} />
                  <span>No recurrence</span>
                </label>
                <label style={{ display:'inline-flex', alignItems:'center', gap:8 }}>
                  <input type="radio" name={`rec_mode_${eventId||'series'}`} checked={recMode==='until'} onChange={()=> setRecMode('until')} />
                  <span>Repeat until</span>
                </label>
                {recMode==='until' && (
                  <input type="date" value={recUntilDate} onChange={(e)=> setRecUntilDate(e.target.value)}
                    style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }} />
                )}
                <label style={{ display:'inline-flex', alignItems:'center', gap:8 }}>
                  <input type="radio" name={`rec_mode_${eventId||'series'}`} checked={recMode==='count'} onChange={()=> setRecMode('count')} />
                  <span>Repeat N times</span>
                </label>
                {recMode==='count' && (
                  <input type="number" min={1} max={12} value={recCount}
                    onChange={(e)=> setRecCount(Math.max(1, Math.min(12, Number(e.target.value) || 1)))}
                    style={{ width:80, background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }} />
                )}
              </div>
              {recMode!=='none' && (
                <div style={{ display:'grid', gap:10 }}>
                  <div style={{ display:'flex', gap:8, alignItems:'center', flexWrap:'wrap' }}>
                    <span style={{ fontSize:12, opacity:0.8 }}>Every</span>
                    <input type="number" min={1} max={12} value={recInterval}
                      onChange={(e)=> setRecInterval(Math.max(1, Math.min(12, Number(e.target.value) || 1)))}
                      style={{ width:80, background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }} />
                    <select value={recFreq} onChange={(e)=> setRecFreq(e.target.value)}
                      style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }}>
                      <option value="weekly">week(s)</option>
                      <option value="monthly">month(s)</option>
                    </select>
                  </div>
                  {recFreq==='weekly' && (
                    <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
                      {['MO','TU','WE','TH','FR','SA','SU'].map((d) => {
                        const active = Array.isArray(recByDay) && recByDay.includes(d);
                        return (
                          <button key={d} type="button" onClick={()=>{
                            setRecByDay(prev => { const set = new Set(prev||[]); if (set.has(d)) set.delete(d); else set.add(d); const arr = Array.from(set); return arr.length ? arr : [weekdayFromDate(curStartIso)]; });
                          }}
                            style={{ fontSize:12, padding:'4px 6px', borderRadius:8, border:'1px solid rgba(255,255,255,0.3)', background: active ? 'rgba(255,255,255,0.18)' : 'transparent' }}
                          >{d}</button>
                        );
                      })}
                    </div>
                  )}
                  {recFreq==='monthly' && (
                    <div style={{ display:'flex', gap:12, flexWrap:'wrap', alignItems:'center' }}>
                      <label style={{ display:'inline-flex', alignItems:'center', gap:6 }}>
                        <span style={{ fontSize:12, opacity:0.8 }}>On day</span>
                        <input type="number" min={1} max={31} value={recByMonthDay || ''}
                          onChange={(e)=> { const v = Number(e.target.value) || null; setRecByMonthDay(v); if (v) { setRecWeekOfMonth(null); } }}
                          placeholder="e.g. 15"
                          style={{ width:100, background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }} />
                      </label>
                      <span style={{ opacity:0.7 }}>or</span>
                      <label style={{ display:'inline-flex', alignItems:'center', gap:6 }}>
                        <span style={{ fontSize:12, opacity:0.8 }}>On the</span>
                        <input type="number" min={-1} max={4} value={recWeekOfMonth || ''}
                          onChange={(e)=> { const v=Number(e.target.value)||null; setRecWeekOfMonth(v); if (v) { setRecByMonthDay(null); } }}
                          placeholder="1..4 or -1"
                          style={{ width:110, background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }} />
                        <select value={recOrdinalWeekday} onChange={(e)=> setRecOrdinalWeekday(e.target.value)}
                          style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px' }}>
                          {['MO','TU','WE','TH','FR','SA','SU'].map(d => (<option key={d} value={d}>{d}</option>))}
                        </select>
                      </label>
                    </div>
                  )}
                </div>
              )}
              <Row style={{ justifyContent:'flex-end', gap:8 }}>
                <Button disabled={busy} onClick={saveRecurrence}>Save Recurrence</Button>
                <GhostButton onClick={onClose}>Close</GhostButton>
              </Row>
            </div>
          )}
        </div>

        {/* Production (Roster & Running Order) */}
        <div style={{ ...sectionStyle, marginTop: 12 }}>
          <div style={{ fontWeight: 600, marginBottom: 6 }}>Production</div>
          {!canManage && (<div style={{ fontSize: 12, opacity: 0.8 }}>You don’t have permission to edit production.</div>)}
          {canManage && (
            <div style={{ display:'grid', gap:12 }}>
              <div>
                <div style={{ fontWeight: 600, marginBottom: 6 }}>Roster Defaults</div>
                <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:8 }}>
                  {(seriesStaff || []).map((r, idx) => (
                    <li key={`${r.owner_id || 'o'}:${idx}`}
                        draggable
                        onDragStart={()=> setDragRosterIdx(idx)}
                        onDragOver={(e)=> e.preventDefault()}
                        onDrop={()=>{
                          if (dragRosterIdx===null || dragRosterIdx===idx) return;
                          setSeriesStaff(prev => {
                            const arr = prev.slice();
                            const [m] = arr.splice(dragRosterIdx,1);
                            arr.splice(idx,0,m);
                            return arr;
                          });
                          setDragRosterIdx(null);
                        }}
                        style={{ display:'grid', gridTemplateColumns:'1fr auto auto', gap:8, alignItems:'center' }}>
                      <div style={{ overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>
                        {r.billing_name || 'Party'}
                        {r.owner_id ? null : <span style={{ opacity:0.6 }}> (unlinked)</span>}
                      </div>
                      <div style={{ fontSize:12, opacity:0.8 }}>{(r.role || 'performer').charAt(0).toUpperCase() + (r.role||'performer').slice(1)}</div>
                      <div style={{ display:'flex', gap:6, justifyContent:'flex-end', alignItems:'center' }}>
                        {r.owner_id && !seriesAttendees.has(r.owner_id) && !seriesPendingInvites.has(r.owner_id) && (
                          <GhostButton title="Invite" onClick={async ()=>{
                            try {
                              await inviteOwnerToEvent(eventId, r.owner_id);
                              addToast('Invite sent.');
                              // refresh attendees & mark pending
                              try {
                                const atts = await getEventAttendeesSeries(eventId);
                                const m = new Map(); (atts||[]).forEach(a=>m.set(a.owner_id,a.partstat));
                                setSeriesAttendees(m);
                              } catch{}
                              setSeriesPendingInvites(prev => { const s = new Set(prev); s.add(r.owner_id); return s; });
                            } catch(e){ addToast(e?.message || 'Invite failed', 'error'); }
                          }} style={{ padding:'2px 6px' }}>✉️</GhostButton>
                        )}
                        {(() => {
                          // Status chip at series level
                          const part = seriesAttendees.get(r.owner_id) || (seriesPendingInvites.has(r.owner_id) ? 'NEEDS-ACTION' : null);
                          if (!part) return null;
                          const label = part === 'ACCEPTED' ? 'Accepted'
                            : part === 'DECLINED' ? 'Declined'
                            : part === 'NEEDS-ACTION' ? 'Needs action'
                            : (part === 'TENTATIVE' ? 'Tentative' : null);
                          if (!label) return null;
                          const color = part === 'ACCEPTED' ? '#34d399'
                            : part === 'DECLINED' ? '#f87171'
                            : part === 'NEEDS-ACTION' ? '#fbbf24'
                            : '#60a5fa';
                          return (
                            <span style={{ border:`1px solid ${color}`, color, borderRadius:12, padding:'2px 6px', fontSize:11 }}>{label}</span>
                          );
                        })()}
                        {(() => {
                          // Series-level RSVP controls for applicable owners (self/authority groups)
                          const isApplicable = (
                            (myOwnerId && String(r.owner_id) === String(myOwnerId)) ||
                            authorityOwnerIds.has(String(r.owner_id))
                          );
                          if (!isApplicable) return null;
                          const p = seriesAttendees.get(r.owner_id) || (seriesPendingInvites.has(r.owner_id) ? 'NEEDS-ACTION' : null);
                          if (!p) return null;
                          const showAccept = p !== 'ACCEPTED';
                          const showDecline = p !== 'DECLINED';
                          return (
                            <>
                              {showAccept && (
                                <Button style={{ padding:'2px 6px', fontSize:11 }}
                                  onClick={async()=>{
                                    try { await setOwnerRSVPForEvent(eventId, null, r.owner_id, 'yes'); addToast('RSVP accepted.');
                                      const atts = await getEventAttendeesSeries(eventId); const m = new Map(); (atts||[]).forEach(a=>m.set(a.owner_id,a.partstat)); setSeriesAttendees(m);
                                    } catch(e){ addToast(e?.message || 'Failed to respond', 'error'); }
                                  }}
                                >Accept</Button>
                              )}
                              {showDecline && (
                                <GhostButton style={{ padding:'2px 6px', fontSize:11 }}
                                  onClick={async()=>{
                                    try { await setOwnerRSVPForEvent(eventId, null, r.owner_id, 'no'); addToast('RSVP declined.');
                                      const atts = await getEventAttendeesSeries(eventId); const m = new Map(); (atts||[]).forEach(a=>m.set(a.owner_id,a.partstat)); setSeriesAttendees(m);
                                    } catch(e){ addToast(e?.message || 'Failed to respond', 'error'); }
                                  }}
                                >Decline</GhostButton>
                              )}
                            </>
                          );
                        })()}
                        <GhostButton title="Remove" onClick={()=> setSeriesStaff(prev => prev.filter((_,i)=> i!==idx))} style={{ padding:'2px 6px', color:'#f87171' }}>✖️</GhostButton>
                      </div>
                    </li>
                  ))}
                </ul>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginTop:8, gap:8 }}>
                  {!addingRoster ? (
                    <GhostButton onClick={()=> { setAddingRoster(true); setAddErr(''); }} style={{ padding:'2px 8px', fontSize:12 }}>+ Add party</GhostButton>
                  ) : (
                    <div style={{ display:'flex', gap:6, alignItems:'center', flexWrap:'wrap' }}>
                      <div style={{ position:'relative', minWidth:260 }}>
                        <input
                          placeholder="Type a name or group display ID"
                          value={query}
                          onChange={(e)=> { setQuery(e.target.value); setSelOwner(''); setAddErr(''); setShowSuggestions(true); }}
                          onFocus={()=> setShowSuggestions(true)}
                          onBlur={()=> setTimeout(()=> setShowSuggestions(false), 120)}
                          onKeyDown={async (e)=>{ if (e.key==='Enter') { e.preventDefault(); e.stopPropagation(); await addRosterLine(); }}}
                          style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px', minWidth:260, height:28 }}
                        />
                        {query.trim() && showSuggestions && (
                          <div style={{ position:'absolute', zIndex:20, background:'#0f0f14', border:'1px solid rgba(255,255,255,0.2)', borderRadius:8, marginTop:4, width:'100%' }}>
                            {suggestions.length === 0 && (
                              <div style={{ padding:'8px 10px', opacity:0.7 }}>No matches. Public groups show up by display ID.</div>
                            )}
                        {suggestions.map(s => (
                          <div key={s.owner_id || s.user_id}
                            style={{ padding:'6px 10px', borderBottom:'1px solid rgba(255,255,255,0.08)', display:'flex', alignItems:'center', justifyContent:'space-between', gap:8 }}>
                            <div onClick={async ()=>{ setQuery(s.display_name || s.display_id || ''); setAddErr(''); setShowSuggestions(false); if (s.owner_id) setSelOwner(s.owner_id); if (s.user_id) { try { const oid = await resolveOwnerByUserId(s.user_id); if (oid) setSelOwner(oid); } catch{} } }} style={{ cursor:'pointer' }}>
                              <div style={{ fontWeight:600 }}>{s.display_name} {s.kind==='group' ? '(group)' : ''}</div>
                              {s.display_id && (<div style={{ fontSize:12, opacity:0.75 }}>ID: {s.display_id}</div>)}
                            </div>
                            {/* Invite icon button */}
                            {/* Placeholder: Invite action can be wired if desired via inviteOwnerToEvent */}
                            <span title="Invite" style={{ opacity:0.8, cursor:'pointer' }} onClick={async (e)=>{ e.stopPropagation(); /* invitation could be triggered here if required */ }}>
                              ✉️
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                    {addErr && (<div style={{ color:'#ff6b6b', fontSize:12, marginTop:4 }}>{addErr}</div>)}
                  </div>
                      <select value={selRole} onChange={(e)=> setSelRole(e.target.value)} style={{ background:'#0f0f14', color:'inherit', border:'1px solid rgba(255,255,255,0.2)', borderRadius:6, padding:'4px 6px', height:28 }}>
                        {ROLE_KINDS.map(r => (<option key={r} value={r}>{r.charAt(0).toUpperCase()+r.slice(1)}</option>))}
                      </select>
                      <input
                        placeholder="Billing name (optional)"
                        value={billingName}
                        onChange={(e)=> setBillingName(e.target.value)}
                        style={{ background:'transparent', color:'inherit', border:'1px solid rgba(255,255,255,0.2)', borderRadius:6, padding:'4px 8px', fontSize:12, minWidth:180, height:28 }}
                      />
                      <GhostButton onClick={async ()=> { await addRosterLine(); }} style={{ padding:'2px 8px', fontSize:12, height:28 }}>Add</GhostButton>
                      <GhostButton onClick={()=> { setAddingRoster(false); setSelOwner(''); setQuery(''); setBillingName(''); setAddErr(''); }} style={{ padding:'2px 8px', fontSize:12, height:28 }}>Cancel</GhostButton>
                    </div>
                  )}
                  {/* Auto-saves; no explicit Save button needed */}
                </div>
              </div>

              <div>
                <div style={{ fontWeight: 600, marginBottom: 6 }}>Running Order (Series)</div>
                <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:8 }}>
                  {(seriesSlots || []).map((s, idx) => (
                    <li key={s.slot_id || `slot-${idx}`}
                        draggable
                        onDragStart={()=> setDragSlotIdx(idx)}
                        onDragOver={(e)=> e.preventDefault()}
                        onDrop={()=>{
                          if (dragSlotIdx===null || dragSlotIdx===idx) return;
                          setSeriesSlots(prev => {
                            const arr = prev.slice();
                            const [m] = arr.splice(dragSlotIdx,1);
                            arr.splice(idx,0,m);
                            return arr;
                          });
                          setDragSlotIdx(null);
                        }}
                        style={{ display:'grid', gridTemplateColumns:'1.4fr 1fr 1fr 1.6fr auto', gap:8, alignItems:'center' }}>
                      <div onClick={()=> setSlotEdit({ idx, field:'name' })} style={{ cursor:'text' }}>
                        {slotEdit.idx===idx && slotEdit.field==='name' ? (
                          <input autoFocus value={s.name || ''} onChange={(e)=>{
                            const v=e.target.value; setSeriesSlots(prev => prev.map((x,i)=> i===idx?{...x,name:v}:x));
                          }} onBlur={()=> setSlotEdit({ idx:-1, field:'' })}
                          style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px', width:'100%' }} />
                        ) : (
                          <span style={{ overflow:'hidden', whiteSpace:'nowrap', textOverflow:'ellipsis' }}>{s.name || 'Slot'}</span>
                        )}
                      </div>
                      <div onClick={()=> setSlotEdit({ idx, field:'offset' })} style={{ cursor:'text' }}>
                        {slotEdit.idx===idx && slotEdit.field==='offset' ? (
                          <input autoFocus type="number" min={0} value={Math.round((Number(s.offset_sec)||0)/60)}
                            onChange={(e)=>{ const v=Math.max(0, Number(e.target.value)||0); setSeriesSlots(prev => prev.map((x,i)=> i===idx?{...x,offset_sec:v*60}:x)); }}
                            onBlur={()=> setSlotEdit({ idx:-1, field:'' })}
                            style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px', width:'100%' }} />
                        ) : (
                          <span>Offset: {Math.round((Number(s.offset_sec)||0)/60)} min</span>
                        )}
                      </div>
                      <div onClick={()=> setSlotEdit({ idx, field:'duration' })} style={{ cursor:'text' }}>
                        {slotEdit.idx===idx && slotEdit.field==='duration' ? (
                          <input autoFocus type="number" min={0} value={Math.round((Number(s.duration_sec)||0)/60)}
                            onChange={(e)=>{ const v=Math.max(0, Number(e.target.value)||0); setSeriesSlots(prev => prev.map((x,i)=> i===idx?{...x,duration_sec:v*60}:x)); }}
                            onBlur={()=> setSlotEdit({ idx:-1, field:'' })}
                            style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.25)', borderRadius:6, padding:'4px 6px', width:'100%' }} />
                        ) : (
                          <span>Duration: {Math.round((Number(s.duration_sec)||0)/60)} min</span>
                        )}
                      </div>
                      <div style={{ fontSize:12, opacity:0.85 }}>
                        {(() => {
                          try {
                            const base = curStartIso || eventRow?.dtstart || null;
                            if (!base) return '-';
                            const t = new Date(new Date(base).getTime() + (Number(s.offset_sec)||0)*1000);
                            return t.toLocaleString();
                          } catch { return '-'; }
                        })()}
                      </div>
                      <GhostButton title="Remove" onClick={()=> setSeriesSlots(prev => prev.filter((_,i)=> i!==idx))} style={{ padding:'2px 6px', color:'#f87171' }}>✖️</GhostButton>
                    </li>
                  ))}
                </ul>
                <Row style={{ justifyContent:'flex-start', marginTop:8 }}>
                  <GhostButton onClick={()=> setSeriesSlots(prev => [...prev, { name:'', offset_sec:0, duration_sec:0, staff:[] }])}>Add Slot</GhostButton>
                </Row>
              </div>
            </div>
          )}
        </div>
    </>
  );

  if (inline) {
    // Match EventOverviewPanel inline (no Card wrapper inside right modal)
    return (
      <div>
        {inner}
      </div>
    );
  }
  return (
    <div role="dialog" aria-modal
      style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.55)', display: 'grid', placeItems: 'center', zIndex: 1000 }}
      onClick={(e) => { if (e.target === e.currentTarget && onClose) onClose(); }}
    >
      <Card style={{ position: 'relative', width: 'min(900px, 92vw)', maxHeight: '90vh', overflow: 'auto', padding: 24 }}>
        {inner}
      </Card>
    </div>
  );
}
