import { useCallback, useEffect, useMemo, useState } from 'react';
import { Row, Label, Input, Button, ErrorText, InfoText, GhostButton } from 'components/ui';
import { useNavigate, useLocation } from 'react-router-dom';
import { fmtRangeLocal, fmtTime, browserTZ } from 'teams/utils/datetime';
import { expandEvents } from 'calendar/expandOccurrences';
import { listCalloutOpportunities, listCalloutOpportunitiesWithInterest } from 'teams/teams.api';
import {
  listMyInvitedEvents,
  listMyTeams,
  listGroupCalendars,
  fetchGroupEvents,
  fetchGroupOverrides,
  getCalendarOwnerInfo,
  listGroupOwnerNotifications,
  getEventsByIds,
  listOverridesForEvents,
} from 'teams/teams.api';

function toDateInputValue(date) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}
function toIsoStartOfDay(dateInput) {
  if (!dateInput) return null;
  return new Date(`${dateInput}T00:00:00`).toISOString();
}
function toIsoEndOfDay(dateInput) {
  if (!dateInput) return null;
  return new Date(`${dateInput}T23:59:59`).toISOString();
}

export default function CalendarPage() {
  const tz = useMemo(() => browserTZ(), []);
  const navigate = useNavigate();
  const location = useLocation();
  const today = useMemo(() => new Date(), []);
  const defaultEnd = useMemo(() => { const d = new Date(); d.setDate(d.getDate() + 30); return d; }, []);

  // Filters (same as Dashboard – start/end/category/source)
  const [startDate, setStartDate] = useState(() => toDateInputValue(today));
  const [endDate, setEndDate] = useState(() => toDateInputValue(defaultEnd));
  const [category, setCategory] = useState('all');
  const [sourceFilter, setSourceFilter] = useState('all'); // 'all' | 'individual' | <groupId>
  const [availableCategories, setAvailableCategories] = useState([]);
  const [myGroups, setMyGroups] = useState([]); // [{ id, name, display_id }]

  // Data state
  const [events, setEvents] = useState([]); // invited/personal
  const [ownOccs, setOwnOccs] = useState([]); // occurrences from my groups
  const [calOwnerCache, setCalOwnerCache] = useState({}); // calendar_id -> owner info
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');
  // Opportunities are integrated via category 'opportunity'; no separate toggle
  const [view, setView] = useState('agenda'); // 'agenda' | 'week' | 'month'
  const [myTeamsFull, setMyTeamsFull] = useState([]); // for permission checks (role)
  const setWeekFromDate = useCallback((dateObj) => {
    try {
      const base = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
      const dow = base.getDay();
      const mondayDelta = ((dow + 6) % 7);
      const ws = new Date(base); ws.setDate(base.getDate() - mondayDelta);
      const we = new Date(ws); we.setDate(ws.getDate() + 6);
      setStartDate(toDateInputValue(ws));
      setEndDate(toDateInputValue(we));
    } catch {}
  }, []);
  const setMonthFromDate = useCallback((dateObj) => {
    try {
      const first = new Date(dateObj.getFullYear(), dateObj.getMonth(), 1);
      const last = new Date(dateObj.getFullYear(), dateObj.getMonth() + 1, 0);
      setStartDate(toDateInputValue(first));
      setEndDate(toDateInputValue(last));
    } catch {}
  }, []);

  // Keep date range in sync with the visible window whenever view changes
  useEffect(() => {
    try {
      if (view === 'month') {
        const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
        setMonthFromDate(base);
      } else if (view === 'week') {
        const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
        setWeekFromDate(base);
      }
      // agenda uses the existing start/end unchanged
    } catch {}
  }, [view, setMonthFromDate, setWeekFromDate]);

  // Helpers
  const openEventRightPanel = (row) => {
    try {
      const sp = new URLSearchParams(location.search || '');
      ['rpanel','team','group','user','create','tab','series'].forEach(k => sp.delete(k));
      sp.set('event', row.event_id);
      try { if (row.recurrence_id || row.dtstart) sp.set('rid', row.recurrence_id || row.dtstart); } catch {}
      navigate(`/calendar?${sp.toString()}`, { replace: true });
    } catch {}
  };

  const load = useCallback(async () => {
    if (!startDate || !endDate) { setEvents([]); setOwnOccs([]); return; }
    if (startDate > endDate) { setErr('Start date must be on or before the end date.'); setEvents([]); setOwnOccs([]); return; }
    setErr('');
    setRows([]);
    setLoading(true);
    const seq = (load.seq = (load.seq || 0) + 1);
    try {
      const startIso = toIsoStartOfDay(startDate);
      const endIso = toIsoEndOfDay(endDate);
      const categoryParam = category === 'all' ? null : category;

      // Invited/personal events (fetch all categories)
      const invitedRows = await listMyInvitedEvents(startIso, endIso, null);
      setEvents(invitedRows || []);

      // My group calendars -> expand to occurrences (similar to Dashboard)
      const teams = await listMyTeams();
      setMyTeamsFull(teams || []);
      const groups = (teams || []).map(t => ({ id: t.id, name: t.name || t.group_name || '', display_id: t.display_id || t.group_display_id || '' }));
      setMyGroups(groups);

      const occsAll = [];
      await Promise.all(groups.map(async (g) => {
        try {
          const cals = await listGroupCalendars(g.id);
          const calIds = (cals || []).map(c => c.id);
          const [ev, ov] = await Promise.all([
            fetchGroupEvents(g.id, startIso, endIso, calIds),
            fetchGroupOverrides(g.id, startIso, endIso, calIds),
          ]);
          // Expand base occurrences and merge overrides (like group calendar panel)
          const merged = expandEvents({ events: ev || [], overrides: ov || [], windowStart: startIso, windowEnd: endIso, capPerEvent: 500 }) || [];
          merged.forEach(m => {
            const event = m.event || {};
            const override = m.override || {};
            const extOverride = override.extended || {};
            const extEvent = event.extended || {};
            // Prefer override category, then series extended.category, then first categories[] entry
            const category = (extOverride.category || extEvent.category || (Array.isArray(event.categories) && event.categories[0]) || '').toLowerCase();
            const startIsoOcc = m.start ? new Date(m.start).toISOString() : (override.dtstart || event.dtstart);
            const endIsoOcc = m.end ? new Date(m.end).toISOString() : (override.dtend || event.dtend || null);
            occsAll.push({
              source: 'group',
              event_id: m.eventId,
              override_id: m.overrideId || null,
              recurrence_id: m.recurrence_id,
              summary: override.summary || event.summary || '',
              description: override.description || event.description || '',
              location: override.location || event.location || '',
              dtstart: startIsoOcc,
              dtend: endIsoOcc,
              tzid: override.tzid || event.tzid || 'UTC',
              category: category || '',
              calendar_id: event.calendar_id,
              event_status: override.status || event.status || 'TENTATIVE',
              group_id: g.id,
            });
          });
        } catch (_) { /* ignore per-group failures */ }
      }));
      setOwnOccs(occsAll);

      // Categories: include full set from data plus standard types (opportunities are treated as a source)
      const catsSet = new Set([
        ...((invitedRows || []).map(r => (r.category || '').toLowerCase())),
        ...((occsAll || []).map(r => (r.category || '').toLowerCase())),
      ].filter(Boolean));
      ['rehearsal','performance','workshop','social'].forEach((c) => catsSet.add(c));
      const cats = Array.from(catsSet).sort();
      if (load.seq !== seq) return;
      setAvailableCategories(cats);

      // Prefetch owner info for display
      const missing = Array.from(new Set([...(invitedRows||[]), ...(occsAll||[])]
        .map(r => r.calendar_id).filter(id => id && calOwnerCache[id] === undefined)));
      if (missing.length) {
        const entries = await Promise.all(missing.map(async (cid) => {
          try { const info = await getCalendarOwnerInfo(cid); return [cid, info || null]; } catch { return [cid, null]; }
        }));
        setCalOwnerCache(prev => ({ ...prev, ...Object.fromEntries(entries) }));
      }

      // Determine which base events are recurring (for series button visibility)
      try {
        const eventIdsAll = Array.from(new Set([...(invitedRows||[]), ...(occsAll||[])]
          .map(r => r.event_id).filter(Boolean)));
        if (eventIdsAll.length) {
          const baseRows = await getEventsByIds(eventIdsAll);
          const recSet = new Set((baseRows || []).filter(e => {
            const rr = String(e.rrule || '').toUpperCase();
            return rr.includes('FREQ=') && !rr.includes('FREQ=NONE');
          }).map(e => e.id));
          if (load.seq === seq) setRecurringEventIds(recSet);
        } else {
          if (load.seq === seq) setRecurringEventIds(new Set());
        }
      } catch (_) { if (load.seq === seq) setRecurringEventIds(new Set()); }

      // Load opportunities and normalize
      let oppCards = [];
      try {
        const [rowsAll, rowsWith] = await Promise.all([
          listCalloutOpportunities(null, startIso, endIso),
          listCalloutOpportunitiesWithInterest(null, startIso, endIso),
        ]);
        const byId = new Map();
        (rowsAll || []).forEach(r => byId.set(r.callout_id || `${r.event_id}:${r.kind}`, { ...r }));
        (rowsWith || []).forEach(r => {
          const key = r.callout_id || `${r.event_id}:${r.kind}`;
          const prev = byId.get(key) || r;
          byId.set(key, { ...prev, ...r });
        });
        const dedup = new Map();
        Array.from(byId.values()).forEach(row => {
          const startIso2 = row.dtstart ? new Date(row.dtstart).toISOString() : '';
          const k = `${row.event_id}|${startIso2}|${row.kind || ''}`;
          if (!dedup.has(k)) dedup.set(k, row);
        });
        oppCards = Array.from(dedup.values()).map(row => ({
          __kind: 'opportunity',
          event_id: row.event_id,
          dtstart: row.dtstart,
          dtend: row.dtend,
          tzid: row.tzid || 'UTC',
          title: row.summary || '(untitled)',
          description: row.details || '',
          location: row.location || '',
          hostName: row.owner_display || row.calendar_name || 'Organizer',
          category: 'opportunity',
          calendar_id: row.calendar_id || null,
          opportunity_kind: row.kind,
        }));
        // Do not inject 'opportunity' as an event type; use Source filter for callouts
      } catch (_) {}

      // Consolidate per occurrence with context chips
      const groupName = new Map((myGroups || []).map(g => [String(g.id), g.name || g.display_id || String(g.id)]));
      const byOcc = new Map(); // key -> consolidated
      const normIso = (v) => { try { return v ? new Date(v).toISOString() : ''; } catch { return v || ''; } };
      const makeKey = (ev) => {
        const eid = String(ev.event_id);
        const ov = ev.override_id ? `ov:${String(ev.override_id)}` : '';
        const rid = ev.recurrence_id ? `rid:${normIso(ev.recurrence_id)}` : '';
        const dt = ev.dtstart ? `dt:${normIso(ev.dtstart)}` : '';
        return `${eid}|${ov || rid || dt}`;
      };
      const ensure = (ev) => {
        // Prefer a stable key: override_id -> recurrence_id -> dtstart
        const eid = String(ev.event_id);
        const hasOv = !!ev.override_id;
        const ridIso = normIso(ev.recurrence_id);
        const dtIso = normIso(ev.dtstart);
        const key = makeKey(ev);
        let cur = byOcc.get(key);
        if (!cur) {
          cur = {
            event_id: ev.event_id,
            recurrence_id: ev.recurrence_id || null,
            dtstart: ev.dtstart,
            dtend: ev.dtend,
            tzid: ev.tzid || 'UTC',
            title: ev.summary || ev.title || '(untitled)',
            description: ev.description || '',
            location: ev.location || '',
            category: '',
            event_status: ev.event_status || '',
            contexts: { invited: false, groups: [], act: false, jam: false },
            calendar_id: ev.calendar_id || null,
            override_id: ev.override_id || null,
            overridden: !!ev.override_id,
          };
          byOcc.set(key, cur);
          // If we now have an override-based entry, purge any pre-existing series key for the same occurrence
          if (hasOv) {
            const dtKeyFromRid = ridIso ? `${eid}|dt:${ridIso}` : '';
            const ridKey = ridIso ? `${eid}|rid:${ridIso}` : '';
            if (dtKeyFromRid && byOcc.has(dtKeyFromRid)) byOcc.delete(dtKeyFromRid);
            if (ridKey && byOcc.has(ridKey)) byOcc.delete(ridKey);
          } else if (ridIso) {
            // If we have a rid-based entry, drop any dt-key that matches this rid
            const dtKeyFromRid = `${eid}|dt:${ridIso}`;
            if (byOcc.has(dtKeyFromRid)) byOcc.delete(dtKeyFromRid);
          }
        }
        if (!cur.calendar_id && ev.calendar_id) cur.calendar_id = ev.calendar_id;
        if (!cur.override_id && ev.override_id) cur.override_id = ev.override_id;
        if (!cur.overridden && ev.override_id) cur.overridden = true;
        return cur;
      };
      // invited (already resolved to occurrence if override exists)
      (invitedRows || []).forEach(r => {
        const cat = (r.category || '').toLowerCase();
        const cur = ensure(r);
        // Always prefer the occurrence-resolved values from this row
        cur.title = r.summary || cur.title;
        cur.description = r.description || cur.description;
        cur.location = r.location || cur.location;
        if (r.dtstart) cur.dtstart = r.dtstart;
        if (r.dtend) cur.dtend = r.dtend;
        if (r.tzid) cur.tzid = r.tzid;
        cur.override_id = r.override_id || cur.override_id || null;
        cur.overridden = cur.overridden || !!r.override_id;
        if (!cur.category && cat) cur.category = cat;
        if (!cur.event_status && r.event_status) cur.event_status = r.event_status;
        cur.contexts.invited = true;
      });
      // groups
      (occsAll || []).forEach(r => {
        const cat = (r.category || '').toLowerCase();
        const cur = ensure(r);
        // Prefer override occurrence content when provided
        cur.title = r.summary || cur.title;
        cur.description = r.description || cur.description;
        cur.location = r.location || cur.location;
        if (r.dtstart) cur.dtstart = r.dtstart;
        if (r.dtend) cur.dtend = r.dtend;
        if (r.tzid) cur.tzid = r.tzid;
        cur.override_id = r.override_id || cur.override_id || null;
        cur.overridden = cur.overridden || !!r.override_id;
        if (!cur.category && cat) cur.category = cat;
        if (!cur.event_status && r.event_status) cur.event_status = r.event_status;
        const gid = String(r.group_id || '');
        if (gid && !cur.contexts.groups.some(g => String(g.id) === gid)) {
          cur.contexts.groups.push({ id: gid, name: groupName.get(gid) || gid });
        }
      });
      // opportunities (independent of event type category)
      (oppCards || []).forEach(o => {
        const cur = ensure(o);
        const kind = String(o.opportunity_kind || '').toLowerCase();
        if (kind === 'act') cur.contexts.act = true; else cur.contexts.jam = true;
      });
      // Output cards
      const cards = Array.from(byOcc.values())
        .sort((a,b)=> (Date.parse(a?.dtstart||0)||0) - (Date.parse(b?.dtstart||0)||0));
      if (load.seq !== seq) return;
      setRows(cards);
    } catch (e) {
      setErr(e?.message || 'Failed to load calendar');
      setEvents([]); setOwnOccs([]);
    } finally {
      if (load.seq === seq) setLoading(false);
    }
  }, [startDate, endDate, calOwnerCache]);

  useEffect(() => { load(); }, [load]);

  // Reflect inline edits from EventOverviewPanel immediately on cards
  useEffect(() => {
    function onEventUpdated(ev) {
      try {
        const detail = ev?.detail || {};
        const eventId = detail.eventId;
        const rid = detail.baseStart || null;
        const patch = detail.patch || {};
        if (!eventId) return;
        setRows((prev) => {
          let changed = false;
          const updated = (prev || []).map((r) => {
            if (String(r.event_id) !== String(eventId)) return r;
            if (rid && r.recurrence_id && new Date(r.recurrence_id).toISOString() !== new Date(rid).toISOString()) {
              return r; // only update the matching occurrence when rid provided
            }
            changed = true;
            const next = { ...r };
            if (Object.prototype.hasOwnProperty.call(patch, 'summary')) {
              next.title = patch.summary || '';
            }
            if (Object.prototype.hasOwnProperty.call(patch, 'description')) {
              next.description = patch.description || '';
            }
            if (Object.prototype.hasOwnProperty.call(patch, 'location')) {
              next.location = patch.location || '';
            }
            if (Object.prototype.hasOwnProperty.call(patch, 'dtstart')) {
              next.dtstart = patch.dtstart;
            }
            if (Object.prototype.hasOwnProperty.call(patch, 'dtend')) {
              next.dtend = patch.dtend;
            }
            if (Object.prototype.hasOwnProperty.call(patch, 'status')) {
              next.event_status = String(patch.status || '').toUpperCase();
            }
            return next;
          });
          if (!changed) return prev;
          // Re-sort by start time to keep UI consistent
          return updated.slice().sort((a,b)=> (Date.parse(a?.dtstart||0)||0) - (Date.parse(b?.dtstart||0)||0));
        });
      } catch {}
    }
    window.addEventListener('improvhub:event-updated', onEventUpdated);
    return () => window.removeEventListener('improvhub:event-updated', onEventUpdated);
  }, []);

  // Allow deep link: ?source=<groupId|'individual'>
  useEffect(() => {
    try {
      const sp = new URLSearchParams(location.search || '');
      const src = sp.get('source');
      if (src) setSourceFilter(src);
    } catch {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Fresh combined rows after last fetch
  const [rows, setRows] = useState([]);

  const filtered = useMemo(() => {
    let list = rows || [];
    // First apply event type (base category) filter
    if (category !== 'all') list = list.filter(r => (r.category || '') === category);
    // Then apply source filter
    if (sourceFilter === 'all') return list;
    if (sourceFilter === 'individual') return list.filter(r => r.contexts?.invited);
    if (sourceFilter === 'op:act') return list.filter(r => r.contexts?.act);
    if (sourceFilter === 'op:jam') return list.filter(r => r.contexts?.jam);
    // group id
    return list.filter(r => Array.isArray(r.contexts?.groups) && r.contexts.groups.some(g => String(g.id) === String(sourceFilter)));
  }, [rows, category, sourceFilter]);

  const displayEvents = useMemo(() => (filtered || []).map((ev) => {
    const startStr = fmtTime(ev.dtstart);
    const endStr = ev.dtend ? fmtTime(ev.dtend) : '';
    const timeRange = endStr ? `${startStr}–${endStr}` : startStr;
    const tzToUse = ev.tzid || tz || 'UTC';
    const info = ev.calendar_id ? (calOwnerCache[ev.calendar_id] || null) : null;
    const hostName = ev.hostName || info?.owner_display_name || info?.group_name || null;
    return {
      ...ev,
      categoryLabel: ev.category ? ev.category.charAt(0).toUpperCase() + ev.category.slice(1) : '',
      range: fmtRangeLocal(ev.dtstart, ev.dtend, tzToUse),
      timeRange,
      hostName,
    };
  }), [filtered, tz, calOwnerCache]);

  const manageGroupIds = useMemo(() => {
    try {
      const set = new Set();
      (myTeamsFull || []).forEach(t => {
        const role = String(t.role || '').toLowerCase();
        if (role === 'admin' || role === 'manager') set.add(String(t.id));
      });
      return set;
    } catch { return new Set(); }
  }, [myTeamsFull]);

  const [recurringEventIds, setRecurringEventIds] = useState(new Set());
  // UI
  let body;
  try {
    body = (
    <div>
      <div className="flex items-center justify-between">
        <div className="text-lg font-semibold">Calendar</div>
        <div />
      </div>

      {/* Sleek filter bar */}
      <div style={{ marginTop:12 }}>
        <div style={{ display:'flex', gap:10, alignItems:'center', flexWrap:'wrap', justifyContent:'space-between' }}>
          <div style={{ display:'flex', gap:8, alignItems:'center', flexWrap:'wrap' }}>
            <input type="date" value={startDate} onChange={(e)=> setStartDate(e.target.value)}
              style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.2)', borderRadius:8, padding:'6px 8px' }}
              aria-label="Start date" />
            <span style={{ opacity:0.5 }}>–</span>
            <input type="date" value={endDate} onChange={(e)=> setEndDate(e.target.value)}
              style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.2)', borderRadius:8, padding:'6px 8px' }}
              aria-label="End date" />
            <select
              value={category}
              onChange={(e)=> setCategory(e.target.value)}
              style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.2)', borderRadius:8, padding:'6px 8px', minWidth:180 }}
              aria-label="Event type"
            >
              <option value="all">All event types</option>
              {availableCategories.map((c) => {
                const key = String(c || '').toLowerCase();
                const label = key.charAt(0).toUpperCase() + key.slice(1);
                const col = (
                  key === 'performance' ? '#34d399' :
                  key === 'rehearsal'   ? '#60a5fa' :
                  key === 'workshop'    ? '#f59e0b' :
                  key === 'social'      ? '#ec4899' : '#9ca3af'
                );
                return (
                  <option key={c} value={c} style={{ color: col }}>{`\u25CF ${label}`}</option>
                );
              })}
            </select>
            <select
              value={sourceFilter}
              onChange={(e)=> setSourceFilter(e.target.value)}
              style={{ background:'#0b0b0e', color:'#fff', border:'1px solid rgba(255,255,255,0.2)', borderRadius:8, padding:'6px 8px', minWidth:200 }}
              aria-label="Source"
            >
              <option value="all">All sources</option>
              <option value="individual">Personal</option>
              <option value="op:act">Act Callouts</option>
              <option value="op:jam">Jam Callouts</option>
              {myGroups.map(g => (
                <option key={g.id} value={g.id}>{g.name || g.display_id || g.id}</option>
              ))}
            </select>
          </div>
          <div style={{ display:'flex', gap:6, alignItems:'center' }}>
            <div style={{ display:'flex', border:'1px solid rgba(255,255,255,0.2)', borderRadius:999, overflow:'hidden' }}>
              <button
                className={`${view==='agenda' ? 'bg-white text-black' : 'text-white hover:bg-white/10'} px-3 py-1`}
                onClick={() => setView('agenda')}
                aria-label="Agenda view"
              >Agenda</button>
              <button
                className={`${view==='week' ? 'bg-white text-black' : 'text-white hover:bg-white/10'} px-3 py-1`}
                onClick={() => { setView('week'); setWeekFromDate(new Date(startDate || toDateInputValue(today))); }}
                aria-label="Weekly view"
              >Week</button>
              <button
                className={`${view==='month' ? 'bg-white text-black' : 'text-white hover:bg-white/10'} px-3 py-1`}
                onClick={() => { setView('month'); setMonthFromDate(new Date(startDate || toDateInputValue(today))); }}
                aria-label="Monthly view"
              >Month</button>
            </div>
            {view==='agenda' && (
              <button className="px-2 py-1 rounded-lg border border-white/20 hover:bg-white/10"
                onClick={() => { try { const t=new Date(); const pad=(n)=>String(n).padStart(2,'0'); const s=`${t.getFullYear()}-${pad(t.getMonth()+1)}-${pad(t.getDate())}`; const e=new Date(t); e.setDate(e.getDate()+30); const se=`${e.getFullYear()}-${pad(e.getMonth()+1)}-${pad(e.getDate())}`; setStartDate(s); setEndDate(se); setView('agenda'); } catch {} }}
              >Today</button>
            )}
            {(view==='week' || view==='month') && (
              <div style={{ display:'flex', gap:6, alignItems:'center' }}>
                <button className="px-2 py-1 rounded-lg border border-white/20 hover:bg-white/10"
                  onClick={() => {
                    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                    if (view==='week') { base.setDate(base.getDate() - 7); setWeekFromDate(base); }
                    else { base.setMonth(base.getMonth() - 1); setMonthFromDate(base); }
                  }}>‹</button>
                <button className="px-2 py-1 rounded-lg border border-white/20 hover:bg-white/10"
                  onClick={() => { if (view==='week') setWeekFromDate(new Date()); else setMonthFromDate(new Date()); }}>Today</button>
                <button className="px-2 py-1 rounded-lg border border-white/20 hover:bg-white/10"
                  onClick={() => {
                    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                    if (view==='week') { base.setDate(base.getDate() + 7); setWeekFromDate(base); }
                    else { base.setMonth(base.getMonth() + 1); setMonthFromDate(base); }
                  }}>›</button>
              </div>
            )}
            <button className="px-2 py-1 rounded-lg border border-white/20 hover:bg-white/10" onClick={load} disabled={loading}>Refresh</button>
          </div>
        </div>
      </div>

      {err && <ErrorText style={{ marginTop: 12 }}>{err}</ErrorText>}

      {view === 'agenda' && (
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(260px, 1fr))', gap:12, marginTop:16 }}>
          {(displayEvents || []).map((ev) => {
            const cat = String(ev.category || '').toLowerCase();
            const colors = {
              rehearsal: { bg: 'rgba(96,165,250,0.08)', border: 'rgba(96,165,250,0.5)' },
              performance: { bg: 'rgba(52,211,153,0.08)', border: 'rgba(52,211,153,0.5)' },
              workshop: { bg: 'rgba(245,158,11,0.10)', border: 'rgba(245,158,11,0.5)' },
              social: { bg: 'rgba(236,72,153,0.08)', border: 'rgba(236,72,153,0.5)' },
            };
            const tint = colors[cat] || { bg: 'rgba(18,18,22,0.45)', border: 'rgba(255,255,255,0.12)' };
            const cardStyle = {
              border: `1px solid ${tint.border}`,
              borderRadius: 10,
              padding: 14,
              display: 'flex',
              flexDirection: 'column',
              gap: 6,
              background: tint.bg,
              cursor: 'pointer',
              minHeight: 140,
              position: 'relative',
              overflow: 'hidden',
            };
            const chipRowStyle = { display:'flex', gap:6, alignItems:'center', flexWrap:'wrap' };
            const isSeriesEvent = recurringEventIds.has(ev.event_id);
            const owner = ev.calendar_id ? (calOwnerCache[ev.calendar_id] || null) : null;
            const canShowSeriesBtn = (() => {
              try {
                if (!isSeriesEvent) return false;
                if (owner && owner.owner_kind === 'group') {
                  const gid = String(owner.group_id || '');
                  if (gid && manageGroupIds.has(gid)) return true;
                }
                const gList = Array.isArray(ev.contexts?.groups) ? ev.contexts.groups : [];
                if (gList.some(g => manageGroupIds.has(String(g.id)))) return true;
                return false;
              } catch { return false; }
            })();
            return (
            <div key={`${ev.event_id}:${ev.recurrence_id || ev.dtstart}:${ev.__kind || 'event'}`}
              role="button" tabIndex={0}
              onClick={() => openEventRightPanel(ev)}
              onKeyDown={(e)=> { if (e.key==='Enter') openEventRightPanel(ev); }}
              style={cardStyle}
            >
              {canShowSeriesBtn && (
                <button
                  title="Edit series"
                  onClick={(e)=>{
                    e.stopPropagation();
                    try {
                      const sp = new URLSearchParams(location.search || '');
                      ['rpanel','team','group','user','create','tab'].forEach(k => sp.delete(k));
                      sp.set('event', ev.event_id);
                      sp.delete('rid');
                      sp.set('series', '1');
                      navigate(`/calendar?${sp.toString()}`, { replace: true });
                    } catch {}
                  }}
                  style={{ position:'absolute', right:8, bottom:8, fontSize:12, padding:'4px 6px', border:'1px solid rgba(255,255,255,0.3)', borderRadius:8, background:'rgba(0,0,0,0.25)' }}
                >🔁 Series</button>
              )}
              {(() => {
                const st = String(ev.event_status || '').toUpperCase();
                if (st !== 'CANCELLED' && st !== 'TENTATIVE') return null;
                const label = st === 'CANCELLED' ? 'Cancelled' : 'Tentative';
                const bg = st === 'CANCELLED' ? 'rgba(248,113,113,0.92)' : 'rgba(96,165,250,0.92)';
                return (
                  <div style={{
                    position:'absolute',
                    top:22,
                    right:-68,
                    transform:'rotate(45deg)',
                    background:bg,
                    color:'#0a0a0a',
                    fontWeight:800,
                    fontSize:12,
                    lineHeight:1,
                    padding:'6px 72px',
                    pointerEvents:'none',
                    boxShadow:'0 2px 6px rgba(0,0,0,0.3)'
                  }}>{label}</div>
                );
              })()}
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', gap:12 }}>
                <div style={{ fontWeight:600, fontSize:16, lineHeight:1.2 }}>
                  {ev.title}
                  {ev.overridden && (<span style={{ marginLeft: 8, fontSize: 12, opacity: 0.7 }}>(edited)</span>)}
                </div>
                <div style={chipRowStyle}>
                  {(() => {
                    const chips = [];
                    // Category chip
                    if (ev.categoryLabel) {
                      const cardCat = String(ev.category || '').toLowerCase();
                      const active = category === cardCat;
                      chips.push(
                        <button key={`cat`}
                          title={`Filter by ${ev.categoryLabel}`}
                          onClick={(e)=> { e.stopPropagation(); const next=(active ? 'all' : cardCat); setCategory(next); }}
                          style={{ fontSize: 12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity: active ? 1 : 0.7, background: active ? 'rgba(255,255,255,0.2)' : 'transparent' }}
                        >{ev.categoryLabel}</button>
                      );
                    }
                    // Context chips
                    if (ev.contexts?.invited) {
                      const active = sourceFilter === 'individual';
                      chips.push(
                        <button key={`ctx-you`}
                          title="You"
                          onClick={(e)=> { e.stopPropagation(); setSourceFilter(active ? 'all' : 'individual'); }}
                          style={{ fontSize: 12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity: active ? 1 : 0.7, background: active ? 'rgba(255,255,255,0.2)' : 'transparent' }}
                        >You</button>
                      );
                    }
                    (ev.contexts?.groups || []).forEach((g, idx) => {
                      const active = String(sourceFilter) === String(g.id);
                      chips.push(
                        <button key={`ctx-g-${g.id}-${idx}`}
                          title={`Team ${g.name}`}
                          onClick={(e)=> { e.stopPropagation(); setSourceFilter(active ? 'all' : g.id); }}
                          style={{ fontSize: 12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity: active ? 1 : 0.7, background: active ? 'rgba(255,255,255,0.2)' : 'transparent' }}
                        >Team {g.name}</button>
                      );
                    });
                    if (ev.contexts?.act) {
                      const active = sourceFilter === 'op:act';
                      chips.push(
                        <button key={`ctx-act`}
                          title="Act Callout"
                          onClick={(e)=> { e.stopPropagation(); setSourceFilter(active ? 'all' : 'op:act'); }}
                          style={{ fontSize: 12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity: active ? 1 : 0.7, background: active ? 'rgba(255,255,255,0.2)' : 'transparent' }}
                        >Act Callout</button>
                      );
                    }
                    if (ev.contexts?.jam) {
                      const active = sourceFilter === 'op:jam';
                      chips.push(
                        <button key={`ctx-jam`}
                          title="Jam Callout"
                          onClick={(e)=> { e.stopPropagation(); setSourceFilter(active ? 'all' : 'op:jam'); }}
                          style={{ fontSize: 12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity: active ? 1 : 0.7, background: active ? 'rgba(255,255,255,0.2)' : 'transparent' }}
                        >Jam Callout</button>
                      );
                    }
                    return chips;
                  })()}
                  {/* consolidated context chips above; removed legacy per-card source button */}
                </div>
              </div>
              <div style={{ fontSize:13, opacity:0.85 }}>{ev.range}</div>
              {ev.location && (<div style={{ fontSize:13, opacity:0.75 }}>📍 {ev.location}</div>)}
              {ev.hostName && (<div style={{ fontSize:12, opacity:0.7 }}>Hosted by {ev.hostName}</div>)}
              {ev.description && (<div style={{ fontSize:12, opacity:0.8, marginTop:'auto' }}>{ev.description}</div>)}
            </div>
            );
          })}
        </div>
      )}

      {view === 'week' && (
        <WeekGrid
          events={displayEvents}
          tz={tz}
          onOpen={openEventRightPanel}
          startDate={startDate}
          onPickDay={(dateObj) => {
            try {
              const d = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
              const pad = (n)=> String(n).padStart(2,'0');
              const s = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
              setStartDate(s);
              setEndDate(s);
              setView('agenda');
            } catch {}
          }}
        />
      )}

      {view === 'month' && (
        <MonthGrid
          events={displayEvents}
          tz={tz}
          onOpen={openEventRightPanel}
          startDate={startDate}
          onPickDay={(dateObj) => {
            try { setView('week'); setWeekFromDate(dateObj); } catch {}
          }}
        />
      )}
    </div>
    );
  } catch (e) {
    body = (<ErrorText>Failed to render calendar: {String(e?.message || e)}</ErrorText>);
  }

  return body;
}

function WeekGrid({ events, tz, onOpen, startDate, onPickDay }) {
  try {
    const today = new Date();
    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
    const dow = base.getDay();
    const mondayDelta = ((dow + 6) % 7);
    const ws = new Date(base); ws.setDate(base.getDate() - mondayDelta);
    const days = Array.from({ length: 7 }, (_, i) => new Date(ws.getFullYear(), ws.getMonth(), ws.getDate() + i));
    const byDay = days.map(d => ({ date: d, items: [] }));
    (events || []).forEach(ev => {
      try {
        const d = new Date(ev.dtstart);
        if (isNaN(+d)) return;
        const idx = Math.floor((d - ws) / (24*3600*1000));
        if (idx >=0 && idx < 7) byDay[idx].items.push(ev);
      } catch {}
    });
    const rowHeight = 40;
    const hourLabels = Array.from({ length: 24 }, (_, h) => `${String(h).padStart(2,'0')}:00`);
    return (
      <div style={{ marginTop: 16 }}>
        {/* Header row with day labels */}
        <div style={{ display:'grid', gridTemplateColumns:'60px repeat(7, 1fr)', gap:0, marginBottom:6 }}>
          <div />
          {byDay.map((col, i) => (
            <div key={`hdr-${i}`} style={{ textAlign:'center', fontWeight:600, fontSize:12, opacity:0.9, padding:'4px 0' }}
                 title="View agenda for this day"
                 onClick={() => onPickDay && onPickDay(col.date)}
            >
              {col.date.toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric' })}
            </div>
          ))}
        </div>
        {/* Grid with hour labels and day columns */}
        <div style={{ display:'grid', gridTemplateColumns:'60px repeat(7, 1fr)', gap:0 }}>
          <div style={{ position:'relative', height: rowHeight*24, border:'1px solid rgba(255,255,255,0.1)' }}>
            {hourLabels.map((label, i) => (
              <div key={i} style={{ position:'absolute', top: i*rowHeight - 6, left: 6, fontSize:10, opacity:0.7 }}>{label}</div>
            ))}
          </div>
          {byDay.map((col, i) => {
            const isToday = col.date.toDateString() === today.toDateString();
            return (
              <div key={i}
                style={{
                  position:'relative',
                  height: rowHeight*24,
                  border:'1px solid rgba(255,255,255,0.1)',
                  background: `repeating-linear-gradient(to bottom, rgba(255,255,255,0.06) 0, rgba(255,255,255,0.06) 1px, transparent 1px, transparent ${rowHeight}px)${isToday ? ', rgba(255,255,255,0.06)' : ''}`,
                  overflow:'hidden',
                }}
              >
              {col.items.map(item => {
                const start = new Date(item.dtstart);
                if (isNaN(+start)) return null;
                const end = item.dtend ? new Date(item.dtend) : new Date(start.getTime() + 60*60*1000);
                const startMinutes = start.getHours()*60 + start.getMinutes();
                const endMinutes = end.getHours()*60 + end.getMinutes();
                const top = (startMinutes/60)*rowHeight;
                const height = Math.max(24, ((endMinutes - startMinutes)/60)*rowHeight);
                const cat = String(item.category || '').toLowerCase();
                const colors = {
                  rehearsal: { bg: 'rgba(96,165,250,0.18)', border: 'rgba(96,165,250,0.6)' },
                  performance: { bg: 'rgba(52,211,153,0.18)', border: 'rgba(52,211,153,0.6)' },
                  workshop: { bg: 'rgba(245,158,11,0.20)', border: 'rgba(245,158,11,0.6)' },
                  social: { bg: 'rgba(236,72,153,0.18)', border: 'rgba(236,72,153,0.6)' },
                };
                const tint = colors[cat] || { bg: 'rgba(255,255,255,0.06)', border: 'rgba(255,255,255,0.2)' };
                return (
                  <div key={`${item.event_id}:${item.recurrence_id || item.dtstart}:${item.__kind || 'event'}`}
                       onClick={()=> onOpen(item)}
                       role="button" tabIndex={0}
                       onKeyDown={(e)=> { if (e.key==='Enter') onOpen(item); }}
                       style={{ position:'absolute', left:6, right:6, top, height, border:`1px solid ${tint.border}`, borderRadius:8, background:tint.bg, padding:'6px 8px', cursor:'pointer' }}>
                    <div style={{ fontSize:12, fontWeight:600, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{item.title}</div>
                    <div style={{ fontSize:11, opacity:0.85 }}>{start.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })} – {end.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}</div>
                  </div>
                );
              })}
              </div>
            );
          })}
        </div>
      </div>
    );
  } catch { return null; }
}

function MonthGrid({ events, tz, onOpen, startDate, onPickDay }) {
  try {
    const today = new Date();
    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
    const y = base.getFullYear(); const m = base.getMonth();
    const first = new Date(y, m, 1);
    const last = new Date(y, m + 1, 0);
    const startDow = (first.getDay() + 6) % 7; // 0=Mon..6=Sun
    const daysInMonth = last.getDate();
    const totalCells = Math.ceil((startDow + daysInMonth) / 7) * 7;
    const startDateGrid = new Date(y, m, 1 - startDow);
    const cells = Array.from({ length: totalCells }, (_, i) => new Date(startDateGrid.getFullYear(), startDateGrid.getMonth(), startDateGrid.getDate() + i));
    const byDateIso = new Map();
    (events || []).forEach(ev => {
      try {
        const d = new Date(ev.dtstart);
        if (isNaN(+d)) return;
        const key = d.toISOString().slice(0,10);
        const arr = byDateIso.get(key) || []; arr.push(ev); byDateIso.set(key, arr);
      } catch {}
    });
    const dayNames = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
    const gridLine = 'rgba(255,255,255,0.1)';
    return (
      <div style={{ marginTop: 16 }}>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(7, 1fr)', gap:0, marginBottom:6 }}>
          {dayNames.map((dn) => (
            <div key={dn} style={{ textAlign:'center', fontWeight:600, fontSize:12, opacity:0.85, background:'transparent', padding:'4px 0' }}>{dn}</div>
          ))}
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(7, 1fr)', gap:0 }}>
          {cells.map((d, i) => {
            const inMonth = d.getMonth() === m;
            const key = d.toISOString().slice(0,10);
            const items = byDateIso.get(key) || [];
            const isToday = d.toDateString() === today.toDateString();
            const rows = totalCells / 7;
            const rowIdx = Math.floor(i / 7);
            const colIdx = i % 7;
            const border = '1px solid rgba(255,255,255,0.1)';
            const cellStyle = {
              borderTop: rowIdx === 0 ? border : 'none',
              borderLeft: colIdx === 0 ? border : 'none',
              borderRight: colIdx === 6 ? border : 'none',
              borderBottom: rowIdx === (rows - 1) ? border : 'none',
              borderRadius: 0,
              padding: 6,
              background: inMonth ? (isToday ? 'rgba(255,255,255,0.06)' : 'transparent') : 'rgba(255,255,255,0.03)'
            };
            return (
              <div key={i} style={cellStyle}>
              <div
                style={{ fontWeight:600, fontSize:12, opacity:0.85, marginBottom:6, cursor:'pointer' }}
                title="View this week"
                onClick={() => onPickDay && onPickDay(d)}
              >
                {d.getDate()}
              </div>
                <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:4 }}>
                  {items.length === 0 ? (
                    <li style={{ opacity:0.6, fontSize:12 }}>No events</li>
                  ) : items.map(item => (
                    <li key={`${item.event_id}:${item.recurrence_id || item.dtstart}:${item.__kind || 'event'}`}
                        onClick={()=> onOpen(item)}
                        role="button" tabIndex={0}
                        onKeyDown={(e)=> { if (e.key==='Enter') onOpen(item); }}
                        style={{
                          border: (()=>{ const c=String(item.category||'').toLowerCase(); const m={ rehearsal:'rgba(96,165,250,0.6)', performance:'rgba(52,211,153,0.6)', workshop:'rgba(245,158,11,0.6)', social:'rgba(236,72,153,0.6)'}; return `1px solid ${m[c]||'rgba(255,255,255,0.1)'}`; })(),
                          borderRadius:6,
                          padding:'4px 6px',
                          cursor:'pointer',
                          background: (()=>{ const c=String(item.category||'').toLowerCase(); const m={ rehearsal:'rgba(96,165,250,0.10)', performance:'rgba(52,211,153,0.10)', workshop:'rgba(245,158,11,0.12)', social:'rgba(236,72,153,0.10)'}; return m[c]||'transparent'; })(),
                        }}>
                      <div style={{ fontSize:12, fontWeight:600, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{item.title}</div>
                      <div style={{ fontSize:11, opacity:0.8 }}>{new Date(item.dtstart).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}</div>
                    </li>
                  ))}
                </ul>
              </div>
            );
          })}
        </div>
      </div>
    );
  } catch { return null; }
}
