import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import ProtectedRoute from "auth/ProtectedRoute";
import AppShell from "app/AppShell";
import SignIn from "auth/AuthScreens/SignIn";
import SignUp from "auth/AuthScreens/SignUp";
import ForgotPassword from "auth/AuthScreens/ForgotPassword";
import NewPassword from "auth/AuthScreens/NewPassword";
import Dashboard from "app_pages/Dashboard";
import GroupsPage from "app_pages/Groups";
import CommunityPage from "app_pages/Community";
import ListingsPage from "app_pages/Listings";
import CalendarPage from "app_pages/Calendar";
import ProfilePage from "app_pages/Profile";
import HelpPage from "app_pages/Help";
// Event routes render details in the right panel; no main content or popups here.

export default function AppRouter() {
  const base = (typeof window !== 'undefined' && window.location && window.location.pathname.startsWith('/improvhub')) ? '/improvhub' : '';
  return (
    <BrowserRouter basename={base}>
      <Routes>
        {/* PUBLIC AUTH ROUTES (no guard) */}
        <Route path="/auth/signin" element={<SignIn />} />
        <Route path="/auth/signup" element={<SignUp />} />
        <Route path="/auth/forgot" element={<ForgotPassword />} />
        <Route path="/auth/new-password" element={<NewPassword />} />

        {/* PRIVATE ROUTES (guarded) */}
        <Route element={<ProtectedRoute />}>
          <Route element={<AppShell />}>
            {/* home/dashboard */}
            <Route path="/" element={<Dashboard />} />
            <Route index element={<Dashboard />} />
            {/* groups */}
            <Route path="/groups" element={<GroupsPage />} />
            <Route path="/groups/:groupId" element={<GroupsPage />} >
              <Route path="events/:eventId" element={<></>} />
              <Route path="events/:eventId/occurrences/:rid" element={<></>} />
            </Route>
            {/* community */}
            <Route path="/community" element={<CommunityPage />} />
            <Route path="/listings" element={<ListingsPage />} />
            <Route path="/calendar" element={<CalendarPage />} />
            
            <Route path="/help" element={<HelpPage />} />
            {/* profile */}
            <Route path="/profile" element={<ProfilePage />} />
            {/* events (right panel only; keep main content unchanged) */}
            <Route path="/events/:eventId" element={<></>} />
            <Route path="/events/:eventId/occurrences/:rid" element={<></>} />
          </Route>
        </Route>

        {/* FALLBACK */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </BrowserRouter>
  );
}
