import { useEffect, useMemo, useState } from 'react';
import { useAuth } from 'auth/AuthContext';
import {
  listMyTeams,
  listTeamMembersRPC,
  setMemberRoleRPC,
  addMemberByEmailRPC,
  removeMemberRPC,
  deleteTeamRPC,
} from 'teams/teams.api';
import TeamMembers from 'teams/components/TeamMembers';
import { useNavigate, useLocation } from 'react-router-dom';
import { useToast } from 'components/toast';

export default function RightPanelMembers({ groupId }) {
  const { add: addToast } = useToast();
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const currentUserId = user?.id || null;
  const [team, setTeam] = useState(null);
  const [members, setMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');

  const load = async (id) => {
    setErr(''); setLoading(true);
    try {
      const list = await listMyTeams();
      const t = (list || []).find(x => String(x.id) === String(id));
      setTeam(t || null);
      if (t) {
        const mem = await listTeamMembersRPC(t.id);
        setMembers(mem || []);
      }
    } catch (e) { setErr(e.message || 'Failed to load group'); }
    finally { setLoading(false); }
  };

  useEffect(() => { load(groupId); }, [groupId]);

  const meRole = useMemo(() => {
    const me = (members || []).find(m => m.user_id === currentUserId);
    return (me?.role || '').toLowerCase();
  }, [members, currentUserId]);
  const isAdmin = meRole === 'admin';

  const handleChangeRole = async (userId, role) => {
    try { await setMemberRoleRPC(team.id, userId, role); addToast('Role updated'); await load(groupId); }
    catch (e) { addToast(e.message || 'Failed to update role', 'error'); }
  };
  const handleAddMember = async (email, role) => {
    try { await addMemberByEmailRPC(team.id, email, role); addToast('Invite sent'); await load(groupId); }
    catch (e) { addToast(e.message || 'Failed to invite', 'error'); }
  };
  const handleRemoveMember = async (userId) => {
    try { await removeMemberRPC(team.id, userId); addToast('Member removed'); await load(groupId); }
    catch (e) { addToast(e.message || 'Failed to remove', 'error'); }
  };
  const handleLeaveTeam = async () => {
    try { await removeMemberRPC(team.id, currentUserId); addToast('You left the group'); await load(groupId); }
    catch (e) { addToast(e.message || 'Failed to leave', 'error'); }
  };
  const handleDeleteTeam = async () => {
    if (!team?.id) return;
    if (!window.confirm('Delete group? This cannot be undone.')) return;
    const name = team?.name || team?.group_name || '';
    try {
      await deleteTeamRPC(team.id);
      try { addToast(name ? `Deleted ${name}.` : 'Group deleted.'); } catch {}
      try { window.dispatchEvent(new CustomEvent('group:deleted', { detail: { groupId: team.id, groupName: name } })); } catch {}
      try {
        const sp = new URLSearchParams(location.search || '');
        ['rpanel','team','tab','user','group','create','event','rid'].forEach(k => sp.delete(k));
        navigate(`/groups?${sp.toString()}`);
      } catch { navigate('/groups'); }
    } catch (e) { addToast(e.message || 'Failed to delete group', 'error'); }
  };

  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (err) return <div style={{ color:'#ff6b6b' }}>{err}</div>;
  if (!team) return <div style={{ opacity: 0.75 }}>Group not found.</div>;

  return (
    <TeamMembers
      team={team}
      members={members}
      currentUserId={currentUserId}
      isAdmin={isAdmin}
      onChangeRole={handleChangeRole}
      onAddMember={handleAddMember}
      onRemoveMember={handleRemoveMember}
      onLeaveTeam={handleLeaveTeam}
      onDeleteTeam={handleDeleteTeam}
      showDeleteTeamControl={false}
    />
  );
}
