"use client";
import { useEffect, useRef, useState } from 'react';

export function Dropdown({ open: openProp, onOpenChange, children }) {
  const [open, setOpen] = useState(!!openProp);
  useEffect(() => { if (openProp !== undefined) setOpen(!!openProp); }, [openProp]);
  const set = (v) => { setOpen(v); onOpenChange?.(v); };
  return (
    <div className="relative inline-block text-left" data-open={open} onKeyDown={(e)=>{ if(e.key==='Escape') set(false); }}>
      {typeof children === 'function' ? children({ open, setOpen: set }) : children}
    </div>
  );
}

export function DropdownTrigger({ asChild = false, onClick, children, setOpen }) {
  const props = {
    onClick: (e) => { setOpen?.((v) => !v); onClick?.(e); },
  };
  return asChild ? (
    <span {...props}>{children}</span>
  ) : (
    <button {...props} className="inline-flex items-center justify-center rounded-md border border-white/20 hover:bg-white/10">
      {children}
    </button>
  );
}

export function DropdownContent({ children, align = 'end', open, setOpen, className = '' }) {
  const ref = useRef(null);
  useEffect(() => {
    const onDoc = (e) => { if (!ref.current) return; if (!ref.current.contains(e.target)) setOpen?.(false); };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, [setOpen]);
  if (!open) return null;
  const alignClass = align === 'end' ? 'right-0' : 'left-0';
  return (
    <div ref={ref} className={`absolute z-50 mt-2 w-72 ${alignClass}`}>
      <div className={`rounded-md border border-white/15 bg-card/95 backdrop-blur p-2 ${className}`}>{children}</div>
    </div>
  );
}

