// src/teams/TeamsPanel.jsx
import { useEffect, useMemo, useState } from "react";
import { useAuth } from "auth/AuthContext";
import { useNavigate, useLocation } from 'react-router-dom';
import { Megaphone, Users as UsersIcon, Calendar, Settings } from 'lucide-react';
import {
  // Teams & members
  listMyTeams,
  createTeam,
  listTeamMembersRPC,
  setMemberRoleRPC,
  addMemberByEmailRPC,
  removeMemberRPC,
  renameTeamRPC,
  deleteTeamRPC,
  updateGroupTypes,
  updateGroupPublicListing,
  listPublicGroupsByType,
  updateGroupProfile,
  updateGroupDisplayId,
} from "./teams.api";
import CalendarPanel from "./components/CalendarPanel";
import TeamUpdates from "./components/TeamUpdates";
import TeamMembers from "./components/TeamMembers";
import {
  Page, PageHeader, Card, H1, Label, Input, Button, GhostButton, DangerButton, ErrorText, InfoText, Row, Tabs, Tab, Breadcrumbs, SkeletonCard,
} from "components/ui";
import { useToast } from "components/toast";
import IdPeek from "components/IdPeek";

const TYPE_META = {
  act: { label: 'Act', icon: '🎭', short: 'Act', description: 'Performs publicly at shows.' },
  practice_group: { label: 'Practice Group', icon: '🧪', short: 'Practice', description: 'Rehearses stagework without public performances.' },
  school: { label: 'School', icon: '🏫', short: 'School', description: 'Runs workshops, classes, or training programs.' },
  theatre: { label: 'Theatre', icon: '🎟️', short: 'Theatre', description: 'Operates a semi-permanent venue with multiple public shows.' },
  producer: { label: 'Producer', icon: '🎬', short: 'Producer', description: 'Produces and runs public shows (non-venue specific).' },
};

const MUTUALLY_EXCLUSIVE = {
  act: ['practice_group'],
  practice_group: ['act'],
  producer: ['theatre'],
  theatre: ['producer'],
};

const TYPES = Object.entries(TYPE_META).map(([key, meta]) => ({ key, ...meta }));

const PUBLIC_SECTIONS = [
  { key: 'act', tabLabel: 'Acts', title: 'Public acts', empty: 'No public acts listed yet.' },
  { key: 'practice_group', tabLabel: 'Practice groups', title: 'Public practice groups', empty: 'No public practice groups listed yet.' },
  { key: 'theatre', tabLabel: 'Theatres', title: 'Public theatres', empty: 'No public theatres listed yet.' },
  { key: 'producer', tabLabel: 'Producers', title: 'Public producers', empty: 'No public producers listed yet.' },
  { key: 'school', tabLabel: 'Schools', title: 'Public schools', empty: 'No public schools listed yet.' },
];

function normalizeTypes(values = []) {
  const set = new Set();
  (Array.isArray(values) ? values : []).forEach((key) => {
    if (!TYPE_META[key]) return;
    const conflicts = MUTUALLY_EXCLUSIVE[key] || [];
    conflicts.forEach((conflict) => set.delete(conflict));
    set.add(key);
  });
  return Array.from(set);
}

export default function TeamsPanel({ initialTeamId = null, initialTab = null }) {
  const { add: addToast } = useToast();
  const { session } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const currentUserId = session?.user?.id;

  const [teams, setTeams] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [msg, setMsg] = useState("");

  const [selected, setSelected] = useState(null); // current team object
  const [members, setMembers] = useState([]);
  const [membersLoading, setMembersLoading] = useState(false);
  const [invites, setInvites] = useState([]);
  const [teamTab, setTeamTab] = useState("updates"); // 'updates' | 'members' | 'calendar' | 'admin'
  const [manageTarget, setManageTarget] = useState(null); // { eventId, rid? }
  const [calendarResetTick, setCalendarResetTick] = useState(0);
  const [typesDraft, setTypesDraft] = useState([]);
  const [savingTypes, setSavingTypes] = useState(false);
  const [publicDraft, setPublicDraft] = useState(false);
  const [savingPublic, setSavingPublic] = useState(false);
  const [siteDraft, setSiteDraft] = useState("");
  const [bioDraft, setBioDraft] = useState("");
  const [savingProfile, setSavingProfile] = useState(false);
  const [displayIdDraft, setDisplayIdDraft] = useState("");
  const [savingDisplayId, setSavingDisplayId] = useState(false);
  const [nameDraft, setNameDraft] = useState("");
  const [savingAll, setSavingAll] = useState(false);
  const [displayIdStatus, setDisplayIdStatus] = useState(null); // null | 'checking' | 'available' | 'taken' | 'invalid'

  const [publicGroups, setPublicGroups] = useState({});
  const [publicLoading, setPublicLoading] = useState(false);
  const [publicErr, setPublicErr] = useState("");
  const [listTab, setListTab] = useState('mine');

  // create team UI
  const [newName, setNewName] = useState("");
  const [creating, setCreating] = useState(false);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [createDraft, setCreateDraft] = useState({ name: '', displayId: '', website: '', bio: '', types: [], publicListing: false });
  const [createIdStatus, setCreateIdStatus] = useState(null); // null | 'checking' | 'available' | 'taken' | 'invalid'

  // invite UI (when team is open)
  const [showInvite, setShowInvite] = useState(false);
  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState("member");
  const [inviting, setInviting] = useState(false);

  const isAdmin = useMemo(() => {
    if (!selected) return false;
    const me = members.find((m) => m.user_id === currentUserId);
    return me?.role === "admin";
  }, [members, currentUserId, selected]);

  // Utilities for hash param management
  const getHashParams = () => {
    try { return new URLSearchParams((window.location.hash || '').replace(/^#/, '')); } catch { return new URLSearchParams(); }
  };
  const setHashParams = (updater) => {
    try {
      const params = getHashParams();
      updater(params);
      window.location.hash = params.toString();
    } catch {}
  };

  // Load teams and apply deep-link selection if present
  useEffect(() => {
    (async () => {
      setErr(""); setMsg(""); setLoading(true);
      try {
        const data = await listMyTeams();
        const list = (data || []).map((team) => ({ ...team, types: normalizeTypes(team.types) }));
        setTeams(list);
        // Deep-link: #team=<id>&tab=calendar
        const applyHash = async () => {
          try {
            const hash = (window.location.hash || '').replace(/^#/, '');
            if (!hash) return;
            const params = new URLSearchParams(hash);
            const teamId = params.get('team');
            const tabParam = params.get('teamTab');
            const eventId = params.get('event');
            const rid = params.get('rid');
            if (!teamId) return;
            const match = list.find(t => t.id === teamId);
            if (!match) return;
            const allowedTabs = new Set(['updates','members','calendar','admin']);
            if (!selected || selected.id !== teamId) {
              // Open the team (do not rewrite hash here to avoid loops)
              await openTeam(match, { updateHash: false });
              if (tabParam && allowedTabs.has(tabParam)) setTeamTab(tabParam);
            } else {
              // Same team; just switch sub-tab if present
              if (tabParam && allowedTabs.has(tabParam)) setTeamTab(tabParam);
            }
            if (eventId) setManageTarget({ eventId, rid: rid || null });
          } catch {}
        };
        // If route provided an initial team context, open it first
        if (initialTeamId) {
          const match = list.find(t => t.id === initialTeamId);
          if (match) {
            await openTeam(match, { updateHash: false });
            if (initialTab) setTeamTab(initialTab);
            // Also honor any deep-link event/rid in the hash when routed with :groupId
            await applyHash();
          }
        } else {
          await applyHash();
        }
        // Listen for hash changes to support later navigations
        const onHash = () => { applyHash(); };
        window.addEventListener('hashchange', onHash);
        return () => window.removeEventListener('hashchange', onHash);
      } catch (e) {
        setErr(e.message || "Failed to load teams");
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  // Sync updates coming from right panel admin to the main list/selected team
  useEffect(() => {
    const onGroupUpdated = (e) => {
      try {
        const { groupId, patch } = e.detail || {};
        if (!groupId || !patch) return;
        setTeams((ts) => ts.map(t => String(t.id) === String(groupId) ? { ...t, ...patch } : t));
        setSelected((s) => (s && String(s.id) === String(groupId)) ? { ...s, ...patch } : s);
      } catch {}
    };
    const onGroupDeleted = (e) => {
      try {
        const { groupId, groupName } = e.detail || {};
        if (!groupId) return;
        setTeams((ts) => ts.filter(t => String(t.id) !== String(groupId)));
        if (selected && String(selected.id) === String(groupId)) {
          backToList();
        }
        if (groupName) {
          try { addToast(`Deleted ${groupName}.`); } catch {}
        }
      } catch {}
    };
    window.addEventListener('group:updated', onGroupUpdated);
    window.addEventListener('group:deleted', onGroupDeleted);
    return () => window.removeEventListener('group:updated', onGroupUpdated);
  }, []);

  const loadMembers = async (team) => {
    if (!team?.id) return;
    setErr(""); setMsg("");
    setMembersLoading(true);
    try {
      // ✅ Option A fix: pass the team id to the RPC wrapper
      const mem = await listTeamMembersRPC(team.id);
      setMembers(mem);
    } catch (e) {
      setErr(e.message || "Failed to load members");
    } finally { setMembersLoading(false); }
  };

  const loadInvites = async (team) => {
    if (!team?.id) return;
    try {
      const rows = await (await import('./teams.api')).then(m => m);
    } catch {}
  };

  // Live unique-id availability check for Create flow (debounced)
  useEffect(() => {
    if (!showCreateForm) { setCreateIdStatus(null); return; }
    let timer;
    const val = (createDraft.displayId || '').trim();
    if (!val) { setCreateIdStatus(null); return; }
    if (!/^[a-zA-Z0-9_-]+$/.test(val)) { setCreateIdStatus('invalid'); return; }
    setCreateIdStatus('checking');
    timer = setTimeout(async () => {
      try {
        const { resolveOwnerByDisplayId } = await import('./teams.api');
        const ownerId = await resolveOwnerByDisplayId(val);
        setCreateIdStatus(ownerId ? 'taken' : 'available');
      } catch {
        setCreateIdStatus(null);
      }
    }, 350);
    return () => { if (timer) clearTimeout(timer); };
  }, [createDraft.displayId, showCreateForm]);

  const openTeam = async (team, { updateHash = true } = {}) => {
    // Clear any prior banners when opening a team
    setErr("");
    setMsg("");
    const normalizedTypes = normalizeTypes(team?.types);
    const normalizedTeam = { ...team, types: normalizedTypes };
    setSelected(normalizedTeam);
    setTypesDraft(normalizedTypes);
    setPublicDraft(!!team?.public_listing);
    setSiteDraft(team?.website || "");
    setBioDraft(team?.bio || "");
    setDisplayIdDraft(team?.display_id || "");
    setNameDraft(team?.name || "");
    setMembers([]);
    setTeamTab("updates");
    await loadMembers(normalizedTeam);
    // Reflect in URL: stay on /groups and use ?team=<id>
    if (normalizedTeam?.id) {
      try {
        const sp = new URLSearchParams(location.search || '');
        sp.set('team', normalizedTeam.id);
        navigate(`/groups?${sp.toString()}`);
      } catch {}
    }
    // Hash is used for sub-state like tab/event
    if (updateHash) {
      setHashParams((params) => {
        params.set('section', 'groups');
        if (normalizedTeam?.id) params.set('team', normalizedTeam.id); else params.delete('team');
        params.delete('event');
        params.delete('rid');
        params.set('teamTab', 'updates');
      });
    }
  };

  const backToList = () => {
    // Clear banners when leaving a team
    setErr("");
    setMsg("");
    setSelected(null);
    setTypesDraft([]);
    setPublicDraft(false);
    setMembers([]);
    setShowInvite(false);
    setInviteEmail("");
    setInviteRole("member");
    setShowCreateForm(false);
    setListTab('mine');
    // Clear deep-link to team, keep section=groups
    setHashParams((params) => {
      params.set('section', 'groups');
      params.delete('team');
      params.delete('event');
      params.delete('rid');
      params.delete('teamTab');
    });
    // Ensure route reflects group list
    navigate('/groups');
  };

  const createNewTeam = async () => {
    const name = (createDraft.name || '').trim();
    const displayId = (createDraft.displayId || '').trim();
    if (!name || !displayId) return;
    if (!/^[a-zA-Z0-9_-]+$/.test(displayId)) { setErr('Unique ID may only contain letters, numbers, dashes and underscores.'); return; }
    if (createIdStatus === 'taken' || createIdStatus === 'checking' || createIdStatus === 'invalid') return;
    setCreating(true); setErr(""); setMsg("");
    try {
      // 1) Create group by name
      const t = await createTeam(name);
      const normalizedTeam = { ...t, types: normalizeTypes(t.types) };

      // 2) Configure unique id
      await updateGroupDisplayId(normalizedTeam.id, displayId);

      // 3) Configure profile (optional)
      const site = (createDraft.website || '').trim();
      const bio = (createDraft.bio || '').trim();
      if (site || bio) {
        try { await updateGroupProfile(normalizedTeam.id, { website: site, bio }); } catch {}
      }

      // 4) Configure types (optional) and public listing
      const types = normalizeTypes(createDraft.types || []);
      if (types.length) {
        try { await updateGroupTypes(normalizedTeam.id, types); } catch {}
      }
      if (!!createDraft.publicListing) {
        try { await updateGroupPublicListing(normalizedTeam.id, !!createDraft.publicListing); } catch {}
      }

      // 5) Reflect locally and open
      const finalTeam = { ...normalizedTeam, name, display_id: displayId, website: site || null, bio: bio || null, types, public_listing: !!createDraft.publicListing };
      setTeams((ts) => [finalTeam, ...ts]);
      setShowCreateForm(false);
      setCreateDraft({ name: '', displayId: '', website: '', bio: '', types: [], publicListing: false });
      await openTeam(finalTeam);
      addToast('Group created.');
    } catch (e) {
      setErr(e.message || "Failed to create group"); addToast(e.message || 'Failed to create group', 'error');
    } finally {
      setCreating(false);
    }
  };

  const renameTeam = async () => {
    const name = window.prompt("Rename group", selected?.name || "");
    if (!name || !name.trim()) return;
    setErr(""); setMsg("");
    try {
      await renameTeamRPC(selected.id, name.trim());
      setSelected({ ...selected, name: name.trim() });
      setTeams((ts) => ts.map((t) => (t.id === selected.id ? { ...t, name: name.trim() } : t)));
      setMsg("Group renamed."); addToast('Group renamed.');
    } catch (e) {
      setErr(e.message || "Failed to rename group"); addToast(e.message || 'Failed to rename group', 'error');
    }
  };

  const deleteTeam = async () => {
    if (!window.confirm("Delete group? This cannot be undone.")) return;
    setErr(""); setMsg("");
    try {
      const deletedName = selected?.name || selected?.group_name || '';
      await deleteTeamRPC(selected.id);
      setTeams((ts) => ts.filter((t) => t.id !== selected.id));
      backToList();
      setMsg("Group deleted."); addToast(deletedName ? `Deleted ${deletedName}.` : 'Group deleted.');
    } catch (e) {
      setErr(e.message || "Failed to delete group"); addToast(e.message || 'Failed to delete group', 'error');
    }
  };

  // Live unique-id availability check (debounced)
  useEffect(() => {
    let timer;
    const val = (displayIdDraft || '').trim();
    if (!val) { setDisplayIdStatus(null); return; }
    if (!/^[a-zA-Z0-9_-]+$/.test(val)) { setDisplayIdStatus('invalid'); return; }
    if (selected?.display_id && val === selected.display_id) { setDisplayIdStatus('available'); return; }
    setDisplayIdStatus('checking');
    timer = setTimeout(async () => {
      try {
        const { resolveOwnerByDisplayId } = await import('./teams.api');
        const ownerId = await resolveOwnerByDisplayId(val);
        setDisplayIdStatus(ownerId ? 'taken' : 'available');
      } catch {
        setDisplayIdStatus(null);
      }
    }, 350);
    return () => { if (timer) clearTimeout(timer); };
  }, [displayIdDraft, selected?.display_id]);

  const saveAllChanges = async () => {
    if (!selected?.id) return;
    setSavingAll(true); setErr(""); setMsg("");
    try {
      // Name
      const trimmedName = (nameDraft || '').trim();
      if (trimmedName && trimmedName !== selected.name) {
        await renameTeamRPC(selected.id, trimmedName);
        setSelected(s => ({ ...s, name: trimmedName }));
        setTeams(ts => ts.map(t => t.id === selected.id ? { ...t, name: trimmedName } : t));
      }

      // Unique ID
      const trimmedId = (displayIdDraft || '').trim() || null;
      if (trimmedId !== (selected.display_id || null)) {
        if (trimmedId && !/^[a-zA-Z0-9_-]+$/.test(trimmedId)) throw new Error('Unique ID may only contain letters, numbers, dashes and underscores.');
        if (displayIdStatus === 'taken') throw new Error('Unique ID is already taken.');
        const row = await updateGroupDisplayId(selected.id, trimmedId);
        const newId = row?.display_id || trimmedId || '';
        setSelected(s => ({ ...s, display_id: newId }));
        setTeams(ts => ts.map(t => t.id === selected.id ? { ...t, display_id: newId } : t));
      }

      // Profile
      const site = (siteDraft || '').trim();
      const bio = (bioDraft || '').trim();
      if (site !== (selected.website || '') || bio !== (selected.bio || '')) {
        await updateGroupProfile(selected.id, { website: site, bio });
        setSelected(s => ({ ...s, website: site || null, bio: bio || null }));
        setTeams(ts => ts.map(t => t.id === selected.id ? { ...t, website: site || null, bio: bio || null } : t));
      }

      // Types
      const normTypes = normalizeTypes(typesDraft);
      if (JSON.stringify(normTypes) !== JSON.stringify(selected.types || [])) {
        await updateGroupTypes(selected.id, normTypes);
        setSelected(s => ({ ...s, types: normTypes }));
        setTeams(ts => ts.map(t => t.id === selected.id ? { ...t, types: normTypes } : t));
      }

      // Public listing
      if (!!publicDraft !== !!selected.public_listing) {
        await updateGroupPublicListing(selected.id, publicDraft);
        setSelected(s => ({ ...s, public_listing: !!publicDraft }));
        setTeams(ts => ts.map(t => t.id === selected.id ? { ...t, public_listing: !!publicDraft } : t));
      }

      setMsg('Changes saved.');
    } catch (e) {
      setErr(e.message || 'Failed to save changes');
    } finally { setSavingAll(false); }
  };

  const leaveTeam = async () => {
    if (!window.confirm("Leave this group?")) return;
    setErr(""); setMsg("");
    try {
      await removeMemberRPC(selected.id, currentUserId);
      setTeams((ts) => ts.filter((t) => t.id !== selected.id));
      backToList();
      setMsg("You left the group."); addToast('You left the group.');
    } catch (e) {
      setErr(e.message || "Failed to leave group"); addToast(e.message || 'Failed to leave group', 'error');
    }
  };

  const inviteMember = async () => {
    if (!inviteEmail.trim()) return;
    setInviting(true); setErr(""); setMsg("");
    try {
      await addMemberByEmailRPC(selected.id, inviteEmail.trim(), inviteRole);
      setInviteEmail("");
      setInviteRole("member");
      setShowInvite(false);
      await loadMembers(selected);
      // Refresh invites list
      try {
        const { listTeamInvitations } = await import('./teams.api');
        const inv = await listTeamInvitations(selected.id);
        setInvites(inv);
      } catch {}
      setMsg("Invitation added."); addToast('Invitation added.');
    } catch (e) {
      setErr(e.message || "Failed to add member"); addToast(e.message || 'Failed to add member', 'error');
    } finally {
      setInviting(false);
    }
  };

  useEffect(() => {
    let active = true;
    const loadPublicGroups = async () => {
      setPublicErr("");
      setPublicLoading(true);
      try {
        const results = await Promise.all(PUBLIC_SECTIONS.map(async (section) => {
          const rows = await listPublicGroupsByType(section.key);
          return { type: section.key, rows: (rows || []).map((g) => ({ ...g, types: normalizeTypes(g.types) })) };
        }));
        if (!active) return;
        const scoped = {};
        results.forEach(({ type, rows }) => { scoped[type] = rows; });
        setPublicGroups(scoped);
      } catch (e) {
        if (!active) return;
        setPublicErr(e.message || 'Failed to load public groups');
      } finally {
        if (active) setPublicLoading(false);
      }
    };
    loadPublicGroups();
    return () => { active = false; };
  }, []);


  const toggleType = (key) => {
    setTypesDraft((cur) => {
      const set = new Set(cur || []);
      if (set.has(key)) {
        set.delete(key);
        setMsg("");
      } else {
        const conflicts = MUTUALLY_EXCLUSIVE[key] || [];
        const removed = [];
        conflicts.forEach((conflict) => {
          if (set.delete(conflict)) removed.push(TYPE_META[conflict]?.label || conflict);
        });
        set.add(key);
        if (removed.length) {
          setMsg(`Removed ${removed.join(', ')} to keep taxonomy consistent.`);
        } else {
          setMsg("");
        }
      }
      return Array.from(set);
    });
  };

  const renderTypeBadges = (types) => {
    if (!Array.isArray(types) || types.length === 0) return null;
    return (
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 4 }}>
        {types.map((key) => {
          const meta = TYPE_META[key] || { icon: '🔹', label: key, short: key };
          return (
            <span
              key={key}
              title={meta.description || meta.label}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 4,
                border: '1px solid rgba(255,255,255,0.15)',
                borderRadius: 999,
                padding: '2px 8px',
                fontSize: 12,
              }}
            >
              <span aria-hidden>{meta.icon}</span>
              <span>{meta.short || meta.label}</span>
            </span>
          );
        })}
      </div>
    );
  };

  const renderPublicSectionList = (section) => {
    if (publicErr) {
      return <ErrorText style={{ marginTop: 8 }}>{publicErr}</ErrorText>;
    }
    const hasFetched = Object.prototype.hasOwnProperty.call(publicGroups, section.key);
    const isLoading = publicLoading && !hasFetched;
    if (!hasFetched || isLoading) {
      return (
        <div style={{ display: 'grid', gap: 10, marginTop: 8 }}>
          <SkeletonCard lines={3} />
          <SkeletonCard lines={3} />
        </div>
      );
    }
    const rows = publicGroups[section.key] || [];
    if (rows.length === 0) {
      return <p style={{ opacity: 0.75, marginTop: 8 }}>{section.empty}</p>;
    }
    const icon = TYPE_META[section.key]?.icon || '🔹';
    return (
      <ul style={{ listStyle: 'none', padding: 0, margin: 0, marginTop: 12, display: 'grid', gap: 10 }}>
        {rows.map((g) => (
          <li
            key={g.group_id || g.display_id}
            style={{
              border: '1px solid rgba(255,255,255,0.12)',
              borderRadius: 10,
              padding: 12,
              display: 'flex',
              flexDirection: 'column',
              gap: 6,
              background: 'rgba(18,18,22,0.45)'
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 600 }}>
              <span aria-hidden style={{ fontSize: 16 }}>{icon}</span>
              <span>{g.name}</span>
              <IdPeek id={g.display_id} />
            </div>
            {renderTypeBadges(g.types)}
          </li>
        ))}
      </ul>
    );
  };

  const saveTypes = async () => {
    if (!selected?.id) return;
    setSavingTypes(true); setErr(""); setMsg("");
    try {
      await updateGroupTypes(selected.id, typesDraft);
      const normalized = normalizeTypes(typesDraft);
      setSelected((s) => ({ ...s, types: normalized }));
      setTeams((ts) => ts.map((t) => t.id === selected.id ? { ...t, types: normalized } : t));
      setMsg('Group types updated.');
    } catch (e) {
      setErr(e.message || 'Failed to update group types');
    } finally { setSavingTypes(false); }
  };

  // Handlers for TeamMembers component (accept teamId explicitly)
  const changeRole = async (userId, role) => {
    setErr(""); setMsg("");
    try {
      await setMemberRoleRPC(selected.id, userId, role);
      await loadMembers(selected);
      setMsg("Role updated.");
    } catch (e) {
      setErr(e.message || "Failed to update role");
    }
  };

  const handleChangeRole = async (teamId, userId, role) => {
    setErr("");
    try {
      await setMemberRoleRPC(teamId, userId, role);
      if (selected?.id === teamId) await loadMembers(selected);
    } catch (e) { setErr(e.message || "Failed to update role"); }
  };

  const removeMember = async (userId) => {
    if (!window.confirm("Remove this member from the team?")) return;
    setErr(""); setMsg("");
    try {
      await removeMemberRPC(selected.id, userId);
      await loadMembers(selected);
      setMsg("Member removed.");
    } catch (e) {
      setErr(e.message || "Failed to remove member");
    }
  };

  const cancelInvite = async (teamId, userId) => {
    setErr("");
    try {
      const { cancelInvitation, listTeamInvitations } = await import('./teams.api');
      await cancelInvitation(teamId, userId);
      const inv = await listTeamInvitations(teamId);
      setInvites(inv);
    } catch (e) { setErr(e.message || "Failed to cancel invitation"); }
  };

  const handleAddMember = async (teamId, email, role) => {
    setErr("");
    try {
      await addMemberByEmailRPC(teamId, email, role);
      if (selected?.id === teamId) await loadMembers(selected);
      // Refresh invites immediately so pending invitation appears without tab change
      try {
        const { listTeamInvitations } = await import('./teams.api');
        const inv = await listTeamInvitations(teamId);
        setInvites(inv);
      } catch (e) {
        console.warn('Failed to refresh invitations', e?.message || e);
      }
    } catch (e) { setErr(e.message || "Failed to add member"); }
  };

  const handleRemoveMember = async (teamId, userId) => {
    if (!window.confirm("Remove this member from the team?")) return;
    setErr("");
    try {
      await removeMemberRPC(teamId, userId);
      if (selected?.id === teamId) await loadMembers(selected);
    } catch (e) { setErr(e.message || "Failed to remove member"); }
  };

  const handleLeaveTeam = async (teamId, userId) => {
    if (!window.confirm("Leave this group?")) return;
    setErr(""); setMsg("");
    try {
      await removeMemberRPC(teamId, userId);
      // If it's me and the current team, navigate back
      if (userId === currentUserId && selected?.id === teamId) {
        setTeams((ts) => ts.filter((t) => t.id !== teamId));
        backToList();
      } else if (selected?.id === teamId) {
        await loadMembers(selected);
      }
      setMsg(userId === currentUserId ? "You left the group." : "Member removed.");
    } catch (e) { setErr(e.message || "Failed to leave group"); }
  };

  const handleDeleteTeam = async (teamId) => {
    if (!window.confirm("Delete group? This cannot be undone.")) return;
    setErr(""); setMsg("");
    try {
      const t = teams.find(x => x.id === teamId);
      const deletedName = t?.name || t?.group_name || '';
      await deleteTeamRPC(teamId);
      setTeams((ts) => ts.filter((t) => t.id !== teamId));
      if (selected?.id === teamId) backToList();
      setMsg("Group deleted.");
      try { addToast(deletedName ? `Deleted ${deletedName}.` : 'Group deleted.'); } catch {}
    } catch (e) { setErr(e.message || "Failed to delete group"); }
  };

  if (loading) return (
    <Page>
      <div style={{ marginTop: 16 }}>
        <SkeletonCard lines={4} />
        <SkeletonCard lines={4} style={{ marginTop: 12 }} />
      </div>
    </Page>
  );

  return (
    <>
      {err && <ErrorText style={{ marginBottom: 8 }}>{err}</ErrorText>}
      {msg && <InfoText style={{ marginBottom: 8 }}>{msg}</InfoText>}

      {!selected ? (
        <div style={{ marginTop: 16 }}>
          {/* Use the global FAB (+) to create a group; the form appears in the right panel. */}
          <div style={{ marginTop: 20 }}>
              {teams.length === 0 ? (
                <p style={{ opacity: 0.8 }}>No groups yet. Use the “+ Create group” button to get started.</p>
              ) : (
                <ul style={{ listStyle: "none", padding: 0, margin: 0, display:'grid', gap:10, gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))' }}>
                  {teams.map((t) => (
                    <li
                      key={t.id}
                      style={{
                        border: "1px solid rgba(255,255,255,0.12)",
                        borderRadius: 10,
                        padding: 12,
                        background: 'rgba(18,18,22,0.45)',
                        minHeight: 160,
                        display: "flex",
                        flexDirection: 'column',
                        justifyContent: "space-between",
                      }}
                    >
                      <div>
                        <div style={{ fontWeight: 600, display: 'flex', alignItems: 'center', gap: 6 }}>
                          <span>{t.name}</span>
                          <IdPeek id={t.display_id} />
                        </div>
                        <div style={{ opacity: 0.75, fontSize: 12 }}>
                          you are {t.role}{t.public_listing ? ' · public' : ''}
                        </div>
                        {renderTypeBadges(t.types)}
                        <MemberAvatars teamId={t.id} />
                      </div>
                      <div style={{ display:'flex', justifyContent:'flex-end', gap: 8 }}>
                        <button title="Updates" aria-label="Updates" className="inline-flex items-center justify-center w-8 h-8 rounded border border-white/20 hover:bg-white/10"
                          onClick={() => { try { const sp=new URLSearchParams(location.search||''); sp.set('team', t.id); sp.set('rpanel','updates'); sp.delete('tab'); sp.delete('group'); sp.delete('user'); navigate(`/groups?${sp.toString()}`);} catch {} }}>
                          <Megaphone size={16} />
                        </button>
                        <button title="Members" aria-label="Members" className="inline-flex items-center justify-center w-8 h-8 rounded border border-white/20 hover:bg-white/10"
                          onClick={() => { try { const sp=new URLSearchParams(location.search||''); sp.set('team', t.id); sp.set('rpanel','members'); sp.delete('tab'); sp.delete('group'); sp.delete('user'); navigate(`/groups?${sp.toString()}`);} catch {} }}>
                          <UsersIcon size={16} />
                        </button>
                        <button title="Calendar" aria-label="Calendar" className="inline-flex items-center justify-center w-8 h-8 rounded border border-white/20 hover:bg-white/10"
                          onClick={() => { try { const sp=new URLSearchParams(location.search||''); sp.set('team', t.id); sp.set('rpanel','calendar'); sp.delete('tab'); sp.delete('group'); sp.delete('user'); navigate(`/groups?${sp.toString()}`);} catch {} }}>
                          <Calendar size={16} />
                        </button>
                        <button title="Admin" aria-label="Admin" className="inline-flex items-center justify-center w-8 h-8 rounded border border-white/20 hover:bg-white/10"
                          onClick={() => { try { const sp=new URLSearchParams(location.search||''); sp.set('team', t.id); sp.set('rpanel','admin'); sp.delete('tab'); sp.delete('group'); sp.delete('user'); navigate(`/groups?${sp.toString()}`);} catch {} }}>
                          <Settings size={16} />
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
          </div>
        </div>
      ) : (
        <div style={{ marginTop: 16 }}>
          <Breadcrumbs
            items={[
              { label: 'Groups', onClick: (e) => { e.preventDefault?.(); backToList(); } },
              { label: (<><span style={{ fontWeight: 800 }}>{selected.name}</span><IdPeek id={selected.display_id} /></>) },
            ]}
            style={{ marginBottom: 8, fontSize: 28, opacity: 1, lineHeight: 1.1 }}
          />
          {renderTypeBadges(selected.types)}

          <div style={{ marginTop: 16 }}>

            <Tabs
              value={teamTab}
              onChange={(v) => {
                // If already on Calendar and user clicks Calendar again, issue a reset signal
                if (v === 'calendar' && teamTab === 'calendar') {
                  setCalendarResetTick((x) => x + 1);
                }
                setTeamTab(v);
                setErr("");
                setMsg("");
                // sync to route query when a team is open
                if (selected?.id) {
                  const sp = new URLSearchParams(location.search);
                  sp.set('tab', v);
                  sp.set('team', selected.id);
                  navigate(`/groups?${sp.toString()}`, { replace: true });
                }
              }}
              style={{ marginTop: 8, marginBottom: 16 }}
            >
              <Tab value="updates" label="Updates">
                <TeamUpdates team={selected} isAdmin={isAdmin} active={teamTab==='updates'} />
              </Tab>
              <Tab value="members" label="Members">
                {membersLoading ? (
                  <div style={{ display: 'grid', gap: 10 }}>
                    <SkeletonCard lines={4} />
                    <SkeletonCard lines={4} />
                  </div>
                ) : (
                  <TeamMembers
                    team={selected}
                    members={members}
                    currentUserId={currentUserId}
                    isAdmin={isAdmin}
                    onChangeRole={handleChangeRole}
                    onAddMember={handleAddMember}
                    onRemoveMember={handleRemoveMember}
                    onLeaveTeam={handleLeaveTeam}
                    onDeleteTeam={handleDeleteTeam}
                    showDeleteTeamControl={false}
                  />
                )}
              </Tab>
              <Tab value="calendar" label="Calendar">
            <CalendarPanel
              team={selected}
              autoManageTarget={manageTarget}
              onAutoManageHandled={() => { setManageTarget(null); }}
              showBreadcrumbs={false}
              resetToListSignal={calendarResetTick}
            />
              </Tab>
              {isAdmin && (
                <Tab value="admin" label="Admin">
                  <div style={{ display: "grid", gap: 12 }}>
                    <h3 style={{ margin: "16px 0 6px", fontSize: 16 }}>Group administration</h3>
                    <div style={{ borderTop: "1px solid rgba(255,255,255,0.1)", margin: "6px 0 12px" }} />
                    <div>
                      <h4 style={{ margin: '0 0 6px', fontSize: 14 }}>Group name</h4>
                      <div style={{ display: 'grid', gap: 8, maxWidth: 560 }}>
                        <Label>
                          Name (non-unique)
                          <Input
                            placeholder="Group name"
                            value={nameDraft}
                            onChange={(e)=> setNameDraft(e.target.value)}
                          />
                        </Label>
                      </div>
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 6px', fontSize: 14 }}>Unique ID</h4>
                      <div style={{ display: 'grid', gap: 6, maxWidth: 420 }}>
                        <Label>
                          Unique ID (username)
                          <Input
                            placeholder="e.g. my-group"
                            value={displayIdDraft}
                            maxLength={32}
                            onChange={(e)=> setDisplayIdDraft(e.target.value)}
                          />
                        </Label>
                        <div style={{ fontSize: 12, opacity: 0.8 }}>
                          {displayIdDraft ? (
                            displayIdStatus === 'checking' ? 'Checking availability…' :
                            displayIdStatus === 'invalid' ? 'Only letters, numbers, dashes, and underscores are allowed.' :
                            displayIdStatus === 'taken' ? 'This ID is already taken.' :
                            displayIdStatus === 'available' ? 'ID is available.' : ''
                          ) : 'Leave blank to clear the unique ID.'}
                        </div>
                      </div>
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 6px', fontSize: 14 }}>Public profile</h4>
                      <div style={{ display: 'grid', gap: 8, maxWidth: 560 }}>
                        <Label>
                          Website
                          <Input type="url" value={siteDraft} onChange={(e)=> setSiteDraft(e.target.value)} placeholder="https://example.com" />
                        </Label>
                        <Label>
                          Bio
                          <textarea
                            rows={5}
                            value={bioDraft}
                            onChange={(e)=> setBioDraft(e.target.value)}
                            style={{ width: '100%', background:'#0f0f14', color:'inherit', border:'1px solid rgba(255,255,255,0.2)', borderRadius:10, padding:'10px 12px' }}
                          />
                        </Label>
                      </div>
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 6px', fontSize: 14 }}>Group taxonomy</h4>
                      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
                        {TYPES.map(t => (
                          <label key={t.key} style={{ display:'inline-flex', alignItems:'center', gap:6, border:'1px solid rgba(255,255,255,0.15)', borderRadius:8, padding:'6px 10px' }}>
                            <input type="checkbox" checked={typesDraft?.includes(t.key)} onChange={()=>toggleType(t.key)} />
                            <span aria-hidden style={{ fontSize: 16 }}>{t.icon}</span>
                            <span>{t.label}</span>
                          </label>
                        ))}
                      </div>
                      {/* Types saved via the single Save button below */}
                      <InfoText style={{ marginTop: 8, fontSize: 12, lineHeight: 1.6 }}>
                        <div><strong>Act</strong> — Performs publicly at shows. Selecting Act deselects Practice Group.</div>
                        <div><strong>Practice Group</strong> — Rehearses stagework without public performances. Selecting Practice Group deselects Act.</div>
                        <div><strong>School</strong> — Runs workshops, classes, or training programs.</div>
                        <div><strong>Producer</strong> — Produces and runs public shows (non-venue specific). Selecting Producer deselects Theatre.</div>
                        <div><strong>Theatre</strong> — Operates a semi-permanent venue with multiple public shows. Selecting Theatre deselects Producer.</div>
                      </InfoText>
                    </div>
                    <div>
                      <h4 style={{ margin: '12px 0 6px', fontSize: 14 }}>Public listing</h4>
                      <label style={{ display:'inline-flex', alignItems:'center', gap:8 }}>
                        <input type="checkbox" checked={!!publicDraft} onChange={(e)=> setPublicDraft(e.target.checked)} />
                        <span>List this group publicly</span>
                      </label>
                      {/* Visibility saved via the single Save button below */}
                    </div>
                    <Row>
                      <Button onClick={saveAllChanges} disabled={savingAll || displayIdStatus === 'taken' || displayIdStatus === 'invalid'}>
                        {savingAll ? 'Saving…' : 'Save changes'}
                      </Button>
                      <DangerButton onClick={deleteTeam}>Delete group</DangerButton>
                    </Row>
                  </div>
                </Tab>
              )}
            </Tabs>
          </div>
        </div>
      )}
    </>
  );
}

const styles = {
  select: {
    background: "#0f0f14",
    color: "white",
    border: "1px solid rgba(255,255,255,0.2)",
    borderRadius: 10,
    padding: "10px 12px",
    outline: "none",
  },
};
  function MemberAvatars({ teamId }) {
    const [people, setPeople] = useState([]);
    useEffect(() => {
      let active = true;
      (async () => {
        try { const rows = await listTeamMembersRPC(teamId); if (active) setPeople(rows || []); } catch {}
      })();
      return () => { active = false; };
    }, [teamId]);
    if (!teamId) return null;
    return (
      <div style={{ display:'flex', gap:10, flexWrap:'wrap', marginTop: 10 }}>
        {(people || []).map((m) => (
          <div key={m.user_id} style={{ width: 56, textAlign:'center' }}>
            <button title={m.display_name || m.email || ''}
              onClick={() => {
                try {
                  const sp = new URLSearchParams(location.search);
                  sp.set('user', m.user_id);
                  sp.delete('rpanel');
                  sp.delete('team');
                  sp.delete('tab');
                  navigate(`${location.pathname}?${sp.toString()}`);
                } catch {}
              }}
              className="inline-flex items-center justify-center w-12 h-12 rounded-full border border-white/20 bg-white/10 text-xs font-semibold"
              style={{ display:'inline-flex' }}
            >
              {(() => {
                const name = (m.display_name || m.email || '').trim();
                const parts = name.split(/\s+/).filter(Boolean);
                const two = (parts[0]?.[0] || '') + (parts[1]?.[0] || (parts[0]?.[1] || ''));
                return (two || '?').toUpperCase();
              })()}
            </button>
            <div style={{ marginTop: 4, fontSize: 11, opacity: 0.85, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>
              {(m.display_name || m.email || '').split('@')[0]}
            </div>
          </div>
        ))}
      </div>
    );
  }
