// src/teams/components/CommunityPanel.jsx
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Card, H1, Row, Label, Input, Button, GhostButton, ErrorText, InfoText, Tabs, Tab, SkeletonCard } from 'components/ui';
import { useNavigate } from 'react-router-dom';
import { useToast } from 'components/toast';
import { listPublicGroupsByType, listPublicIndividuals } from '../teams.api';
import { listPublicEvents } from '../teams.api';
import EventOverviewPanel from 'eventui/EventOverviewPanel';

const TYPE_META = {
  act: { label: 'Act', icon: '🎭' },
  practice_group: { label: 'Practice Group', icon: '🧪' },
  school: { label: 'School', icon: '🏫' },
  theatre: { label: 'Theatre', icon: '🎟️' },
  producer: { label: 'Producer', icon: '🎬' },
};

function TypeBadges({ types = [] }) {
  if (!Array.isArray(types) || types.length === 0) return null;
  return (
    <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 4 }}>
      {types.map((key) => {
        const meta = TYPE_META[key] || { label: key, icon: '🔹' };
        return (
          <span key={key} style={{ border: '1px solid rgba(255,255,255,0.15)', borderRadius: 999, padding: '2px 8px', fontSize: 12, display: 'inline-flex', alignItems: 'center', gap: 4 }}>
            <span aria-hidden>{meta.icon}</span>
            <span>{meta.label}</span>
          </span>
        );
      })}
    </div>
  );
}

export default function CommunityPanel() {
  const { add: addToast } = useToast();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');
  const [groups, setGroups] = useState([]); // [{ group_id, name, display_id, types, website, bio }]
  const [individuals, setIndividuals] = useState([]); // [{ owner_id, display_name, display_id, website, bio }]
  const [filters, setFilters] = useState({ act: true, practice_group: true, school: true, theatre: true, producer: true });
  const [tab, setTab] = useState('groups'); // 'groups' | 'individuals'
  const [search, setSearch] = useState('');
  const [open, setOpen] = useState(null); // { group }
  const [events, setEvents] = useState([]);
  const [eventsLoading, setEventsLoading] = useState(false);

  const loadGroups = useCallback(async () => {
    setLoading(true); setErr('');
    try {
      const keys = Object.keys(TYPE_META);
      const lists = await Promise.all(keys.map(async (k) => {
        const rows = await listPublicGroupsByType(k);
        return (rows || []).map(r => ({ ...r, types: Array.isArray(r.types) ? r.types : [] }));
      }));
      // Merge unique by group_id
      const map = new Map();
      lists.flat().forEach(g => {
        const id = g.group_id || g.display_id || Math.random().toString(36);
        if (!map.has(id)) map.set(id, g);
      });
      setGroups(Array.from(map.values()));
      // Also fetch individuals once
      try {
        const ppl = await listPublicIndividuals();
        setIndividuals(Array.isArray(ppl) ? ppl : []);
      } catch (_) { /* non-fatal */ }
    } catch (e) {
      setErr(e.message || 'Failed to load community groups'); addToast(e.message || 'Failed to load community', 'error');
      setGroups([]);
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { loadGroups(); }, [loadGroups]);

  const filtered = useMemo(() => {
    const actives = new Set(Object.keys(filters).filter(k => filters[k]));
    const term = (search || '').trim().toLowerCase();
    return (groups || []).filter(g => {
      const hasType = (g.types || []).some(t => actives.has(t));
      if (!hasType) return false;
      if (!term) return true;
      return (g.name || '').toLowerCase().includes(term) || (g.display_id || '').toLowerCase().includes(term);
    }).sort((a,b)=> (a.name||'').localeCompare(b.name||''));
  }, [groups, filters, search]);

  const filteredIndividuals = useMemo(() => {
    if (tab !== 'individuals') return [];
    const term = (search || '').trim().toLowerCase();
    const list = Array.isArray(individuals) ? individuals : [];
    return list.filter(p => {
      if (!term) return true;
      return (p.display_name || '').toLowerCase().includes(term) || (p.display_id || '').toLowerCase().includes(term);
    }).sort((a,b)=> (a.display_name||'').localeCompare(b.display_name||''));
  }, [individuals, tab, search]);

  const openGroup = async (g) => {
    setOpen({ group: g });
    setEvents([]); setEventsLoading(true);
    try {
      const now = new Date();
      const end = new Date(); end.setDate(end.getDate() + 90);
      const rows = await listPublicEvents(now.toISOString(), end.toISOString(), null);
      const evs = (rows || []).filter(ev => (ev.group_id && g.group_id && ev.group_id === g.group_id));
      setEvents(evs || []);
    } catch (e) { /* ignore */ }
    finally { setEventsLoading(false); }
  };

  const closeGroup = () => { setOpen(null); setEvents([]); };

  const [openOverview, setOpenOverview] = useState(null); // { eventId, row }

  const normalizeUrl = useCallback((raw) => {
    if (!raw) return '';
    const s = String(raw).trim();
    if (/^https?:\/\//i.test(s)) return s;
    return `http://${s}`;
  }, []);

  return (
    <div style={{ marginTop: 16 }}>
      <div>
        <Tabs value={tab} onChange={setTab} suppressContent>
          <Tab value="groups" label="Groups" />
          <Tab value="individuals" label="Individuals" />
        </Tabs>
        <Row style={{ gap: 12, flexWrap: 'wrap', marginTop: 8 }}>
          <Input value={search} onChange={(e)=> setSearch(e.target.value)} placeholder={tab==='groups' ? 'Search group name' : 'Search name or ID'} />
        </Row>
        {tab==='groups' && (
          <Row style={{ gap:10, alignItems:'center', flexWrap:'wrap' }}>
            {Object.keys(TYPE_META).map((k) => (
              <label key={k} style={{ display:'inline-flex', alignItems:'center', gap:6 }}>
                <input type="checkbox" checked={!!filters[k]} onChange={(e)=> setFilters(prev => ({ ...prev, [k]: !!e.target.checked }))} />
                <span>{TYPE_META[k].label}</span>
              </label>
            ))}
          </Row>
        )}
        {err && <ErrorText style={{ marginTop: 8 }}>{err}</ErrorText>}
        {loading ? (
          <div style={{ display: 'grid', gap: 10, marginTop: 12 }}>
            <SkeletonCard lines={3} />
            <SkeletonCard lines={3} />
            <SkeletonCard lines={3} />
          </div>
        ) : (
          <ul style={{ listStyle:'none', padding:0, margin: '12px 0', display:'grid', gap:10, gridTemplateColumns:'repeat(auto-fill, minmax(220px, 1fr))' }}>
            {tab==='groups' && filtered.map((g) => (
              <li
                key={g.group_id}
                onClick={()=> navigate(`/community?group=${g.group_id}`)}
                style={{ cursor:'pointer', border:'1px solid rgba(255,255,255,0.12)', borderRadius:10, padding:12, background:'rgba(18,18,22,0.45)', minHeight:160, display:'flex', flexDirection:'column', justifyContent:'space-between' }}
              >
                <div>
                  <div style={{ fontWeight:600 }}>{g.name}</div>
                  <TypeBadges types={g.types} />
                </div>
              </li>
            ))}
            {tab==='individuals' && filteredIndividuals.map(p => (
              <li key={p.owner_id} style={{ border:'1px solid rgba(255,255,255,0.12)', borderRadius:10, padding:10, background:'rgba(18,18,22,0.45)', minHeight:160, display:'flex', flexDirection:'column', justifyContent:'space-between' }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
                  <div>
                    <div style={{ fontWeight:600 }}>{p.display_name || p.display_id || '(individual)'}</div>
                    {p.display_id && <div style={{ fontSize:12, opacity:0.75 }}>ID: {p.display_id}</div>}
                  </div>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>

      {open && (
        <div role="dialog" aria-modal onClick={(e)=> { if (e.target === e.currentTarget) closeGroup(); }}
             style={{ position:'fixed', inset:0, background:'rgba(0,0,0,0.55)', display:'grid', placeItems:'center', zIndex: 1000 }}>
          <Card style={{ width:'min(900px,92vw)', maxHeight:'90vh', overflow:'auto', padding: 20 }}>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
              <div style={{ fontWeight:800, fontSize:20 }}>{open.group.name}</div>
              <GhostButton onClick={closeGroup}>Close</GhostButton>
            </div>
            <TypeBadges types={open.group.types} />
            {open.group.website && (
              <div style={{ marginTop: 6 }}>
                Website: <a href={normalizeUrl(open.group.website)} target="_blank" rel="noopener noreferrer" style={{ color:'#7aa2ff' }}>{normalizeUrl(open.group.website)}</a>
              </div>
            )}
            {open.group.bio && (
              <div style={{ marginTop: 6, whiteSpace:'pre-wrap', opacity:0.9 }}>{open.group.bio}</div>
            )}
            <div style={{ marginTop: 12 }}>
              <h4 style={{ margin:'8px 0 6px', fontSize:14 }}>Forthcoming public events</h4>
              {eventsLoading ? (
                <p style={{ opacity:0.75 }}>Loading…</p>
              ) : (events.length === 0 ? (
                <p style={{ opacity:0.75 }}>No upcoming public events.</p>
              ) : (
                <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:8 }}>
                  {events.map((ev) => (
                    <li key={ev.event_id} style={{ border:'1px solid rgba(255,255,255,0.12)', borderRadius:10, padding:10 }}>
                      <div style={{ fontWeight:600 }}>{ev.summary || '(untitled)'}</div>
                      <div style={{ opacity:0.8, fontSize:12 }}>{new Date(ev.dtstart).toLocaleString()}</div>
                      <Row>
                        <GhostButton onClick={() => navigate(`/events/${ev.event_id}`)}>View Event</GhostButton>
                      </Row>
                    </li>
                  ))}
                </ul>
              ))}
            </div>
          </Card>
        </div>
      )}

      {openOverview && (
        <EventOverviewPanel
          eventId={openOverview.eventId}
          onClose={() => setOpenOverview(null)}
          title={openOverview.row.summary || ''}
          description={openOverview.row.description || ''}
          location={openOverview.row.location || ''}
          dtstart={openOverview.row.dtstart}
          dtend={openOverview.row.dtend}
          tzid={openOverview.row.tzid || 'UTC'}
          status={openOverview.row.status || 'TENTATIVE'}
          category={(openOverview.row.category || '').toLowerCase()}
          calendarId={openOverview.row.calendar_id || null}
        />
      )}
    </div>
  );
}
