import { useEffect, useMemo, useState } from 'react';
import { Button, GhostButton, DangerButton, Label, Input, InfoText, ErrorText, Row } from 'components/ui';
import { useToast } from 'components/toast';
import { listMyTeams, updateGroupTypes, updateGroupPublicListing, updateGroupProfile, updateGroupDisplayId, renameTeamRPC, deleteTeamRPC } from 'teams/teams.api';
import { useNavigate, useLocation } from 'react-router-dom';

const TYPE_META = {
  act: { label: 'Act', icon: '🎭' },
  practice_group: { label: 'Practice Group', icon: '🧪' },
  school: { label: 'School', icon: '🏫' },
  theatre: { label: 'Theatre', icon: '🎟️' },
  producer: { label: 'Producer', icon: '🎬' },
};
const MUTUALLY_EXCLUSIVE = { act: ['practice_group'], practice_group: ['act'], producer: ['theatre'], theatre: ['producer'] };
const TYPES = Object.entries(TYPE_META).map(([key, meta]) => ({ key, ...meta }));

function normalizeTypes(values = []) {
  const set = new Set();
  (Array.isArray(values) ? values : []).forEach((key) => {
    if (!TYPE_META[key]) return;
    const conflicts = MUTUALLY_EXCLUSIVE[key] || [];
    conflicts.forEach((c) => set.delete(c));
    set.add(key);
  });
  return Array.from(set);
}

export default function RightGroupAdmin({ groupId }) {
  const { add: addToast } = useToast();
  const navigate = useNavigate();
  const location = useLocation();
  const [team, setTeam] = useState(null);
  const [name, setName] = useState('');
  const [displayId, setDisplayId] = useState('');
  const [website, setWebsite] = useState('');
  const [bio, setBio] = useState('');
  const [types, setTypes] = useState([]);
  const [isPublic, setIsPublic] = useState(false);
  const [saving, setSaving] = useState(false);
  const [err, setErr] = useState('');
  const [msg, setMsg] = useState('');

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const list = await listMyTeams();
        const t = (list || []).find(x => String(x.id) === String(groupId));
        if (!t) { if (active) setTeam(null); return; }
        if (active) {
          setTeam(t);
          setName(t.name || t.group_name || '');
          setDisplayId(t.display_id || t.group_display_id || '');
          setWebsite(t.website || '');
          setBio(t.bio || '');
          setTypes(normalizeTypes(t.types || []));
          setIsPublic(!!t.public_listing);
        }
      } catch {
        if (active) setTeam(null);
      }
    })();
    return () => { active = false; };
  }, [groupId]);

  const toggleType = (key) => {
    setTypes((prev) => {
      const cur = new Set(prev || []);
      if (cur.has(key)) { cur.delete(key); return Array.from(cur); }
      (MUTUALLY_EXCLUSIVE[key] || []).forEach((c) => cur.delete(c));
      cur.add(key);
      return normalizeTypes(Array.from(cur));
    });
  };

  const save = async () => {
    if (!team?.id) return;
    setSaving(true); setErr(''); setMsg('');
    try {
      if ((name || '') !== (team.name || team.group_name || '')) await renameTeamRPC(team.id, name || '');
      const site = (website || '').trim();
      const b = (bio || '').trim();
      await updateGroupProfile(team.id, { website: site, bio: b });
      await updateGroupDisplayId(team.id, displayId || null);
      await updateGroupTypes(team.id, types);
      await updateGroupPublicListing(team.id, !!isPublic);
      setMsg('Saved ✓');
      try {
        addToast('Changes saved.');
      } catch {}
      // Notify main section to update team list/details
      try {
        const patch = { name, display_id: displayId || null, website: site || null, bio: b || null, types, public_listing: !!isPublic };
        window.dispatchEvent(new CustomEvent('group:updated', { detail: { groupId: team.id, patch } }));
      } catch {}
    } catch (e) { setErr(e.message || 'Save failed'); }
    finally { setSaving(false); }
  };

  if (!team) return <div style={{ opacity: 0.75 }}>Group not found.</div>;

  return (
    <div style={{ display:'grid', gap: 12 }}>
      <div>
        <Label>
          Group name
          <Input value={name} onChange={(e)=> setName(e.target.value)} />
        </Label>
      </div>
      <div>
        <Label>
          Unique ID (username)
          <Input value={displayId} onChange={(e)=> setDisplayId(e.target.value)} maxLength={32} placeholder="e.g. my-group" />
        </Label>
      </div>
      <div>
        <Label>
          Website
          <Input value={website} onChange={(e)=> setWebsite(e.target.value)} placeholder="example.org" />
        </Label>
      </div>
      <div>
        <Label>
          Bio
          <Input value={bio} onChange={(e)=> setBio(e.target.value)} placeholder="Short description" />
        </Label>
      </div>
      <div>
        <div style={{ marginBottom: 6, opacity: 0.9, fontWeight: 600 }}>Types</div>
        <div style={{ display:'flex', gap:10, flexWrap:'wrap' }}>
          {TYPES.map((t) => (
            <label key={t.key} style={{ display:'inline-flex', alignItems:'center', gap:6, border:'1px solid rgba(255,255,255,0.15)', borderRadius:8, padding:'6px 10px' }}>
              <input type="checkbox" checked={types.includes(t.key)} onChange={()=> toggleType(t.key)} />
              <span aria-hidden style={{ fontSize: 16 }}>{t.icon}</span>
              <span>{t.label}</span>
            </label>
          ))}
        </div>
      </div>
      <label style={{ display:'inline-flex', alignItems:'center', gap:8 }}>
        <input type="checkbox" checked={!!isPublic} onChange={(e)=> setIsPublic(!!e.target.checked)} />
        <span>Public listing</span>
      </label>

      {err && <ErrorText>{err}</ErrorText>}
      {msg && <InfoText>{msg}</InfoText>}

      <Row>
        <Button disabled={saving} onClick={save}>{saving ? 'Saving…' : 'Save changes'}</Button>
      </Row>

      <div style={{ marginTop: 6 }}>
        <DangerButton onClick={async ()=> {
          if (!window.confirm('Delete group? This cannot be undone.')) return;
          const name = team?.name || team?.group_name || '';
          try {
            await deleteTeamRPC(team.id);
            try { addToast(name ? `Deleted ${name}.` : 'Group deleted.'); } catch {}
            try { window.dispatchEvent(new CustomEvent('group:deleted', { detail: { groupId: team.id, groupName: name } })); } catch {}
            try {
              const sp = new URLSearchParams(location.search || '');
              ['rpanel','team','tab','user','group','create','event','rid'].forEach(k => sp.delete(k));
              navigate(`/groups?${sp.toString()}`);
            } catch { navigate('/groups'); }
          } catch (e) {
            try { addToast(e?.message || 'Failed to delete group', 'error'); } catch {}
          }
        }}>Delete group</DangerButton>
      </div>
    </div>
  );
}
