import { useState, useEffect } from "react";

/**
 * Renders a compact clickable ellipsis that reveals/copies an identifier.
 * Shows the id via the native title tooltip and copies it to the clipboard when clicked.
 */
export default function IdPeek({ id, className = "", style }) {
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    let timer;
    if (copied) {
      timer = setTimeout(() => setCopied(false), 1500);
    }
    return () => { if (timer) clearTimeout(timer); };
  }, [copied]);

  if (!id) return null;

  const handleCopy = async (event) => {
    event.stopPropagation();
    try {
      if (navigator?.clipboard?.writeText) {
        await navigator.clipboard.writeText(id);
        setCopied(true);
      } else {
        // Fallback prompt for environments without clipboard API
        window.prompt("Copy id", id);
      }
    } catch (err) {
      console.warn("Failed to copy id", err);
    }
  };

  const handleKeyDown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      handleCopy(event);
    }
  };

  return (
    <span
      role="button"
      tabIndex={0}
      onClick={handleCopy}
      onKeyDown={handleKeyDown}
      onMouseLeave={() => setCopied(false)}
      title={copied ? "Copied!" : `ID: ${id}`}
      className={className}
      style={{
        cursor: "pointer",
        opacity: 0.75,
        fontSize: "0.85em",
        display: "inline-flex",
        alignItems: "center",
        marginLeft: 6,
        userSelect: "none",
        ...style,
      }}
    >
      [{copied ? "✓" : "…"}]
    </span>
  );
}
