import { useEffect, useState } from 'react';
import { listPublicIndividuals, getOwnersDisplayMap } from 'teams/teams.api';
import { InfoText } from 'components/ui';

function Avatar({ name = '', size = 28 }) {
  const initials = (() => {
    const parts = (name || '').trim().split(/\s+/);
    const two = (parts[0]?.[0] || '') + (parts[1]?.[0] || (parts[0]?.[1] || ''));
    return (two || '?').toUpperCase();
  })();
  return (
    <div style={{ width: size, height: size }} className="inline-flex items-center justify-center rounded-full border border-white/20 bg-white/10 text-xs font-semibold">
      {initials}
    </div>
  );
}

export default function OwnerSummaryPanel({ ownerId }) {
  const [row, setRow] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const list = await listPublicIndividuals();
        let match = (list || []).find(p => String(p.owner_id) === String(ownerId));
        if (!match) {
          // Fallback to owners table for a display name if not public
          const map = await getOwnersDisplayMap([ownerId]);
          const name = map.get(ownerId) || null;
          if (name) match = { owner_id: ownerId, display_name: name };
        }
        if (active) setRow(match || null);
      } catch { if (active) setRow(null); }
      finally { if (active) setLoading(false); }
    })();
    return () => { active = false; };
  }, [ownerId]);

  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (!row) return <div style={{ opacity: 0.75 }}>User not found.</div>;

  const name = row.display_name || row.display_id || '(user)';
  return (
    <div>
      <div className="flex items-center gap-2">
        <Avatar name={name} size={32} />
        <div className="font-semibold">{name}</div>
      </div>
      {row.website && (
        <div className="mt-2">Website: <a href={/^https?:\/\//.test(row.website) ? row.website : `http://${row.website}`} target="_blank" rel="noreferrer" className="text-blue-300">{row.website}</a></div>
      )}
      {row.bio && (
        <div className="mt-2 opacity-90 whitespace-pre-wrap">{row.bio}</div>
      )}
      <InfoText style={{ marginTop: 6 }}>Owner ID: {String(ownerId)}</InfoText>
    </div>
  );
}
