// src/pages/Dashboard.jsx
import { useState, useEffect, useMemo, useCallback } from "react";
import { useAuth } from "auth/AuthContext";
import ProfilePanel from "profiles/ProfilePanel";
import TeamsPanel from "teams/TeamsPanel";
import CommunityPanel from "teams/components/CommunityPanel";
import ListingsPanel from "listings/ListingsPanel";
import { listMyOwnerNotifications, dismissOwnerNotification, respondAnyOwnerNotification, listMyInvitedEvents, listMyTeams, listGroupCalendars, fetchGroupEvents, fetchGroupOverrides, getCalendarOwnerInfo, listGroupOwnerNotifications, getEventsByIds, listOverridesForEvents } from "teams/teams.api";
import { signOut } from "auth/auth.api";
import { Card, H1, Tabs, Tab, GhostButton, Button, ErrorText, Row, Label, Input, InfoText, Select, SkeletonCard } from "components/ui";
import { useNavigate } from 'react-router-dom';
import { useToast } from "components/toast";
import { fmtRangeLocal, fmtTime, browserTZ, fmtDateTimeLocal } from "teams/utils/datetime";
import { expandEvents } from "calendar/expandOccurrences";
import EventOverviewPanel from "eventui/EventOverviewPanel";

const PARTSTAT_LABEL = {
  "NEEDS-ACTION": "Response needed",
  ACCEPTED: "Accepted",
  DECLINED: "Declined",
  TENTATIVE: "Tentative",
};

function toDateInputValue(date) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function toIsoStartOfDay(dateInput) {
  if (!dateInput) return null;
  return new Date(`${dateInput}T00:00:00`).toISOString();
}

function toIsoEndOfDay(dateInput) {
  if (!dateInput) return null;
  return new Date(`${dateInput}T23:59:59`).toISOString();
}

function InvitedEventsSection({ refreshSignal = 0, onRequestManage = () => {} }) {
  const today = useMemo(() => new Date(), []);
  const defaultEnd = useMemo(() => {
    const dt = new Date();
    dt.setDate(dt.getDate() + 30);
    return dt;
  }, []);

  const [startDate, setStartDate] = useState(() => toDateInputValue(today));
  const [endDate, setEndDate] = useState(() => toDateInputValue(defaultEnd));
  const [category, setCategory] = useState("all");
  const [events, setEvents] = useState([]);
  const [ownOccs, setOwnOccs] = useState([]); // occurrences from my groups
  const [calOwnerCache, setCalOwnerCache] = useState({}); // calendar_id -> owner info
  const [groupRoles, setGroupRoles] = useState({}); // group_id -> role
  const [groupMeta, setGroupMeta] = useState({}); // group_id -> { name, display_id }
  const [myGroups, setMyGroups] = useState([]); // [{ id, name, role }]
  const [openOverview, setOpenOverview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [availableCategories, setAvailableCategories] = useState([]);
  const [sourceFilter, setSourceFilter] = useState('all'); // 'all' | 'individual' | <groupId>
  const tz = useMemo(() => browserTZ(), []);

  const load = useCallback(async () => {
    if (!startDate || !endDate) {
      setEvents([]);
      return;
    }
    if (startDate > endDate) {
      setErr("Start date must be on or before the end date.");
      setEvents([]);
      return;
    }

    setErr("");
    setLoading(true);
    try {
      const startIso = toIsoStartOfDay(startDate);
      const endIso = toIsoEndOfDay(endDate);
      const categoryParam = category === "all" ? null : category;
      const rows = await listMyInvitedEvents(startIso, endIso, categoryParam);
      setEvents(rows || []);

      // Load my groups and expand their events into occurrences
      const myTeams = await listMyTeams();
      const myGroups = (myTeams || []).map(t => ({ id: t.id, role: (t.role || '').toLowerCase(), name: t.name || t.group_name || '', display_id: t.display_id || t.group_display_id || '' }));
      setMyGroups(myGroups);
      const rolesMap = {}; myGroups.forEach(g => rolesMap[g.id] = g.role);
      setGroupRoles(rolesMap);
      const metaMap = {}; myGroups.forEach(g => metaMap[g.id] = { name: g.name, display_id: g.display_id });
      setGroupMeta(metaMap);
      // For each group, fetch events+overrides and expand to occurrences within window
      const occsAll = [];
      const pendingInvites = []; // { group_id, event_id, recurrence_id|null }
      await Promise.all(myGroups.map(async (g) => {
        try {
          const cals = await listGroupCalendars(g.id);
          const calIds = (cals || []).map(c => c.id);
          const [ev, ov] = await Promise.all([
            fetchGroupEvents(g.id, startIso, endIso, calIds),
            fetchGroupOverrides(g.id, startIso, endIso, calIds),
          ]);
          const occs = expandEvents({ events: ev || [], overrides: ov || [], windowStart: startIso, windowEnd: endIso, capPerEvent: 50 });
          for (const m of occs) {
            const event = m.event || {};
            const override = m.override || {};
            const cat = (function(){
              const ext = (override.extended || event.extended || {});
              const c = (ext.category || (Array.isArray(event.categories)&&event.categories[0]) || '').toLowerCase();
              return c || '';
            })();
            if (categoryParam && cat !== categoryParam) continue;
            occsAll.push({
              source: 'group',
              event_id: m.eventId,
              override_id: m.overrideId || null,
              recurrence_id: m.recurrence_id,
              event_slot_id: null,
              slot_name: null,
              slot_offset_sec: null,
              slot_duration_sec: null,
              summary: override.summary || event.summary || '',
              description: override.description || event.description || '',
              location: override.location || event.location || '',
              dtstart: m.start || event.dtstart,
              dtend: m.end || event.dtend,
              tzid: override.tzid || event.tzid || 'UTC',
              category: cat,
              calendar_id: event.calendar_id,
              calendar_name: null,
              owner_id: null,
              owner_kind: null,
              owner_display: null,
              group_id: g.id,
              group_name: null,
              group_display_id: null,
              partstat: null,
              attendee_role: null,
              rsvp: null,
              event_status: override.status || event.status || 'TENTATIVE',
              organizer_name: event.organizer_name || null,
              organizer_email: event.organizer_email || null,
            });
          }

          // Also capture pending group invites (not yet accepted) so they show separately
          try {
            const notifs = await listGroupOwnerNotifications(g.id);
            for (const n of (notifs || [])) {
              const pending = (n?.type === 'ack' && !n?.ack_response && n?.payload && (n.payload.kind === 'event_roster_invite'));
              if (!pending) continue;
              const evId = n.payload?.event_id || null;
              const rid = n.payload?.recurrence_id || null;
              if (!evId) continue;
              pendingInvites.push({ group_id: g.id, event_id: evId, recurrence_id: rid || null });
            }
          } catch (_) { /* ignore notif failures per group */ }
        } catch (_) { /* ignore per-group failure to avoid breaking others */ }
      }));

      // Resolve pending invites into display rows
      if (pendingInvites.length > 0) {
        const eventIds = Array.from(new Set(pendingInvites.map(p => p.event_id)));
        const [eventRows, ovRows] = await Promise.all([
          getEventsByIds(eventIds),
          listOverridesForEvents(eventIds, startIso, endIso),
        ]);
        const byEvent = new Map((eventRows || []).map(e => [e.id, e]));
        const overrideKey = (eId, rid) => `${eId}|${new Date(rid).toISOString()}`;
        const byOverride = new Map((ovRows || []).map(ov => [overrideKey(ov.parent_event_id, ov.recurrence_id), ov]));

        for (const p of pendingInvites) {
          const event = byEvent.get(p.event_id);
          if (!event) continue;
          const ridIso = p.recurrence_id ? new Date(p.recurrence_id).toISOString() : null;
          const ov = (ridIso && byOverride.get(overrideKey(p.event_id, ridIso))) || null;
          const ext = (ov?.extended || event.extended || {});
          const cat = (ext?.category || (Array.isArray(event.categories) && event.categories[0]) || '').toLowerCase();
          if (categoryParam && cat !== categoryParam) continue;
          const dtstart = ridIso || ov?.dtstart || event.dtstart;
          const dtend = ov?.dtend || event.dtend;
          // Window filter for series-level invite
          if (!ridIso) {
            if ((startIso && new Date(dtstart) < new Date(startIso)) || (endIso && new Date(dtstart) > new Date(endIso))) continue;
          }
          occsAll.push({
            source: 'group',
            event_id: event.id,
            override_id: ov?.id || null,
            recurrence_id: ridIso,
            event_slot_id: null,
            slot_name: null,
            slot_offset_sec: null,
            slot_duration_sec: null,
            summary: ov?.summary || event.summary || '',
            description: ov?.description || event.description || '',
            location: ov?.location || event.location || '',
            dtstart,
            dtend,
            tzid: ov?.tzid || event.tzid || 'UTC',
            category: cat || '',
            calendar_id: event.calendar_id,
            calendar_name: null,
            owner_id: null,
            owner_kind: null,
            owner_display: null,
            group_id: p.group_id,
            group_name: null,
            group_display_id: null,
            partstat: 'NEEDS-ACTION',
            attendee_role: null,
            rsvp: true,
            event_status: ov?.status || event.status || 'TENTATIVE',
            organizer_name: event.organizer_name || null,
            organizer_email: event.organizer_email || null,
          });
        }
      }

      setOwnOccs(occsAll);
      // Build categories from both invited events and group calendar occurrences
      const cats = Array.from(new Set([
        ...((rows || []).map((r) => (r.category || "").toLowerCase())),
        ...((occsAll || []).map((r) => (r.category || "").toLowerCase())),
      ].filter((c) => c)));
      setAvailableCategories(cats.sort());
    } catch (e) {
      setErr(e.message || "Failed to load your event invites.");
      setEvents([]);
    } finally {
      setLoading(false);
    }
  }, [startDate, endDate, category]);

  useEffect(() => { load(); }, [load]);
  // Refresh when parent indicates tab activation
  useEffect(() => { load(); }, [refreshSignal]);

  // Merge invited rows + own group occurrences (dedupe by event_id + recurrence_id)
  const mergedRows = useMemo(() => {
    const map = new Map();
    // Use distinct keys per source to avoid unintended dedupe
    (events || []).forEach((r) => {
      const base = `${r.event_id}|${r.recurrence_id || r.dtstart}`;
      const k = `${base}|invited`;
      map.set(k, { ...r, __source: 'invited' });
    });
    (ownOccs || []).forEach((r) => {
      const base = `${r.event_id}|${r.recurrence_id || r.dtstart}`;
      const gid = r.group_id || 'unknown';
      const k = `${base}|group:${gid}`; // keep separate per team
      if (!map.has(k)) map.set(k, { ...r, __source: 'group' });
    });
    return Array.from(map.values())
      .sort((a,b) => new Date(a.dtstart).getTime() - new Date(b.dtstart).getTime());
  }, [events, ownOccs]);

  const sourceFiltered = useMemo(() => {
    if (sourceFilter === 'all') return mergedRows || [];
    if (sourceFilter === 'individual') return (mergedRows || []).filter(r => r.__source === 'invited');
    return (mergedRows || []).filter(r => r.__source === 'group' && r.group_id === sourceFilter);
  }, [mergedRows, sourceFilter]);

  const displayEvents = useMemo(() => (sourceFiltered || []).map((ev) => {
    const label = PARTSTAT_LABEL[ev.partstat] || (ev.partstat ? ev.partstat.replace(/_/g, " ") : "");
    const tzToUse = ev.tzid || tz || "UTC";
    const co = calOwnerCache[ev.calendar_id];
    const startStr = fmtTime(ev.dtstart);
    const endStr = ev.dtend ? fmtTime(ev.dtend) : '';
    const timeRange = endStr ? `${startStr}–${endStr}` : startStr;
    return {
      ...ev,
      title: ev.summary || "(untitled)",
      hostName: ev.group_name || ev.owner_display || co?.group_name || co?.owner_display_name || "",
      categoryLabel: ev.category ? ev.category.charAt(0).toUpperCase() + ev.category.slice(1) : "",
      range: fmtRangeLocal(ev.dtstart, ev.dtend, tzToUse),
      timeRange,
      partstatLabel: label,
      needsResponse: ev.partstat === "NEEDS-ACTION",
    };
  }), [sourceFiltered, tz, calOwnerCache]);

  // Resolve calendar owner info for permission checks and host labels
  useEffect(() => {
    (async () => {
      const missing = Array.from(new Set((mergedRows || []).map(r => r.calendar_id).filter(id => id && calOwnerCache[id] === undefined)));
      if (!missing.length) return;
      const entries = await Promise.all(missing.map(async (cid) => {
        try { const info = await getCalendarOwnerInfo(cid); return [cid, info || null]; } catch { return [cid, null]; }
      }));
      setCalOwnerCache(prev => ({ ...prev, ...Object.fromEntries(entries) }));
    })();
  }, [mergedRows]);

  const showCategoryFilter = availableCategories.length > 0;
  const formatDateKey = useCallback((iso) => {
    try {
      const d = new Date(iso);
      return d.toLocaleDateString(undefined, { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });
    } catch { return String(iso).slice(0,10); }
  }, []);

  const groupedByDate = useMemo(() => {
    const groups = new Map();
    for (const ev of displayEvents) {
      const key = formatDateKey(ev.dtstart);
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(ev);
    }
    return Array.from(groups.entries());
  }, [displayEvents, formatDateKey]);

  return (
    <div style={{ marginTop: 24 }}>
      <h3 style={{ margin: "0 0 8px", fontSize: 16 }}>Your Calendar</h3>
      <InfoText style={{ marginBottom: 12 }}>
        Shows events you&apos;re invited to or on the roster for, including accepted, pending, and declined.
      </InfoText>

      <Row style={{ gap: 12, flexWrap: "wrap" }}>
        <Label>
          Start
          <Input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} />
        </Label>
        <Label>
          End
          <Input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} />
        </Label>
        {showCategoryFilter && (
          <Label>
            Event type
            <Select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              style={{ minWidth: 200 }}
            >
              <option value="all">All event types</option>
              {availableCategories.map((c) => (
                <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>
              ))}
            </Select>
          </Label>
        )}
        <Label>
          Showing
          <Select
            value={sourceFilter}
            onChange={(e) => setSourceFilter(e.target.value)}
            style={{ minWidth: 220 }}
          >
            <option value="all">All events</option>
            <option value="individual">Events for you (individual)</option>
            {myGroups.map((g) => (
              <option key={g.id} value={g.id}>Events for {g.name || g.id}</option>
            ))}
          </Select>
        </Label>
        <Row style={{ gap: 8, alignItems: "flex-end" }}>
          <Button onClick={load} disabled={loading}>Refresh</Button>
          {loading && <span style={{ opacity: 0.7, fontSize: 12 }}>Loading…</span>}
        </Row>
      </Row>

      {err && <ErrorText style={{ marginTop: 12 }}>{err}</ErrorText>}

      {!err && !loading && displayEvents.length === 0 && (
        <p style={{ marginTop: 16, opacity: 0.75 }}>No invited events in this window.</p>
      )}

      <ul style={{ listStyle: "none", padding: 0, margin: 0, marginTop: 20 }}>
        {groupedByDate.map(([dateKey, rows]) => (
          <li key={dateKey} style={{ marginBottom: 22 }}>
            <div style={{
              fontSize: 18,
              fontWeight: 800,
              opacity: 0.98,
              margin: '10px 2px 12px',
              padding: '6px 8px',
              borderLeft: '3px solid rgba(255,255,255,0.35)'
            }}>{dateKey}</div>
            <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
              {rows.map((ev) => (
                <li
                  key={`${ev.event_id}-${ev.override_id || "base"}-${ev.event_slot_id || "series"}-${ev.__source || 'src'}-${ev.group_id || 'nogroup'}`}
                  style={{
                    border: "1px solid rgba(255,255,255,0.1)",
                    borderRadius: 10,
                    padding: 14,
                    marginBottom: 12,
                    display: "flex",
                    flexDirection: "column",
                    gap: 6,
                    background: ev.needsResponse ? "rgba(50,50,90,0.45)" : "rgba(15,15,20,0.45)",
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
                    <div style={{ fontWeight: 600, fontSize: 16 }}>
                      {ev.title}
                      {ev.event_status === 'CANCELLED' && <span style={{ marginLeft: 8, fontSize: 12, color: '#ff8585' }}>(Cancelled)</span>}
                    </div>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      {(() => {
                        const catValue = (ev.category || '').toLowerCase();
                        if (!catValue) return null;
                        const active = category !== 'all' && category === catValue;
                        return (
                          <button
                            onClick={() => setCategory(active ? 'all' : catValue)}
                            title={active ? 'Showing this event type; click to show all' : 'Filter to this event type'}
                            style={{
                              background: active ? 'rgba(255,255,255,0.18)' : 'transparent',
                              color: 'inherit',
                              border: '1px solid rgba(255,255,255,0.35)',
                              borderRadius: 10,
                              padding: '3px 8px',
                              fontSize: 12,
                              cursor: 'pointer',
                              textTransform: 'capitalize'
                            }}
                          >
                            {ev.categoryLabel}
                          </button>
                        );
                      })()}
                      {(() => {
                        const isIndividual = ev.__source !== 'group';
                        const label = isIndividual ? 'You' : (groupMeta[ev.group_id]?.name || 'Your team');
                        const value = isIndividual ? 'individual' : ev.group_id;
                        const active = sourceFilter === value;
                        return (
                          <button
                            onClick={() => setSourceFilter(active ? 'all' : value)}
                            title={active ? 'Showing only this; click to clear filter' : 'Filter to this context'}
                            style={{
                              background: active ? 'rgba(255,255,255,0.18)' : 'transparent',
                              color: 'inherit',
                              border: '1px solid rgba(255,255,255,0.35)',
                              borderRadius: 12,
                              padding: '3px 8px',
                              fontSize: 12,
                              cursor: 'pointer'
                            }}
                          >
                            {label}
                          </button>
                        );
                      })()}
                      {(() => {
                        const eventStatus = (ev.event_status || ev.status || 'TENTATIVE').toUpperCase();
                        const eventStatusLabel = eventStatus === 'CONFIRMED' ? 'Confirmed' : eventStatus === 'CANCELLED' ? 'Cancelled' : 'Tentative';
                        return (
                          <span style={{
                            border: '1px solid rgba(255,255,255,0.35)',
                            borderRadius: 10,
                            padding: '3px 8px',
                            fontSize: 12,
                            opacity: 0.9
                          }}>
                            {eventStatusLabel}
                          </span>
                        );
                      })()}
                    </div>
                  </div>
                    <div style={{ fontSize: 13, opacity: 0.9 }}>{ev.timeRange}</div>
                  {ev.location && (
                    <div style={{ fontSize: 13, opacity: 0.75 }}>📍 {ev.location}</div>
                  )}
                  {ev.hostName && (
                    <div style={{ fontSize: 14, fontWeight: 700, opacity: 0.95 }}>Hosted by {ev.hostName}</div>
                  )}
                  {ev.partstatLabel && (
                    <div style={{ fontSize: 12, opacity: 0.8 }}>
                      Invitation: {ev.partstatLabel}
                    </div>
                  )}
                  {ev.attendee_role && (
                    <div style={{ fontSize: 12, opacity: 0.7 }}>Attending as: {String(ev.attendee_role).toLowerCase()}</div>
                  )}
                  {ev.slot_name && (
                    <div style={{ fontSize: 12, opacity: 0.7 }}>Slot: {ev.slot_name}</div>
                  )}
                  {ev.description && (
                    <div style={{ fontSize: 12, opacity: 0.8, marginTop: 6 }}>{ev.description}</div>
                  )}
                  <Row style={{ justifyContent: 'flex-end' }}>
                    <GhostButton onClick={() => setOpenOverview({ eventId: ev.event_id, row: ev })}>
                      View Details
                    </GhostButton>
                    {(() => {
                      // Show manage actions only for owning group's rows and when user can manage
                      if (ev.__source !== 'group') return null;
                      const info = calOwnerCache[ev.calendar_id];
                      const ownerGroupId = info?.group_id || null;
                      if (!ownerGroupId || ownerGroupId !== ev.group_id) return null;
                      const role = groupRoles[ownerGroupId] || '';
                      const canManage = role === 'admin' || role === 'manager';
                      if (!canManage) return null;
                      const isSeries = !!ev.recurrence_id; // occurrence of a recurring series
                      return (
                        <>
                          <GhostButton onClick={() => onRequestManage(ownerGroupId, ev, 'event')}>
                            Manage event
                          </GhostButton>
                          {isSeries && (
                            <GhostButton onClick={() => onRequestManage(ownerGroupId, ev, 'series')}>
                              Manage series
                            </GhostButton>
                          )}
                        </>
                      );
                    })()}
                  </Row>
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ul>

      {openOverview && (
        <EventOverviewPanel
          eventId={openOverview.eventId}
          onClose={() => setOpenOverview(null)}
          // Keep public-friendly defaults for home
          hideJammers
          hideRunningOrder
          title={openOverview.row.summary || openOverview.row.title}
          description={openOverview.row.description}
          location={openOverview.row.location}
          dtstart={openOverview.row.dtstart}
          dtend={openOverview.row.dtend}
          tzid={openOverview.row.tzid || tz}
          status={openOverview.row.event_status || openOverview.row.status || 'TENTATIVE'}
          category={(openOverview.row.category || '').toLowerCase()}
          calendarId={openOverview.row.calendar_id || null}
        />
      )}
    </div>
  );
}

export default function Dashboard() {
  const { session, displayName, user } = useAuth();
  const { add: addToast } = useToast();
  const navigate = useNavigate();
  const [tab, setTab] = useState("home"); // 'home' | 'listings' | 'groups' | 'profile'
  const [notifs, setNotifs] = useState([]);
  const [notifsLoading, setNotifsLoading] = useState(true);
  const [notifsErr, setNotifsErr] = useState("");
  const [notifOverview, setNotifOverview] = useState(null); // { eventId, baseStart? }

  const loadNotifs = async () => {
    setNotifsErr(""); setNotifsLoading(true);
    try {
      const rows = await listMyOwnerNotifications();
      setNotifs(rows || []);
    } catch (e) { setNotifsErr(e.message || "Failed to load notifications"); }
    finally { setNotifsLoading(false); }
  };

  useEffect(() => { loadNotifs(); }, []);
  // Refresh when switching back to Home tab
  useEffect(() => { if (tab === 'home') loadNotifs(); }, [tab]);
  const [homeRefreshTick, setHomeRefreshTick] = useState(0);
  useEffect(() => { if (tab === 'home') setHomeRefreshTick((x)=>x+1); }, [tab]);

  // --- URL hash sync for top-level tab ("section") ---
  useEffect(() => {
    const applyHashSection = () => {
      try {
        const hash = (window.location.hash || '').replace(/^#/, '');
        if (!hash) return;
        const params = new URLSearchParams(hash);
        const section = params.get('section');
        const allowed = new Set(['home','listings','groups','community','profile']);
        if (section && allowed.has(section)) {
          setTab(section);
        } else if (params.get('team')) {
          // Back-compat: if a team is present, default to groups
          setTab('groups');
        }
      } catch {}
    };
    applyHashSection();
    const onHash = () => { applyHashSection(); };
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  const setSectionInHash = (section) => {
    try {
      const cur = (window.location.hash || '').replace(/^#/, '');
      const params = new URLSearchParams(cur);
      if (section) params.set('section', section); else params.delete('section');
      // Clear group-specific params when changing top-level section,
      // and also when explicitly clicking Groups tab (to show list by default).
      if (section !== 'groups') {
        params.delete('team');
        params.delete('event');
        params.delete('rid');
        params.delete('teamTab');
      } else {
        // If user clicked Groups tab from top, clear any deep-link
        params.delete('team');
        params.delete('event');
        params.delete('rid');
        params.delete('teamTab');
      }
      const newHash = params.toString();
      window.location.hash = newHash;
    } catch {}
  };

  return (
    <>
            <InvitedEventsSection
              refreshSignal={homeRefreshTick}
              onRequestManage={(groupId, ev, scope)=> {
                if (groupId) {
                  try {
                    const base = `/groups/${groupId}?tab=calendar`;
                    const params = new URLSearchParams();
                    params.set('tab', 'calendar');
                    const hash = new URLSearchParams();
                    hash.set('team', groupId);
                    hash.set('teamTab', 'calendar');
                    if (ev?.event_id) hash.set('event', ev.event_id);
                    if (scope === 'event' && ev?.recurrence_id) hash.set('rid', new Date(ev.recurrence_id).toISOString());
                    navigate(`${base}#${hash.toString()}`);
                  } catch {}
                }
              }}
            />
    </>
  );
}
