// src/listings/ListingsPanel.jsx
import { useCallback, useEffect, useMemo, useState } from "react";
import { Row, Label, Input, Button, ErrorText, InfoText, GhostButton } from "components/ui";
import IdPeek from "components/IdPeek";
import { listPublicEvents } from "teams/teams.api";
import { fmtRangeLocal, browserTZ } from "teams/utils/datetime";
import { useLocation, useNavigate } from "react-router-dom";

const EXCLUDED_CATEGORIES = new Set(["rehearsal", "social"]);

function toDateInputValue(date) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function toIsoStartOfDay(dateInput) {
  if (!dateInput) return null;
  const iso = new Date(`${dateInput}T00:00:00`).toISOString();
  return iso;
}

function toIsoEndOfDay(dateInput) {
  if (!dateInput) return null;
  const iso = new Date(`${dateInput}T23:59:59`).toISOString();
  return iso;
}

export default function ListingsPanel() {
  const navigate = useNavigate();
  const location = useLocation();
  const today = useMemo(() => new Date(), []);
  const defaultEnd = useMemo(() => {
    const next = new Date();
    next.setDate(next.getDate() + 30);
    return next;
  }, []);

  const [startDate, setStartDate] = useState(() => toDateInputValue(today));
  const [endDate, setEndDate] = useState(() => toDateInputValue(defaultEnd));
  const [category, setCategory] = useState("all");
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [availableCategories, setAvailableCategories] = useState([]);
  const tz = useMemo(() => browserTZ(), []);
  const [view, setView] = useState('agenda'); // 'agenda' | 'week' | 'month'
  const openEventRightPanel = (row) => {
    try {
      const sp = new URLSearchParams(location.search || '');
      // Clear other right-panel drivers so content cleanly replaces
      ['rpanel','team','group','user','create','tab','series'].forEach(k => sp.delete(k));
      sp.set('event', row.event_id);
      navigate(`/listings?${sp.toString()}`, { replace: true });
    } catch {}
  };

  // Helpers to align ranges for week/month and navigation
  const setWeekFromDate = useCallback((dateObj) => {
    try {
      const base = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
      const dow = base.getDay(); // 0=Sun..6=Sat
      const mondayDelta = ((dow + 6) % 7); // days back to Monday
      const ws = new Date(base); ws.setDate(base.getDate() - mondayDelta);
      const we = new Date(ws); we.setDate(ws.getDate() + 6);
      setStartDate(toDateInputValue(ws));
      setEndDate(toDateInputValue(we));
    } catch {}
  }, []);

  const setMonthFromDate = useCallback((dateObj) => {
    try {
      const first = new Date(dateObj.getFullYear(), dateObj.getMonth(), 1);
      const last = new Date(dateObj.getFullYear(), dateObj.getMonth() + 1, 0);
      setStartDate(toDateInputValue(first));
      setEndDate(toDateInputValue(last));
    } catch {}
  }, []);

  const load = useCallback(async () => {
    if (!startDate || !endDate) {
      setEvents([]);
      return;
    }
    if (startDate > endDate) {
      setErr("Start date must be on or before the end date.");
      setEvents([]);
      return;
    }

    setErr("");
    setLoading(true);
    try {
      const startIso = toIsoStartOfDay(startDate);
      const endIso = toIsoEndOfDay(endDate);
      const catParam = category === "all" ? null : category;
      const rows = await listPublicEvents(startIso, endIso, catParam);
      setEvents(rows || []);
      const cats = Array.from(new Set((rows || [])
        .map((r) => (r.category || "").toLowerCase())
        .filter((c) => c && !EXCLUDED_CATEGORIES.has(c))
      )).sort();
      setAvailableCategories(cats);
    } catch (e) {
      setErr(e.message || "Failed to load public listings.");
      setEvents([]);
    } finally {
      setLoading(false);
    }
  }, [startDate, endDate, category]);

  useEffect(() => { load(); }, [load]);

  // When switching to week/month, ensure the date range covers the visible window
  useEffect(() => {
    try {
      if (view === 'month') {
        const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
        setMonthFromDate(base);
      } else if (view === 'week') {
        const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
        setWeekFromDate(base);
      }
    } catch {}
  }, [view, setMonthFromDate, setWeekFromDate]);

  const displayEvents = useMemo(() => (events || []).map((ev) => {
    const hostName = ev.group_name || ev.owner_display || "";
    return {
      ...ev,
      title: ev.summary || "(untitled)",
      hostName,
      category: ev.category ? ev.category.charAt(0).toUpperCase() + ev.category.slice(1) : "",
      range: fmtRangeLocal(ev.dtstart, ev.dtend, ev.tzid || tz || "UTC"),
    };
  }), [events, tz]);

  const showCategoryFilter = availableCategories.length > 0;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16, marginTop: 16 }}>
        <InfoText style={{ marginBottom: 12 }}>
          Browse performances shared by teams on ImprovHub. Adjust the date range or filter by event type to find shows.
        </InfoText>

        <Row style={{ gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              className={`px-3 py-2 rounded-lg border ${view==='agenda' ? 'bg-white text-black border-white' : 'border-white/20 text-white hover:bg-white/10'}`}
              onClick={() => setView('agenda')}
            >Agenda</button>
            <button
              className={`px-3 py-2 rounded-lg border ${view==='week' ? 'bg-white text-black border-white' : 'border-white/20 text-white hover:bg-white/10'}`}
              onClick={() => setView('week')}
            >Weekly</button>
            <button
              className={`px-3 py-2 rounded-lg border ${view==='month' ? 'bg-white text-black border-white' : 'border-white/20 text-white hover:bg-white/10'}`}
              onClick={() => setView('month')}
            >Monthly</button>
          </div>
          {/* Navigation for week/month */}
          <div style={{ display:'flex', gap:8, alignItems:'center' }}>
            <button
              className="px-3 py-2 rounded-lg border border-white/20 hover:bg-white/10"
              onClick={() => {
                if (view === 'week') {
                  const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                  base.setDate(base.getDate() - 7);
                  setWeekFromDate(base);
                } else if (view === 'month') {
                  const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                  base.setMonth(base.getMonth() - 1);
                  setMonthFromDate(base);
                }
              }}
            >‹</button>
            <button
              className="px-3 py-2 rounded-lg border border-white/20 hover:bg-white/10"
              onClick={() => {
                if (view === 'week') setWeekFromDate(new Date());
                else if (view === 'month') setMonthFromDate(new Date());
              }}
            >Today</button>
            <button
              className="px-3 py-2 rounded-lg border border-white/20 hover:bg-white/10"
              onClick={() => {
                if (view === 'week') {
                  const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                  base.setDate(base.getDate() + 7);
                  setWeekFromDate(base);
                } else if (view === 'month') {
                  const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                  base.setMonth(base.getMonth() + 1);
                  setMonthFromDate(base);
                }
              }}
            >›</button>
            <div style={{ fontSize:12, opacity:0.8 }}>
              {(() => {
                try {
                  if (view === 'week') {
                    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                    const dow = base.getDay(); const mondayDelta = ((dow + 6) % 7);
                    const ws = new Date(base); ws.setDate(base.getDate() - mondayDelta);
                    const we = new Date(ws); we.setDate(ws.getDate() + 6);
                    return `${ws.toLocaleDateString(undefined, { month:'short', day:'numeric'})} – ${we.toLocaleDateString(undefined, { month:'short', day:'numeric'})}`;
                  }
                  if (view === 'month') {
                    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
                    return base.toLocaleDateString(undefined, { month:'long', year:'numeric' });
                  }
                } catch {}
                return '';
              })()}
            </div>
          </div>
        </Row>

        <Row style={{ gap: 12, flexWrap: "wrap" }}>
          <Label>
            Start
            <Input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} />
          </Label>
          <Label>
            End
            <Input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} />
          </Label>
          {showCategoryFilter && (
            <Label>
              Event type
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                style={{
                  background: "#0b0b0e",
                  color: "#ffffff",
                  border: "1px solid rgba(255,255,255,0.2)",
                  borderRadius: 10,
                  padding: "10px 12px",
                  outline: "none",
                  minWidth: 200,
                }}
              >
                <option value="all">All event types</option>
                {availableCategories.map((c) => (
                  <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>
                ))}
              </select>
            </Label>
          )}
          <Row style={{ gap: 8, alignItems: "flex-end" }}>
            <GhostButton onClick={load} disabled={loading}>Refresh</GhostButton>
            {view === 'agenda' && (
              <GhostButton onClick={() => { try { const t=new Date(); const pad=(n)=>String(n).padStart(2,'0'); const s=`${t.getFullYear()}-${pad(t.getMonth()+1)}-${pad(t.getDate())}`; const e=new Date(t); e.setDate(e.getDate()+30); const se=`${e.getFullYear()}-${pad(e.getMonth()+1)}-${pad(e.getDate())}`; setStartDate(s); setEndDate(se); setView('agenda'); } catch {} }}>Today</GhostButton>
            )}
            {loading && <span style={{ opacity: 0.7, fontSize: 12 }}>Loading…</span>}
          </Row>
        </Row>

        {err && <ErrorText style={{ marginTop: 12 }}>{err}</ErrorText>}

        {!err && !loading && displayEvents.length === 0 && (
          <p style={{ marginTop: 16, opacity: 0.75 }}>No public events found for the selected dates.</p>
        )}

        {/* Views */}
        {view === 'agenda' && (
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(260px, 1fr))', gap:12, marginTop:24 }}>
            {displayEvents.map((ev) => (
              <div
                key={ev.event_id}
                role="button"
                tabIndex={0}
                onClick={() => openEventRightPanel(ev)}
                onKeyDown={(e)=> { if (e.key==='Enter') openEventRightPanel(ev); }}
                style={{
                  border: "1px solid rgba(255,255,255,0.12)",
                  borderRadius: 10,
                  padding: 14,
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                  background: "rgba(18,18,22,0.45)",
                  cursor: 'pointer',
                  minHeight: 140,
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
                  <div style={{ fontWeight: 600, fontSize: 16, lineHeight:1.2 }}>{ev.title}</div>
                  <div style={{ display:'flex', gap:6, alignItems:'center' }}>
                    {ev.category && (
                      <button
                        title={`Filter by ${ev.category}`}
                        onClick={(e)=> { e.stopPropagation(); const next=(category===String(ev.category||'').toLowerCase()? 'all' : String(ev.category||'').toLowerCase()); setCategory(next); }}
                        style={{ fontSize: 12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity: category===String(ev.category||'').toLowerCase()? 1 : 0.7, background: category===String(ev.category||'').toLowerCase()? 'rgba(255,255,255,0.2)' : 'transparent' }}
                      >{ev.category}</button>
                    )}
                    {ev.hostName && (
                      <span title="Calendar" style={{ fontSize:12, padding:'2px 6px', borderRadius:999, border:'1px solid rgba(255,255,255,0.35)', opacity:0.75 }}>{ev.hostName}</span>
                    )}
                  </div>
                </div>
                <div style={{ fontSize: 13, opacity: 0.85 }}>{ev.range}</div>
                {ev.location && (
                  <div style={{ fontSize: 13, opacity: 0.75 }}>📍 {ev.location}</div>
                )}
                {ev.hostName && (
                  <div style={{ fontSize: 12, opacity: 0.7 }}>
                    Hosted by {ev.hostName}
                    {ev.owner_id && <IdPeek id={ev.owner_id} />}
                  </div>
                )}
                {ev.description && (
                  <div style={{ fontSize: 12, opacity: 0.8, marginTop: 'auto' }}>{ev.description}</div>
                )}
              </div>
            ))}
          </div>
        )}

        {view === 'week' && (
          <WeekGrid
            events={displayEvents}
            tz={tz}
            onOpen={(item)=> openEventRightPanel(item)}
            startDate={startDate}
            onPickDay={(dateObj) => {
              try {
                const d = new Date(dateObj.getFullYear(), dateObj.getMonth(), dateObj.getDate());
                const pad = (n)=> String(n).padStart(2,'0');
                const s = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
                setStartDate(s);
                setEndDate(s);
                setView('agenda');
              } catch {}
            }}
          />
        )}

        {view === 'month' && (
          <MonthGrid
            events={displayEvents}
            tz={tz}
            onOpen={(item)=> openEventRightPanel(item)}
            startDate={startDate}
            onPickDay={(dateObj) => { try { setView('week'); setWeekFromDate(dateObj); } catch {} }}
          />
        )}

        {/* Event details are shown in the right panel via `event` query param; no popup here. */}
    </div>
  );
}

function WeekGrid({ events, tz, onOpen, startDate, onPickDay }) {
  try {
    const today = new Date();
    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
    const dow = base.getDay();
    const mondayDelta = ((dow + 6) % 7);
    const ws = new Date(base); ws.setDate(base.getDate() - mondayDelta);
    const days = Array.from({ length: 7 }, (_, i) => new Date(ws.getFullYear(), ws.getMonth(), ws.getDate() + i));
    const byDay = days.map(d => ({ date: d, items: [] }));
    (events || []).forEach(ev => {
      try {
        const d = new Date(ev.dtstart);
        if (isNaN(+d)) return;
        const idx = Math.floor((d - ws) / (24*3600*1000));
        if (idx >=0 && idx < 7) byDay[idx].items.push(ev);
      } catch {}
    });
    const rowHeight = 40; // px per hour
    const hourLabels = Array.from({ length: 24 }, (_, h) => `${String(h).padStart(2,'0')}:00`);
    return (
      <div style={{ marginTop: 16 }}>
        <div style={{ display:'grid', gridTemplateColumns:'60px repeat(7, 1fr)', gap:0, marginBottom:6 }}>
          <div />
          {byDay.map((col, i) => (
            <div key={`hdr-${i}`} style={{ textAlign:'center', fontWeight:600, fontSize:12, opacity:0.9, padding:'4px 0' }}
                 title="View agenda for this day"
                 onClick={() => onPickDay && onPickDay(col.date)}
            >
              {col.date.toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric' })}
            </div>
          ))}
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'60px repeat(7, 1fr)', gap:0 }}>
          <div style={{ position:'relative', height: rowHeight*24, border:'1px solid rgba(255,255,255,0.1)' }}>
            {hourLabels.map((label, i) => (
              <div key={i} style={{ position:'absolute', top: i*rowHeight - 6, left: 6, fontSize:10, opacity:0.7 }}>{label}</div>
            ))}
          </div>
          {byDay.map((col, i) => {
            const isToday = col.date.toDateString() === today.toDateString();
            return (
              <div key={i}
                style={{
                  position:'relative',
                  height: rowHeight*24,
                  border:'1px solid rgba(255,255,255,0.1)',
                  background: `repeating-linear-gradient(to bottom, rgba(255,255,255,0.06) 0, rgba(255,255,255,0.06) 1px, transparent 1px, transparent ${rowHeight}px)${isToday ? ', rgba(255,255,255,0.06)' : ''}`,
                  overflow:'hidden',
                }}
              >
                {col.items.map(item => {
                  const start = new Date(item.dtstart);
                  if (isNaN(+start)) return null;
                  const end = item.dtend ? new Date(item.dtend) : new Date(start.getTime() + 60*60*1000);
                  const startMinutes = start.getHours()*60 + start.getMinutes();
                  const endMinutes = end.getHours()*60 + end.getMinutes();
                  const top = (startMinutes/60)*rowHeight;
                  const height = Math.max(24, ((endMinutes - startMinutes)/60)*rowHeight);
                  return (
                    <div key={item.event_id}
                         onClick={()=> onOpen(item)}
                         role="button" tabIndex={0}
                         onKeyDown={(e)=> { if (e.key==='Enter') onOpen(item); }}
                         style={{ position:'absolute', left:6, right:6, top, height, border:'1px solid rgba(255,255,255,0.2)', borderRadius:8, background:'rgba(255,255,255,0.06)', padding:'6px 8px', cursor:'pointer' }}>
                      <div style={{ fontSize:12, fontWeight:600, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{item.title}</div>
                      <div style={{ fontSize:11, opacity:0.85 }}>{start.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })} – {end.toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}</div>
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
    );
  } catch { return null; }
}

function MonthGrid({ events, tz, onOpen, startDate, onPickDay }) {
  try {
    const today = new Date();
    const base = startDate ? new Date(`${startDate}T00:00:00`) : today;
    const y = base.getFullYear(); const m = base.getMonth();
    const first = new Date(y, m, 1);
    const last = new Date(y, m + 1, 0);
    const startDow = (first.getDay() + 6) % 7; // 0=Mon..6=Sun
    const daysInMonth = last.getDate();
    const totalCells = Math.ceil((startDow + daysInMonth) / 7) * 7;
    const startDateGrid = new Date(y, m, 1 - startDow);
    const cells = Array.from({ length: totalCells }, (_, i) => new Date(startDateGrid.getFullYear(), startDateGrid.getMonth(), startDateGrid.getDate() + i));
    const byDateIso = new Map();
    (events || []).forEach(ev => {
      try {
        const d = new Date(ev.dtstart);
        if (isNaN(+d)) return;
        const key = d.toISOString().slice(0,10);
        const arr = byDateIso.get(key) || []; arr.push(ev); byDateIso.set(key, arr);
      } catch {}
    });
    const dayNames = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
    const gridLine = 'rgba(255,255,255,0.1)';
    return (
      <div style={{ marginTop: 16 }}>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(7, 1fr)', gap:1, marginBottom:6, background: gridLine }}>
          {dayNames.map((dn) => (
            <div key={dn} style={{ textAlign:'center', fontWeight:600, fontSize:12, opacity:0.85, background:'transparent', padding:'4px 0' }}>{dn}</div>
          ))}
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(7, 1fr)', gap:1, background: gridLine }}>
          {cells.map((d, i) => {
            const inMonth = d.getMonth() === m;
            const key = d.toISOString().slice(0,10);
            const items = byDateIso.get(key) || [];
            const isToday = d.toDateString() === today.toDateString();
            return (
            <div key={i} style={{ border:'none', borderRadius:0, padding:6, background: inMonth ? (isToday ? 'rgba(255,255,255,0.06)' : 'transparent') : 'rgba(255,255,255,0.03)' }}>
              <div
                style={{ fontWeight:600, fontSize:12, opacity:0.85, marginBottom:6, cursor:'pointer' }}
                title="View this week"
                onClick={() => onPickDay && onPickDay(d)}
              >
                {d.getDate()}
              </div>
              <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:4 }}>
                  {items.length === 0 ? (
                    <li style={{ opacity:0.6, fontSize:12 }}>No events</li>
                  ) : items.map(item => (
                    <li key={item.event_id}
                        onClick={()=> onOpen(item)}
                        role="button" tabIndex={0}
                        onKeyDown={(e)=> { if (e.key==='Enter') onOpen(item); }}
                      style={{ border:'1px solid rgba(255,255,255,0.1)', borderRadius:6, padding:'4px 6px', cursor:'pointer' }}>
                      <div style={{ fontSize:12, fontWeight:600, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{item.title}</div>
                      <div style={{ fontSize:11, opacity:0.8 }}>{new Date(item.dtstart).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}</div>
                    </li>
                  ))}
                </ul>
              </div>
          );
        })}
        </div>
      </div>
    );
  } catch { return null; }
}
