import { useEffect, useState } from 'react';
import { Button, Input, Label, InfoText, ErrorText } from 'components/ui';
import { createTeam, updateGroupDisplayId, updateGroupProfile, updateGroupTypes, updateGroupPublicListing } from 'teams/teams.api';
import { useNavigate } from 'react-router-dom';

const TYPE_META = {
  act: { label: 'Act' },
  practice_group: { label: 'Practice Group' },
  school: { label: 'School' },
  theatre: { label: 'Theatre' },
  producer: { label: 'Producer' },
};

const MUTUALLY_EXCLUSIVE = { act: ['practice_group'], practice_group: ['act'], producer: ['theatre'], theatre: ['producer'] };

function normalizeTypes(values = []) {
  const set = new Set();
  (Array.isArray(values) ? values : []).forEach((key) => {
    if (!TYPE_META[key]) return;
    const conflicts = MUTUALLY_EXCLUSIVE[key] || [];
    conflicts.forEach((c) => set.delete(c));
    set.add(key);
  });
  return Array.from(set);
}

export default function CreateGroupPanel() {
  const navigate = useNavigate();
  const [draft, setDraft] = useState({ name: '', displayId: '', website: '', bio: '', types: [], publicListing: false });
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState('');
  const [err, setErr] = useState('');

  const canSubmit = (draft.name || '').trim() && (draft.displayId || '').trim();

  const submit = async () => {
    if (!canSubmit || saving) return;
    const name = (draft.name || '').trim();
    const displayId = (draft.displayId || '').trim();
    if (!/^[a-zA-Z0-9_-]+$/.test(displayId)) { setErr('Unique ID may only contain letters, numbers, dashes and underscores.'); return; }
    setSaving(true); setErr(''); setMsg('');
    try {
      const team = await createTeam(name);
      const types = normalizeTypes(draft.types || []);
      if (displayId) { try { await updateGroupDisplayId(team.id, displayId); } catch {}
      }
      if (draft.website || draft.bio) { try { await updateGroupProfile(team.id, { website: draft.website, bio: draft.bio }); } catch {} }
      if (types.length) { try { await updateGroupTypes(team.id, types); } catch {} }
      if (draft.publicListing) { try { await updateGroupPublicListing(team.id, true); } catch {} }
      setMsg('Group created.');
      navigate(`/groups/${team.id}`);
    } catch (e) {
      setErr(e.message || 'Failed to create group');
    } finally { setSaving(false); }
  };

  return (
    <div>
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom: 8 }}>
        <div style={{ fontWeight: 700 }}>Create group</div>
        <Button onClick={() => navigate('/groups')} style={{ padding: '6px 10px' }}>Close</Button>
      </div>
      {msg && <InfoText style={{ marginBottom: 8 }}>{msg}</InfoText>}
      {err && <ErrorText style={{ marginBottom: 8 }}>{err}</ErrorText>}
      <div style={{ display:'grid', gap: 12 }}>
        <Label>
          Name (required)
          <Input value={draft.name} onChange={(e)=> setDraft(prev => ({ ...prev, name: e.target.value }))} placeholder="Group name" />
        </Label>
        <Label>
          Unique ID (required)
          <Input value={draft.displayId} onChange={(e)=> setDraft(prev => ({ ...prev, displayId: e.target.value }))} placeholder="e.g. my-group" maxLength={32} />
        </Label>
        <Label>
          Website (optional)
          <Input value={draft.website} onChange={(e)=> setDraft(prev => ({ ...prev, website: e.target.value }))} placeholder="example.org" />
        </Label>
        <Label>
          Bio (optional)
          <Input value={draft.bio} onChange={(e)=> setDraft(prev => ({ ...prev, bio: e.target.value }))} placeholder="A short description" />
        </Label>
        <div>
          <div style={{ marginBottom: 6, opacity: 0.9, fontWeight: 600 }}>Types</div>
          <div style={{ display:'flex', gap: 10, flexWrap:'wrap' }}>
            {Object.keys(TYPE_META).map((k) => (
              <label key={k} style={{ display:'inline-flex', alignItems:'center', gap: 6 }}>
                <input type="checkbox" checked={draft.types.includes(k)} onChange={(e)=> setDraft(prev => ({ ...prev, types: normalizeTypes(e.target.checked ? [...prev.types, k] : prev.types.filter(x => x !== k)) }))} />
                <span>{TYPE_META[k].label}</span>
              </label>
            ))}
          </div>
        </div>
        <label style={{ display:'inline-flex', alignItems:'center', gap: 6 }}>
          <input type="checkbox" checked={!!draft.publicListing} onChange={(e)=> setDraft(prev => ({ ...prev, publicListing: !!e.target.checked }))} />
          <span>Public listing</span>
        </label>
        <div>
          <Button disabled={!canSubmit || saving} onClick={submit}>{saving ? 'Creating…' : 'Create group'}</Button>
        </div>
      </div>
    </div>
  );
}

