import { useEffect, useState } from 'react';
import { useParams, useNavigate, useLocation } from 'react-router-dom';
import { getEventById, listOverridesForEvents } from 'teams/teams.api';
import EventOverviewPanel from 'eventui/EventOverviewPanel';
import SeriesOverviewPanel from 'eventui/SeriesOverviewPanel';

export default function EventPanel() {
  const { eventId: paramEventId, rid: paramRid } = useParams();
  const location = useLocation();
  const sp = new URLSearchParams(location.search || '');
  const eventId = paramEventId || sp.get('event');
  const rawRid = paramRid || sp.get('rid');
  const seriesMode = sp.get('series') === '1' || sp.get('series') === 'true';
  let rid = rawRid;
  try { if (typeof rawRid === 'string') rid = decodeURIComponent(rawRid); } catch {}
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [event, setEvent] = useState(null);
  const [override, setOverride] = useState(null);

  useEffect(() => {
    let active = true;
    (async () => {
      setLoading(true);
      try {
        const ev = await getEventById(eventId);
        if (!active) return;
        setEvent(ev);
        if (rid) {
          const rows = await listOverridesForEvents([eventId], null, null);
          if (!active) return;
          const match = (rows || []).find(r => new Date(r.recurrence_id).toISOString() === new Date(rid).toISOString());
          setOverride(match || null);
        } else {
          setOverride(null);
        }
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [eventId, rid]);

  const resolved = (() => {
    if (!event) return null;
    const ov = override || {};
    // Prefer occurrence start when rid provided; derive end from series duration if needed
    const ridIso = (() => { try { return rawRid ? new Date(rawRid).toISOString() : null; } catch { return null; } })();
    const baseStartIso = event.dtstart || null;
    const baseEndIso = event.dtend || null;
    let occEnd = null;
    try {
      if (ridIso && baseStartIso && baseEndIso) {
        const durMs = new Date(baseEndIso).getTime() - new Date(baseStartIso).getTime();
        if (isFinite(durMs) && durMs > 0) occEnd = new Date(new Date(ridIso).getTime() + durMs).toISOString();
      }
    } catch {}
    return {
      title: ov.summary || event.summary || '',
      description: ov.description || event.description || '',
      location: ov.location || event.location || '',
      dtstart: ov.dtstart || ridIso || event.dtstart,
      dtend: ov.dtend || occEnd || event.dtend,
      tzid: ov.tzid || event.tzid || 'UTC',
      status: ov.status || event.status || 'TENTATIVE',
      category: (event.extended?.category || (Array.isArray(event.categories) && event.categories[0]) || '').toLowerCase(),
      calendarId: event.calendar_id || null,
    };
  })();

  // Determine whether there are actual override fields (beyond just the row existing)
  const hasRealOverride = (() => {
    try {
      const ov = override || null;
      if (!ov) return false;
      const primitiveFields = [
        ov.summary, ov.description, ov.location, ov.status,
        ov.dtstart, ov.dtend, ov.tzid, ov.duration_sec, ov.all_day, ov.transparency,
      ];
      if (primitiveFields.some(v => v !== null && v !== undefined)) return true;
      if (Array.isArray(ov.categories) && ov.categories.length > 0) return true;
      if (ov.extended && typeof ov.extended === 'object' && Object.keys(ov.extended || {}).length > 0) return true;
      return false;
    } catch { return false; }
  })();

  const isRecurring = (() => {
    try {
      const rr = String(event?.rrule || '').toUpperCase();
      return rr.includes('FREQ=') && !rr.includes('FREQ=NONE');
    } catch { return false; }
  })();

  const onClose = () => {
    try {
      const sp2 = new URLSearchParams(location.search || '');
      sp2.delete('event');
      sp2.delete('rid');
      sp2.delete('series');
      const q = sp2.toString();
      navigate(`${location.pathname}${q ? `?${q}` : ''}`, { replace: true });
    } catch {
      navigate(-1);
    }
  };

  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (!resolved) return <div style={{ opacity: 0.75 }}>Event not found.</div>;

  if (seriesMode) {
    return (
      <SeriesOverviewPanel
        eventId={eventId}
        onClose={onClose}
        inline
      />
    );
  }

  return (
    <EventOverviewPanel
      eventId={eventId}
      baseStart={rid || null}
      hasOverride={hasRealOverride}
      overrideExists={!!override}
      isRecurring={isRecurring}
      onClose={onClose}
      title={resolved.title}
      description={resolved.description}
      location={resolved.location}
      dtstart={resolved.dtstart}
      dtend={resolved.dtend}
      tzid={resolved.tzid}
      status={resolved.status}
      category={resolved.category}
      calendarId={resolved.calendarId}
      inline
    />
  );
}
