import React, { createContext, useContext, useCallback, useState } from 'react';

const ToastCtx = createContext({ add: () => {} });

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const add = useCallback((msg, kind = 'info', ttl = 3000) => {
    const id = Math.random().toString(36).slice(2);
    setToasts((ts) => [...ts, { id, msg, kind }]);
    if (ttl > 0) setTimeout(() => setToasts((ts) => ts.filter(t => t.id !== id)), ttl);
  }, []);
  const remove = useCallback((id) => setToasts((ts) => ts.filter(t => t.id !== id)), []);
  return (
    <ToastCtx.Provider value={{ add }}>
      {children}
      <div style={{ position: 'fixed', top: 12, left: '50%', transform: 'translateX(-50%)', display: 'grid', gap: 8, zIndex: 2000, alignItems: 'center', justifyItems: 'center' }}>
        {toasts.map(t => (
          <div key={t.id} onClick={() => remove(t.id)} style={{ cursor: 'pointer', background: 'rgba(20,20,26,0.95)', border: '1px solid rgba(255,255,255,0.15)', borderRadius: 8, padding: '8px 12px', minWidth: 220 }}>
            <div style={{ fontWeight: 600, marginBottom: 2 }}>{t.kind === 'error' ? 'Error' : 'Info'}</div>
            <div>{t.msg}</div>
          </div>
        ))}
      </div>
    </ToastCtx.Provider>
  );
}

export function useToast() {
  return useContext(ToastCtx);
}
