import { useEffect, useMemo, useState } from 'react';
import { useAuth } from 'auth/AuthContext';
import { listGroupOwnerNotifications, listGroupOutgoingInvites, dismissOwnerNotification, respondAnyOwnerNotification, cancelGroupInvite, listMyTeams, listTeamMembersRPC } from 'teams/teams.api';
import { GhostButton, Button, ErrorText } from 'components/ui';

export default function RightPanelUpdates({ groupId }) {
  const { user } = useAuth();
  const currentUserId = user?.id || null;
  const [team, setTeam] = useState(null);
  const [members, setMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');

  useEffect(() => {
    let active = true;
    setLoading(true); setErr('');
    (async () => {
      try {
        const list = await listMyTeams();
        const t = (list || []).find(x => String(x.id) === String(groupId));
        if (!active) return;
        setTeam(t || null);
        if (t) {
          try { const mem = await listTeamMembersRPC(t.id); if (active) setMembers(mem || []); } catch {}
        }
      } catch (e) { if (active) setErr(e.message || 'Failed to load group'); }
      finally { if (active) setLoading(false); }
    })();
    return () => { active = false; };
  }, [groupId]);

  const isAdmin = useMemo(() => {
    const me = (members || []).find(m => m.user_id === currentUserId);
    return (me?.role || '').toLowerCase() === 'admin';
  }, [members, currentUserId]);

  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (err) return <div style={{ color:'#ff6b6b' }}>{err}</div>;
  if (!team) return <div style={{ opacity: 0.75 }}>Group not found.</div>;

  return (
    <div className="grid gap-3">
      <div>
        <div style={{ fontWeight: 700, marginBottom: 6 }}>Group Notifications</div>
        <div className="border border-white/10 rounded-xl p-3 bg-card/70">
          <GroupNotifications groupId={team.id} />
        </div>
      </div>
      <div>
        <div style={{ fontWeight: 700, marginBottom: 6 }}>Outgoing Invites</div>
        <div className="border border-white/10 rounded-xl p-3 bg-card/70">
          <GroupOutgoingInvites groupId={team.id} isAdmin={isAdmin} />
        </div>
      </div>
    </div>
  );
}

function GroupNotifications({ groupId }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');
  const load = async () => {
    setErr(''); setLoading(true);
    try { const r = await listGroupOwnerNotifications(groupId); setRows(r || []); }
    catch (e) { setErr(e.message || 'Failed to load notifications'); }
    finally { setLoading(false); }
  };
  useEffect(() => {
    let active = true;
    (async () => { if (active) await load(); })();
    return () => { active = false; };
  }, [groupId]);
  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (err) return <ErrorText>{err}</ErrorText>;
  if (!rows.length) return <div style={{ opacity: 0.8 }}>No notifications.</div>;
  return (
    <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:8 }}>
      {rows.map(n => (
        <li key={n.id} style={{ border:'1px solid rgba(255,255,255,0.12)', borderRadius:10, padding:10 }}>
          <div style={{ fontWeight:600 }}>{n.title || (n.type === 'ack' ? 'Action required' : 'Notification')}</div>
          {n.body && <div style={{ opacity:0.85, marginTop:2 }}>{n.body}</div>}
          <div style={{ opacity:0.7, fontSize:12 }}>{new Date(n.created_at).toLocaleString()}</div>
          <div style={{ display:'flex', gap:8, marginTop:8 }}>
            {(() => {
              const ack = n.type === 'ack' && !n.ack_response;
              if (ack) {
                return (
                  <>
                    <GhostButton onClick={async ()=> { await respondAnyOwnerNotification(n, 'yes'); await load(); }}>Yes</GhostButton>
                    <GhostButton onClick={async ()=> { await respondAnyOwnerNotification(n, 'no'); await load(); }}>No</GhostButton>
                  </>
                );
              }
              return (
                <GhostButton onClick={async ()=> { await dismissOwnerNotification(n.id); await load(); }}>Dismiss</GhostButton>
              );
            })()}
          </div>
        </li>
      ))}
    </ul>
  );
}

function GroupOutgoingInvites({ groupId }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');
  const load = async () => {
    setErr(''); setLoading(true);
    try { const r = await listGroupOutgoingInvites(groupId); setRows(r || []); }
    catch (e) { setErr(e.message || 'Failed to load invites'); }
    finally { setLoading(false); }
  };
  useEffect(() => {
    let active = true;
    (async () => { if (active) await load(); })();
    return () => { active = false; };
  }, [groupId]);
  if (loading) return <div style={{ opacity: 0.75 }}>Loading…</div>;
  if (err) return <ErrorText>{err}</ErrorText>;
  if (!rows.length) return <div style={{ opacity: 0.8 }}>No pending invites.</div>;
  return (
    <ul style={{ listStyle:'none', padding:0, margin:0, display:'grid', gap:8 }}>
      {rows.map(n => (
        <li key={n.id} style={{ border:'1px solid rgba(255,255,255,0.12)', borderRadius:10, padding:10 }}>
          <div style={{ fontWeight:600 }}>{(() => { const p=n?.payload||{}; return `Invitation to ${p.target_owner_name || p.target_user_name || p.target_user_email || 'Recipient'}`; })()}</div>
          <div style={{ opacity:0.7, fontSize:12 }}>{new Date(n.created_at).toLocaleString()}</div>
          <div style={{ marginTop:8 }}>
            <GhostButton onClick={async ()=> { try { await cancelGroupInvite(n.id); await load(); } catch {} }}>Cancel invite</GhostButton>
          </div>
        </li>
      ))}
    </ul>
  );
}
